// ║  All avatars are professionally illustrated SVGs ║
// ║  served from avataaars.io via URL parameters.    ║
// ╚══════════════════════════════════════════════════╝

const AVATAAARS_BASE = 'https://avataaars.io/';

const AVATAR_DEFAULTS = {
  avatarStyle:     'Transparent',
  topType:         'ShortHairShortFlat',
  accessoriesType: 'Blank',
  hairColor:       'BrownDark',
  facialHairType:  'Blank',
  facialHairColor: 'BrownDark',
  clotheType:      'Hoodie',
  clotheColor:     'Red',
  graphicType:     'Bat',
  eyeType:         'Default',
  eyebrowType:     'Default',
  mouthType:       'Smile',
  skinColor:       'Light',
  bgColor:         '#1a2e3a'
};

// Build the avataaars.io URL from a config object
// avatarStyle=Transparent removes the circle background
function buildAvatarUrl(cfg) {
  const c = Object.assign({}, AVATAR_DEFAULTS, cfg);
  const params = [
    'topType', 'accessoriesType', 'hairColor',
    'facialHairType', 'facialHairColor', 'clotheType', 'clotheColor',
    'graphicType', 'eyeType', 'eyebrowType', 'mouthType', 'skinColor'
  ].map(k => `${k}=${encodeURIComponent(c[k])}`).join('&');
  // avatarStyle=Transparent = no circle, no bg — just the character
  return AVATAAARS_BASE + '?avatarStyle=Transparent&' + params;
}

// Returns an <img> tag for the avatar (profile page — bottom-aligned in hero)
function buildAvatarImg(cfg, size = 160) {
  const url = buildAvatarUrl(cfg);
  return `<img src="${url}" width="${size}" height="${size}"
    style="display:block;margin-bottom:-2px;object-fit:contain;object-position:bottom;"
    onerror="this.style.opacity='.4'"
    alt="Avatar">`;
}

// Returns a small <img> for style picker grids
function buildThumbImg(cfg, overrides = {}) {
  const merged = Object.assign({}, AVATAR_DEFAULTS, cfg, overrides);
  const url = buildAvatarUrl(merged);
  return `<img src="${url}" width="64" height="64" style="display:block;" alt="">`;
}

function getAvatarConfig(userId) {
  const saved = db?.submissions?.[userId]?.avatar;
  return Object.assign({}, AVATAR_DEFAULTS, saved || {});
}

// Save avatar config to Firebase
async function saveAvatar(config) {
  if (!currentUser || !db) return;
  const id = currentUser.id;
  if (!db.submissions[id]) db.submissions[id] = {};
  db.submissions[id].avatar = config;
  try {
    await fbPatch(`submissions/${id}/avatar`, config);
    showToast('✓', 'Avatar saved!');
  } catch(e) { showToast('✕', 'Save failed'); }
}

