function openChangePasswordModal() {
  openModal(`
    <div style="padding:4px 0;">
      <div style="font-size:16px;font-weight:700;color:var(--text);margin-bottom:16px;">Change Password</div>
      <div class="form-group"><label>Current Password</label><input type="password" id="cpCurrent" placeholder="Current password"></div>
      <div class="form-group"><label>New Password</label><input type="password" id="cpNew" placeholder="New password (min 6 chars)"></div>
      <div class="form-group" style="margin-bottom:4px;"><label>Confirm New</label><input type="password" id="cpConfirm" placeholder="Confirm new password"></div>
      <div class="error-msg" id="cpError" style="display:none;margin-bottom:8px;"></div>
      <div class="modal-actions">
        <button class="btn btn-secondary" onclick="closeModal()">Cancel</button>
        <button class="btn btn-primary" onclick="doChangePassword()">Update</button>
      </div>
    </div>`);
}

async function doChangePassword() {
  const cur = document.getElementById('cpCurrent')?.value || '';
  const nw  = document.getElementById('cpNew')?.value || '';
  const cf  = document.getElementById('cpConfirm')?.value || '';
  const errEl = document.getElementById('cpError');
  const showErr = msg => { if(errEl){errEl.textContent=msg;errEl.style.display='block';} };
  if (!cur || !nw || !cf) { showErr('Please fill all fields.'); return; }
  if (nw.length < 6) { showErr('New password must be at least 6 characters.'); return; }
  if (nw !== cf) { showErr('Passwords do not match.'); return; }
  // Verify current password
  const curHash = await sha256(cur);
  const uid = currentUser.id;
  const storedHash = db.submissions?.[uid]?.passwordHash || INTERN_HASHES[uid];
  if (curHash !== storedHash) { showErr('Current password is incorrect.'); return; }
  // Save new hash
  const newHash = await sha256(nw);
  if (!db.submissions[uid]) db.submissions[uid] = {};
  db.submissions[uid].passwordHash = newHash;
  try {
    await fbPatch(`submissions/${uid}/passwordHash`, newHash);
    closeModal();
    showToast('✓', 'Password updated!');
  } catch(e) { showErr('Save failed. Try again.'); }
}

