// ── Intern Status Detail page ───────────────────────────
function openInternStatusDetail() {
  const id      = currentUser.id;
  const todayStr = typeof today === 'function' ? today() : new Date().toISOString().split('T')[0];
  const todayDate = new Date(todayStr + 'T00:00:00');

  // Get all tasks for this intern
  const myTasks = db.tasks.filter(t =>
    (t.assignedTo === id || (t.isPersonal && t.createdBy === id)) && !t.isTemplate
  );

  // Classify
  const isTodo    = t => !isTaskDone(t.id, id) && !isTaskInProgress(t.id, id) && !(t.dueDate && new Date(t.dueDate + 'T00:00:00') < todayDate);
  const isReview  = t => !isTaskDone(t.id, id) && isTaskInProgress(t.id, id);
  const isDone    = t => isTaskDone(t.id, id);
  const isOverdue = t => !isTaskDone(t.id, id) && t.dueDate && new Date(t.dueDate + 'T00:00:00') < todayDate;

  const total    = myTasks.length;
  const nTodo    = myTasks.filter(isTodo).length;
  const nReview  = myTasks.filter(isReview).length;
  const nDone    = myTasks.filter(isDone).length;
  const nOverdue = myTasks.filter(isOverdue).length;
  const tsMax    = Math.max(total, nTodo, nReview, nDone, nOverdue, 1);

  const barH = (n) => Math.max(8, Math.round((n / tsMax) * 100));

  const bars = [
    { n: total,   color: '#6366f1', label: 'All',        icon: 'layers',         key: 'All'      },
    { n: nTodo,   color: '#3b82f6', label: 'To Do',      icon: 'circle',         key: 'Todo'     },
    { n: nReview, color: '#f59e0b', label: 'In Review',  icon: 'eye',            key: 'InReview' },
    { n: nDone,   color: '#22c55e', label: 'Completed',  icon: 'check-circle',   key: 'Done'     },
    { n: nOverdue,color: '#ef4444', label: 'Overdue',    icon: 'alert-triangle', key: 'Overdue'  },
  ];

  // Create full-screen overlay
  document.getElementById('internStatusSheet')?.remove();
  const sheet = document.createElement('div');
  sheet.id = 'internStatusSheet';
  sheet.innerHTML = `
    <div class="ist-backdrop" onclick="document.getElementById('internStatusSheet')?.remove()"></div>
    <div class="ist-sheet" id="istSheetInner">
      <div class="ist-handle"></div>

      <!-- Header -->
      <div class="ist-header">
        <div class="ist-title">Status <span style="color:var(--accent);font-size:22px;line-height:1;">+</span></div>
        <button class="ist-close" onclick="document.getElementById('internStatusSheet')?.remove()">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
        </button>
      </div>

      <!-- Bar chart -->
      <div class="ist-chart-wrap">
        <div class="task-chart-bars" style="height:200px;">
          ${bars.map(b => `
            <div class="task-chart-bar" style="height:${barH(b.n)}%;background:${b.color};cursor:pointer;"
              onclick="istFilter('${b.key}')">
              <div class="task-bar-value">${b.n}</div>
            </div>`).join('')}
        </div>
        <div class="task-chart-labels">
          ${bars.map(b => `<div class="task-chart-label"><i data-lucide="${b.icon}" style="width:18px;height:18px;color:${b.color};"></i></div>`).join('')}
        </div>
      </div>

      <!-- Legend / filter pills -->
      <div class="ist-legend">
        ${bars.map(b => `
          <div class="ist-legend-item" id="ist-leg-${b.key}" onclick="istFilter('${b.key}')">
            <i data-lucide="${b.icon}" style="width:18px;height:18px;color:${b.color};"></i>
            <span>${b.label}</span>
          </div>`).join('')}
      </div>

      <!-- Task list -->
      <div class="ist-task-list" id="istTaskList">
        ${_istBuildList(myTasks, 'All', id, isTodo, isReview, isDone, isOverdue)}
      </div>
    </div>`;

  document.body.appendChild(sheet);
  requestAnimationFrame(() => sheet.querySelector('#istSheetInner').classList.add('ist-sheet-open'));
  if (window.lucide) lucide.createIcons();

  // Store for filter use
  window._istTasks   = myTasks;
  window._istId      = id;
  window._istIsTodo  = isTodo;
  window._istIsRev   = isReview;
  window._istIsDone  = isDone;
  window._istIsOver  = isOverdue;
}

function _istBuildList(tasks, key, id, isTodo, isReview, isDone, isOverdue) {
  let filtered = tasks;
  if      (key === 'Todo')     filtered = tasks.filter(isTodo);
  else if (key === 'InReview') filtered = tasks.filter(isReview);
  else if (key === 'Done')     filtered = tasks.filter(isDone);
  else if (key === 'Overdue')  filtered = tasks.filter(isOverdue);

  if (!filtered.length) return `<div class="ist-empty">🎉 No tasks in this category</div>`;
  return filtered.map(t => {
    const done = isTaskDone(t.id, id);
    const color = done ? '#22c55e' : '#3b82f6';
    return `<div class="ist-task-row" onclick="openTaskDetail('${t.id}','${id}')">
      <div class="ist-task-dot" style="background:${color};"></div>
      <div class="ist-task-name${done?' ist-task-done':''}">${sanitize(t.title)}</div>
      ${t.points ? `<span class="ist-task-pts">+${t.points}</span>` : ''}
    </div>`;
  }).join('');
}

function istFilter(key) {
  // Update active legend
  document.querySelectorAll('.ist-legend-item').forEach(el => el.classList.remove('ist-legend-active'));
  document.getElementById('ist-leg-' + key)?.classList.add('ist-legend-active');
  // Rebuild list
  const list = document.getElementById('istTaskList');
  if (list) {
    list.innerHTML = _istBuildList(
      window._istTasks, key, window._istId,
      window._istIsTodo, window._istIsRev, window._istIsDone, window._istIsOver
    );
  }
}

function openStatDetail(category) {
  console.log('=== openStatDetail called ===');
  console.log('Category:', category);
  console.log('Current user:', currentUser);
  
  const id = currentUser.id;
  const s = db.submissions[id] || {};
  
  console.log('User ID:', id);
  console.log('Submissions:', s);
  
  switch(category) {
    case 'points':
      console.log('Opening Points stats');
      renderPointsStats(id, s);
      break;
    case 'rank':
      console.log('Opening Rank stats');
      renderRankStats(id, s);
      break;
    case 'streak':
      console.log('Opening Streak stats');
      renderStreakStats(id, s);
      break;
    case 'office':
      console.log('Opening Office stats');
      renderOfficeStats(id, s);
      break;
    case 'bugs':
      console.log('Opening Bugs stats');
      renderBugsStats(id, s);
      break;
    case 'projects':
      console.log('Opening Projects stats');
      renderProjectsStats(id, s);
      break;
    case 'suggestions':
      console.log('Opening Suggestions stats');
      renderSuggestionsStats(id, s);
      break;
    default:
      console.log('Unknown category:', category);
      showToast('ℹ️', 'Coming soon!');
  }
  console.log('=== openStatDetail finished ===');
}

// Make globally accessible
window.openStatDetail = openStatDetail;

// ── Points History Statistics ────────────────────────────────────────────
function renderPointsStats(id, s) {
  console.log('renderPointsStats called for user:', id);
  
  // Hide header and footer
  const header = document.getElementById('mainTopbar');
  const footer = document.getElementById('mobBottomNav');
  if (header) header.style.display = 'none';
  if (footer) footer.style.display = 'none';
  
  const pts = s.points || 0;
  
  // Calculate points breakdown
  const officePoints = (s.office || 0) * 100;
  const projectPoints = (s.projects || 0) * 200;
  const bugsPoints = (s.bugs || 0) * 150;
  const suggestionsPoints = (s.suggestions || 0) * 80;
  
  const total = officePoints + projectPoints + bugsPoints + suggestionsPoints || 1;
  
  const categories = [
    { label: 'Office', points: officePoints, color: '#8b5cf6', percentage: Math.round((officePoints/total)*100) },
    { label: 'Project', points: projectPoints, color: '#10b981', percentage: Math.round((projectPoints/total)*100) },
    { label: 'Bugs', points: bugsPoints, color: '#14b8a6', percentage: Math.round((bugsPoints/total)*100) },
    { label: 'Suggestions', points: suggestionsPoints, color: '#f59e0b', percentage: Math.round((suggestionsPoints/total)*100) },
  ];
  
  const filter = window.pointsStatsFilter || 'monthly';
  
  const ca = document.getElementById('contentArea');
  ca.innerHTML = `
    <div class="stat-detail-page">
      <div class="stat-detail-header">
        <button class="stat-back-btn" onclick="navigateTo('internDashboard')" title="Back">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
        </button>
        <div class="stat-detail-title">Points History</div>
      </div>

      <div class="stat-detail-body">
        <div class="points-pie-section">
          <div class="points-pie-chart">
            <svg viewBox="0 0 200 200" style="width:100%;max-width:280px;height:auto;">
              <circle cx="100" cy="100" r="80" fill="none" stroke="#8b5cf6" stroke-width="40" 
                stroke-dasharray="${categories[0].percentage * 5.03} 502" 
                transform="rotate(-90 100 100)" />
              <circle cx="100" cy="100" r="80" fill="none" stroke="#3b82f6" stroke-width="40"
                stroke-dasharray="${categories[1].percentage * 5.03} 502"
                stroke-dashoffset="${-categories[0].percentage * 5.03}"
                transform="rotate(-90 100 100)" />
              <circle cx="100" cy="100" r="80" fill="none" stroke="#10b981" stroke-width="40"
                stroke-dasharray="${categories[2].percentage * 5.03} 502"
                stroke-dashoffset="${-(categories[0].percentage + categories[1].percentage) * 5.03}"
                transform="rotate(-90 100 100)" />
              <circle cx="100" cy="100" r="80" fill="none" stroke="#14b8a6" stroke-width="40"
                stroke-dasharray="${categories[3].percentage * 5.03} 502"
                stroke-dashoffset="${-(categories[0].percentage + categories[1].percentage + categories[2].percentage) * 5.03}"
                transform="rotate(-90 100 100)" />
              <circle cx="100" cy="100" r="80" fill="none" stroke="#f59e0b" stroke-width="40"
                stroke-dasharray="${categories[4].percentage * 5.03} 502"
                stroke-dashoffset="${-(categories[0].percentage + categories[1].percentage + categories[2].percentage + categories[3].percentage) * 5.03}"
                transform="rotate(-90 100 100)" />
              <text x="100" y="100" text-anchor="middle" dy="0.35em" style="font-size:32px;font-weight:700;fill:var(--text);">${pts.toLocaleString()}</text>
            </svg>
          </div>

          <div class="points-legend">
            ${categories.map(cat => `
              <div class="points-legend-item">
                <div style="display:flex;align-items:center;gap:8px;">
                  <div style="width:12px;height:12px;border-radius:50%;background:${cat.color};"></div>
                  <span style="font-size:14px;font-weight:600;color:var(--text);">${cat.label}</span>
                </div>
                <span style="font-size:14px;font-weight:700;color:#10b981;">${cat.points.toLocaleString()} pts</span>
              </div>
            `).join('')}
          </div>
        </div>

        <div style="height:60px;"></div>
      </div>
    </div>
  `;
  
  if (window.lucide) lucide.createIcons();
}

function setPointsFilter(filter) {
  window.pointsStatsFilter = filter;
  const id = currentUser.id;
  const s = db.submissions[id] || {};
  renderPointsStats(id, s);
}

// ── Rank Statistics Detail Page ──────────────────────────────────────────
function renderRankStats(id, s) {
  try {
    console.log('renderRankStats called for user:', id);
    
    // Hide header and footer
    const header = document.getElementById('mainTopbar');
    const footer = document.getElementById('mobBottomNav');
    if (header) header.style.display = 'none';
    if (footer) footer.style.display = 'none';
    
    const rank = getRank(id);
    const pts = s.points || 0;
    const allInterns = Object.keys(db.submissions).filter(uid => db.users[uid]?.role === 'intern');
    const totalInterns = allInterns.length;
    
    console.log('Rank data:', { rank, pts, totalInterns });
    
    // Calculate points breakdown
    const tasksPoints = (s.completedTasks || []).reduce((sum, tid) => {
      const t = db.tasks.find(x => x.id == tid);
      return sum + (t?.points || 0);
    }, 0);
    const bugsPoints = (s.bugs || 0) * 20; // 20 pts per bug
    const projectsPoints = (s.projects || 0) * 50; // 50 pts per project
    const attendancePoints = pts - tasksPoints - bugsPoints - projectsPoints;
  
  // Get rank #2 person's points for comparison
  const sortedInterns = allInterns.map(uid => ({
    id: uid,
    name: db.users[uid]?.name || 'Unknown',
    points: db.submissions[uid]?.points || 0
  })).sort((a, b) => b.points - a.points);
  
  const rank2Points = sortedInterns[1]?.points || 0;
  const pointsAhead = pts - rank2Points;
  
  // Get lowest rank person
  const lowestRankPerson = sortedInterns[sortedInterns.length - 1];
  const lowestRankName = lowestRankPerson?.name || 'Unknown';
  const lowestRankNumber = sortedInterns.length;
  
  // Filter state
  const filter = window.rankStatsFilter || 'monthly';
  
  const ca = document.getElementById('contentArea');
  if (!ca) {
    console.error('❌ contentArea not found!');
    return;
  }
  
  console.log('✅ contentArea found:', ca);
  
  ca.innerHTML = `
    <div class="stat-detail-page" style="min-height:100vh;background:#f5f5f5;">
      <!-- Header -->
      <div class="stat-detail-header" style="display:flex;align-items:center;gap:12px;padding:16px 20px;background:#fff;border-bottom:0.5px solid rgba(0,0,0,0.1);">
        <button class="stat-back-btn" onclick="navigateTo('internDashboard')" title="Back" style="width:36px;height:36px;border-radius:10px;background:none;border:1px solid rgba(0,0,0,0.1);display:flex;align-items:center;justify-content:center;color:#666;cursor:pointer;">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
        </button>
        <div class="stat-detail-title" style="font-size:18px;font-weight:700;color:#1a1a1a;">Rank Statistics</div>
      </div>

      <div class="stat-detail-body" style="padding:20px;">
        <!-- Filter Tabs -->
        <div class="stat-filter-tabs" style="display:flex;gap:8px;margin-bottom:20px;background:#f8f8f8;padding:4px;border-radius:12px;">
          <button class="stat-filter-tab ${filter === 'weekly' ? 'active' : ''}" onclick="setRankFilter('weekly')" style="flex:1;padding:8px 16px;border:none;border-radius:8px;background:${filter === 'weekly' ? '#fff' : 'transparent'};color:${filter === 'weekly' ? '#1a1a1a' : '#666'};font-weight:500;font-size:13px;cursor:pointer;">Weekly</button>
          <button class="stat-filter-tab ${filter === 'monthly' ? 'active' : ''}" onclick="setRankFilter('monthly')" style="flex:1;padding:8px 16px;border:none;border-radius:8px;background:${filter === 'monthly' ? '#fff' : 'transparent'};color:${filter === 'monthly' ? '#1a1a1a' : '#666'};font-weight:500;font-size:13px;cursor:pointer;">Monthly</button>
          <button class="stat-filter-tab ${filter === 'all' ? 'active' : ''}" onclick="setRankFilter('all')" style="flex:1;padding:8px 16px;border:none;border-radius:8px;background:${filter === 'all' ? '#fff' : 'transparent'};color:${filter === 'all' ? '#1a1a1a' : '#666'};font-weight:500;font-size:13px;cursor:pointer;">All Time</button>
        </div>

        <!-- 3 Info Buckets -->
        <div class="stat-buckets" style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:24px;">
          <div class="stat-bucket stat-bucket-primary" style="background:#fff;border:1.5px solid #e85d26;border-radius:12px;padding:14px 12px;text-align:center;background:rgba(232,93,38,0.05);">
            <div class="stat-bucket-label" style="font-size:10px;font-weight:600;color:#666;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">Current Rank</div>
            <div class="stat-bucket-value" style="font-size:24px;font-weight:700;color:#1a1a1a;margin-bottom:2px;">#${rank}</div>
            <div class="stat-bucket-sub" style="font-size:11px;color:#999;">of ${totalInterns} interns</div>
          </div>
          <div class="stat-bucket stat-bucket-success" style="background:#fff;border:1.5px solid #27ae60;border-radius:12px;padding:14px 12px;text-align:center;background:rgba(39,174,96,0.05);">
            <div class="stat-bucket-label" style="font-size:10px;font-weight:600;color:#666;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">Points Ahead</div>
            <div class="stat-bucket-value" style="font-size:24px;font-weight:700;color:#1a1a1a;margin-bottom:2px;">+${pointsAhead}</div>
            <div class="stat-bucket-sub" style="font-size:11px;color:#999;">from rank #2</div>
          </div>
          <div class="stat-bucket stat-bucket-info" style="background:#fff;border:1.5px solid #3b82f6;border-radius:12px;padding:14px 12px;text-align:center;background:rgba(59,130,246,0.05);">
            <div class="stat-bucket-label" style="font-size:10px;font-weight:600;color:#666;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">Lowest Rank</div>
            <div class="stat-bucket-value" style="font-size:24px;font-weight:700;color:#1a1a1a;margin-bottom:2px;">#${lowestRankNumber}</div>
            <div class="stat-bucket-sub" style="font-size:11px;color:#999;">${sanitize(lowestRankName)}</div>
          </div>
        </div>

        <!-- Points Breakdown Chart -->
        <div class="stat-section" style="background:#fff;border:0.5px solid rgba(0,0,0,0.1);border-radius:12px;padding:18px;margin-bottom:16px;">
          <div class="stat-section-title" style="font-size:15px;font-weight:600;color:#1a1a1a;margin-bottom:16px;">Points Breakdown</div>
          <div class="stat-chart-wrapper">
            <div class="points-breakdown-chart" style="display:flex;align-items:flex-end;gap:12px;height:180px;padding:0 10px;">
              <div class="pb-item" style="flex:${tasksPoints};display:flex;flex-direction:column;align-items:center;gap:8px;">
                <div class="pb-bar" style="width:100%;background:#3b82f6;height:${Math.max(tasksPoints/pts*100, 10)}%;border-radius:6px 6px 0 0;"></div>
                <div class="pb-label" style="font-size:11px;font-weight:500;color:#666;text-align:center;">Tasks</div>
                <div class="pb-value" style="font-size:13px;font-weight:700;color:#1a1a1a;">${tasksPoints}</div>
              </div>
              <div class="pb-item" style="flex:${bugsPoints};display:flex;flex-direction:column;align-items:center;gap:8px;">
                <div class="pb-bar" style="width:100%;background:#ef4444;height:${Math.max(bugsPoints/pts*100, 10)}%;border-radius:6px 6px 0 0;"></div>
                <div class="pb-label" style="font-size:11px;font-weight:500;color:#666;text-align:center;">Bugs</div>
                <div class="pb-value" style="font-size:13px;font-weight:700;color:#1a1a1a;">${bugsPoints}</div>
              </div>
              <div class="pb-item" style="flex:${projectsPoints};display:flex;flex-direction:column;align-items:center;gap:8px;">
                <div class="pb-bar" style="width:100%;background:#059669;height:${Math.max(projectsPoints/pts*100, 10)}%;border-radius:6px 6px 0 0;"></div>
                <div class="pb-label" style="font-size:11px;font-weight:500;color:#666;text-align:center;">Projects</div>
                <div class="pb-value" style="font-size:13px;font-weight:700;color:#1a1a1a;">${projectsPoints}</div>
              </div>
              <div class="pb-item" style="flex:${attendancePoints};display:flex;flex-direction:column;align-items:center;gap:8px;">
                <div class="pb-bar" style="width:100%;background:#f59e0b;height:${Math.max(attendancePoints/pts*100, 10)}%;border-radius:6px 6px 0 0;"></div>
                <div class="pb-label" style="font-size:11px;font-weight:500;color:#666;text-align:center;">Attendance</div>
                <div class="pb-value" style="font-size:13px;font-weight:700;color:#1a1a1a;">${attendancePoints}</div>
              </div>
            </div>
          </div>
        </div>

        <!-- Top Performers Leaderboard -->
        <div class="stat-section" style="background:#fff;border:0.5px solid rgba(0,0,0,0.1);border-radius:12px;padding:18px;margin-bottom:16px;">
          <div class="stat-section-title" style="font-size:15px;font-weight:600;color:#1a1a1a;margin-bottom:16px;">Top 5 Performers</div>
          <div class="leaderboard-list" style="display:flex;flex-direction:column;gap:8px;">
            ${sortedInterns.slice(0, 5).map((intern, idx) => `
              <div class="lb-item ${intern.id === id ? 'lb-item-me' : ''}" style="display:flex;align-items:center;gap:12px;padding:12px;background:${intern.id === id ? 'rgba(232,93,38,0.08)' : '#f8f8f8'};border:1px solid ${intern.id === id ? '#e85d26' : 'rgba(0,0,0,0.1)'};border-radius:10px;">
                <div class="lb-rank" style="width:32px;height:32px;border-radius:8px;background:#fff;border:1px solid rgba(0,0,0,0.1);display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:#1a1a1a;flex-shrink:0;">#${idx + 1}</div>
                <div class="lb-name" style="flex:1;font-size:14px;font-weight:500;color:#1a1a1a;">${sanitize(intern.name)}</div>
                <div class="lb-points" style="font-size:13px;font-weight:600;color:#e85d26;">${intern.points} pts</div>
              </div>
            `).join('')}
          </div>
        </div>

        <div style="height:60px;"></div>
      </div>
    </div>
  `;
  
  console.log('✅ Rank stats HTML has been set to contentArea');
  console.log('Content length:', ca.innerHTML.length);
  
  if (window.lucide) lucide.createIcons();
  console.log('✅ Rank stats - Lucide icons created');
  
  } catch (error) {
    console.error('❌ ERROR in renderRankStats:', error);
    alert('Error loading Rank Statistics: ' + error.message + '\n\nCheck console for details.');
    // Show header/footer again
    const header = document.getElementById('mainTopbar');
    const footer = document.getElementById('mobBottomNav');
    if (header) header.style.display = '';
    if (footer) footer.style.display = '';
  }
}

