function renderStreakStats(id, s) {
  console.log('renderStreakStats called for user:', id);
  
  // Hide header and footer
  const header = document.getElementById('mainTopbar');
  const footer = document.getElementById('mobBottomNav');
  if (header) header.style.display = 'none';
  if (footer) footer.style.display = 'none';
  
  const currentStreak = getStreak(id);
  const highestStreak = s.highestStreak || currentStreak;
  const teamAvgStreak = 3.5; // TODO: Calculate from all interns
  
  // Generate calendar data for current month
  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();
  
  // Mock attendance data - replace with real data
  const attendanceData = {};
  for (let i = 1; i <= daysInMonth; i++) {
    const rand = Math.random();
    if (rand > 0.8) attendanceData[i] = 'absent';
    else if (rand > 0.6) attendanceData[i] = 'leave';
    else attendanceData[i] = 'present';
  }
  
  const filter = window.streakStatsFilter || 'monthly';
  
  const ca = document.getElementById('contentArea');
  ca.innerHTML = `
    <div class="stat-detail-page">
      <div class="stat-detail-header">
        <button class="stat-back-btn" onclick="navigateTo('internDashboard')" title="Back">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
        </button>
        <div class="stat-detail-title">Streak Statistics</div>
      </div>

      <div class="stat-detail-body">
        <div class="stat-filter-tabs">
          <button class="stat-filter-tab ${filter === 'weekly' ? 'active' : ''}" onclick="setStreakFilter('weekly')">Weekly</button>
          <button class="stat-filter-tab ${filter === 'monthly' ? 'active' : ''}" onclick="setStreakFilter('monthly')">Monthly</button>
          <button class="stat-filter-tab ${filter === 'all' ? 'active' : ''}" onclick="setStreakFilter('all')">All Time</button>
        </div>

        <div class="stat-buckets">
          <div class="stat-bucket stat-bucket-primary">
            <div class="stat-bucket-label">Current Streak</div>
            <div class="stat-bucket-value">${currentStreak}</div>
            <div class="stat-bucket-sub">days</div>
          </div>
          <div class="stat-bucket stat-bucket-success">
            <div class="stat-bucket-label">Highest Ever</div>
            <div class="stat-bucket-value">${highestStreak}</div>
            <div class="stat-bucket-sub">days</div>
          </div>
          <div class="stat-bucket stat-bucket-info">
            <div class="stat-bucket-label">Team Average</div>
            <div class="stat-bucket-value">${teamAvgStreak}</div>
            <div class="stat-bucket-sub">days</div>
          </div>
        </div>

        <div class="stat-section">
          <div class="stat-section-title">Streak overview</div>
          <div class="calendar-dashboard">
            <div class="calendar-header">
              <div class="calendar-weekdays">
                <div class="calendar-weekday">S</div>
                <div class="calendar-weekday">M</div>
                <div class="calendar-weekday">T</div>
                <div class="calendar-weekday">W</div>
                <div class="calendar-weekday">T</div>
                <div class="calendar-weekday">F</div>
                <div class="calendar-weekday">S</div>
              </div>
            </div>
            <div class="calendar-grid">
              ${Array(firstDay).fill('').map(() => '<div class="calendar-day calendar-day-empty"></div>').join('')}
              ${Array.from({length: daysInMonth}, (_, i) => i + 1).map(day => {
                const status = attendanceData[day] || 'empty';
                const isToday = day === today.getDate();
                return `<div class="calendar-day calendar-day-${status} ${isToday ? 'calendar-day-today' : ''}">${day}</div>`;
              }).join('')}
            </div>
            <div class="calendar-legend">
              <div class="legend-item"><div class="legend-dot" style="background:#27ae60;"></div> Present</div>
              <div class="legend-item"><div class="legend-dot" style="background:#ef4444;"></div> Absent</div>
              <div class="legend-item"><div class="legend-dot" style="background:#f59e0b;"></div> Leave</div>
            </div>
          </div>
        </div>

        <div style="height:60px;"></div>
      </div>
    </div>
  `;
  
  if (window.lucide) lucide.createIcons();
}

