// Animate hero stat bars/numbers + Analytics widgets (grow/count-up from zero) whenever
// the profile page (re)renders — e.g. on first open, or when switching to the Analytics tab.
function np2AnimateProfileStats(root) {
  requestAnimationFrame(() => requestAnimationFrame(() => {
    root.querySelectorAll('.np2-anim-bar[data-target]').forEach(el => {
      const prop = el.getAttribute('data-prop') || 'width';
      el.style[prop] = el.getAttribute('data-target');
    });
    root.querySelectorAll('.np2-anim-donut[data-target-dasharray]').forEach(el => {
      el.style.strokeDasharray = el.getAttribute('data-target-dasharray');
    });
    root.querySelectorAll('.np2-countup[data-target]').forEach(el => {
      const target   = parseFloat(el.getAttribute('data-target')) || 0;
      const suffix   = el.getAttribute('data-suffix') || '';
      const useComma = el.getAttribute('data-comma') === '1';
      const duration = 900;
      const t0 = performance.now();
      (function tick(now) {
        const p = Math.min(1, (now - t0) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        const val = Math.round(target * eased);
        el.textContent = (useComma ? val.toLocaleString() : val) + suffix;
        if (p < 1) requestAnimationFrame(tick);
      })(t0);
    });
  }));
}

// Badge tap-to-reveal popup (Habitica-style: locked badges show criteria, earned show date)
function openBadgeDetail(idx) {
  const b = window._pfBadges && window._pfBadges[idx];
  if (!b) return;
  openModal(`
    <div style="text-align:center;padding:10px 4px 4px;">
      <div style="width:64px;height:64px;border-radius:50%;margin:0 auto 14px;display:flex;align-items:center;justify-content:center;font-size:28px;background:${b.earned?b.bg:'rgba(107,114,128,.12)'};color:${b.earned?b.color:'var(--text3)'};">
        ${b.earned ? b.icon : `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0110 0v4"/></svg>`}
      </div>
      <div style="font-size:16px;font-weight:700;color:var(--text);margin-bottom:6px;">${sanitize(b.label)}</div>
      <div style="font-size:13px;color:var(--text2);margin-bottom:12px;">${sanitize(b.desc)}</div>
      ${b.earned
        ? `<div style="font-size:12px;font-weight:600;color:#22c55e;">Earned${b.earnedDate ? ' on ' + sanitize(b.earnedDate) : ''}</div>`
        : `<div style="font-size:12px;font-weight:600;color:var(--text3);">Not yet earned</div>`}
    </div>
  `);
}

// ║      ATTENDANCE DASHBOARD FUNCTIONS               ║
// ╚══════════════════════════════════════════════════╝

function switchAttendanceType(userId, type) {
  if (!window.attendanceState) window.attendanceState = {};
  if (!window.attendanceState[userId]) window.attendanceState[userId] = { type: 'office', month: 3 };
  
  window.attendanceState[userId].type = type;
  
  // Update active tab
  document.querySelectorAll('.attendance-type-tab').forEach(tab => {
    tab.classList.remove('active');
  });
  event.target.closest('.attendance-type-tab').classList.add('active');
  
  updateAttendanceDashboard(userId);
}

function changeAttendanceMonth(userId, monthIndex) {
  if (!window.attendanceState) window.attendanceState = {};
  if (!window.attendanceState[userId]) window.attendanceState[userId] = { type: 'office', month: 3 };
  
  window.attendanceState[userId].month = parseInt(monthIndex);
  updateAttendanceDashboard(userId);
}

function updateAttendanceDashboard(userId) {
  const state = window.attendanceState[userId] || { type: 'office', month: 3 };
  const s = db.submissions[userId] || {};
  const logs = s.attendanceLogs || [];
  
  // Filter logs by type and month
  const year = 2026;
  const monthStart = new Date(year, state.month, 1);
  const monthEnd = new Date(year, state.month + 1, 0);
  
  const filteredLogs = logs.filter(log => {
    if (state.type === 'office' && log.type !== 'Office Attendance') return false;
    
    const logDate = new Date(log.date + 'T00:00:00');
    return logDate >= monthStart && logDate <= monthEnd;
  });
  
  // Calculate stats
  const present = filteredLogs.filter(l => l.status === 'present').length;
  const absent = filteredLogs.filter(l => l.status === 'absent').length;
  const leave = filteredLogs.filter(l => l.status === 'leave').length;
  
  // Update stats display
  const statsEl = document.getElementById(`attendanceStats-${userId}`);
  if (statsEl) {
    statsEl.innerHTML = `
      <div class="attendance-stat-box">
        <div class="attendance-stat-value present">${present}</div>
        <div class="attendance-stat-label">Present</div>
      </div>
      <div class="attendance-stat-box">
        <div class="attendance-stat-value absent">${absent}</div>
        <div class="attendance-stat-label">Absent</div>
      </div>
      <div class="attendance-stat-box">
        <div class="attendance-stat-value leave">${leave}</div>
        <div class="attendance-stat-label">Leave</div>
      </div>
    `;
  }
  
  // Build calendar
  const calendarEl = document.getElementById(`attendanceCalendar-${userId}`);
  if (calendarEl) {
    const daysInMonth = new Date(year, state.month + 1, 0).getDate();
    const firstDay = new Date(year, state.month, 1).getDay();
    const startDay = firstDay === 0 ? 6 : firstDay - 1; // Monday = 0
    
    const today = new Date();
    const todayStr = today.toISOString().slice(0, 10);
    
    let calendarHTML = `
      <div class="attendance-cal-grid">
        <div class="attendance-cal-label">M</div>
        <div class="attendance-cal-label">T</div>
        <div class="attendance-cal-label">W</div>
        <div class="attendance-cal-label">T</div>
        <div class="attendance-cal-label">F</div>
        <div class="attendance-cal-label">S</div>
        <div class="attendance-cal-label">S</div>
    `;
    
    // Empty cells before month starts
    for (let i = 0; i < startDay; i++) {
      calendarHTML += '<div class="attendance-cal-day empty"></div>';
    }
    
    // Days of the month
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, state.month, day);
      const dateStr = date.toISOString().slice(0, 10);
      const dayOfWeek = date.getDay();
      const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
      
      const log = filteredLogs.find(l => l.date === dateStr);
      const status = log ? log.status : (isWeekend ? 'weekend' : '');
      const isToday = dateStr === todayStr;
      
      let className = 'attendance-cal-day';
      if (status) className += ' ' + status;
      if (isToday) className += ' today';
      
      calendarHTML += `<div class="${className}">${day}</div>`;
    }
    
    calendarHTML += '</div>';
    calendarEl.innerHTML = calendarHTML;
  }
}

// Make functions globally accessible
window.switchAttendanceType = switchAttendanceType;
window.changeAttendanceMonth = changeAttendanceMonth;


