// Expanded palette (130+ shades) matching the reference screenshots' hue
// groupings: reds, oranges, ambers, yellows, olive/yellow-greens, greens,
// teals, cyans, blues, indigos, purples, pinks/magentas, browns, grays.
const HABIT_COLORS = [
  '#F44336','#D32F2F','#B71C1C','#E57373','#EF5350','#FF6659','#C62828','#E53935','#FF8A80','#FFCDD2',
  '#FF9800','#F57C00','#E65100','#FFB74D','#FFA726','#FF6D00','#FFCC80','#FF7043','#D84315','#FFAB40',
  '#FFC107','#FFB300','#FF8F00','#FFD54F','#FFE082','#FFA000','#C9930A','#FFCA28','#FFECB3','#D4A03C',
  '#FFEB3B','#FDD835','#F9A825','#FFF176','#FFF9C4','#FBC02D','#FFEE58','#F57F17','#FFFDE7','#E6D200',
  '#8BC34A','#7CB342','#558B2F','#AED581','#9CCC65',
  '#4CAF50','#388E3C','#1B5E20','#66BB6A','#81C784','#2E7D32','#43A047','#A5D6A7','#00A876','#2D7A3A',
  '#009688','#00796B','#004D40','#4DB6AC','#80CBC4','#00897B','#26A69A','#B2DFDB','#0D9488','#00695C',
  '#00BCD4','#0097A7','#006064','#4DD0E1','#B2EBF2','#00ACC1','#26C6DA','#80DEEA','#1EC2D4','#0A7A7A',
  '#2196F3','#1976D2','#0D47A1','#64B5F6','#BBDEFB','#1E88E5','#42A5F5','#90CAF9','#1565C0','#1E90E0',
  '#3F51B5','#303F9F','#1A237E','#7986CB','#C5CAE9','#3D52C7','#5C6BC0','#7484C7',
  '#9C27B0','#7B1FA2','#4A148C','#BA68C8','#E1BEE7','#8E24AA','#AB47BC','#6A1B9A','#D1C4E9',
  '#E91E63','#C2185B','#880E4F','#F06292','#F8BBD0','#D81B60','#EC407A','#FCE4EC','#D4145A','#E0508A',
  '#795548','#5D4037','#3E2723','#A1887F','#D7CCC8','#6D4C41','#8D6E63','#BCAAA4','#7A5A47','#9C8477',
  '#EEEEEE','#E0E0E0','#BDBDBD','#9E9E9E','#757575','#616161','#424242'
];

// ── Auto-assign colour order ─────────────────────────────────────────────
// HABIT_COLORS above is grouped in runs of same-hue shades (10 reds, then
// 10 oranges, 10 ambers, ...) which is exactly right for the manual colour
// picker grid. But cycling through it in that raw order for auto-assignment
// meant back-to-back tasks got near-identical shades of the same hue before
// ever reaching a different colour family (e.g. red, darker red, lighter
// red...). AUTO_COLOR_CYCLE re-orders the same 129 colours "column-major" —
// one colour from every hue family first, then the next shade of every
// family, and so on — so consecutive auto-picks always look visually
// distinct, matching a red, then teal, then gold, then blue... pattern.
// NOTE: keep HUE_GROUP_SIZES in sync with the row layout of HABIT_COLORS
// above (each number = how many shades that hue-family row contains) if
// that list is ever edited.
const HUE_GROUP_SIZES = [10,10,10,10,5,10,10,10,10,8,9,10,10,7];
const AUTO_COLOR_CYCLE = (function() {
  const groups = []; let i = 0;
  for (const size of HUE_GROUP_SIZES) { groups.push(HABIT_COLORS.slice(i, i + size)); i += size; }
  const maxLen = Math.max(...HUE_GROUP_SIZES);
  const order = [];
  for (let col = 0; col < maxLen; col++) {
    for (const g of groups) { if (col < g.length) order.push(g[col]); }
  }
  return order;
})();

function _habitToday() { return typeof today === 'function' ? today() : dateToLocalStr(new Date()); }

function _habitFmtHeaderDate(dateStr) {
  const d = new Date(dateStr + 'T00:00:00');
  const day = d.getDate();
  const suffix = day===1||day===21||day===31?'st':day===2||day===22?'nd':day===3||day===23?'rd':'th';
  return `${day}${suffix} ${d.toLocaleDateString('en-US',{month:'short'})}`;
}

function _habitFmtDow(dateStr) {
  return ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][new Date(dateStr+'T00:00:00').getDay()];
}

function _habitTasksForDate(dateStr, internId) {
  return db.tasks.filter(t => {
    if (t.isTemplate) return false;
    const assigned = t.assignedTo===internId || (t.sharedWith&&t.sharedWith.includes(internId)) || (t.isPersonal&&t.createdBy===internId);
    if (!assigned) return false;
    if (t.instanceDate) return t.instanceDate === dateStr;
    const taskDate = t.dueDate || t.createdDate;
    if (!taskDate) return dateStr === _habitToday();
    return taskDate === dateStr;
  });
}

function _habitDayPct(dateStr, internId) {
  const tasks = _habitTasksForDate(dateStr, internId);
  if (!tasks.length) return 0;
  return Math.round(tasks.filter(t => isTaskDone(t.id, internId)).length / tasks.length * 100);
}

function _habitGetIconSvg(task) {
  if (task.iconSvg) return task.iconSvg;
  const cat = (task.category||'').toLowerCase();
  if (cat==='office') return HABIT_ICONS.office;
  if (cat==='academic') return HABIT_ICONS.book;
  return HABIT_ICONS.check;
}

function _habitGetIconColor(task) {
  if (task.iconColor) return task.iconColor;
  if (task.color) return task.color;
  const cat = (task.category||'').toLowerCase();
  if (cat==='office') return '#2563EB';
  if (cat==='academic') return '#059669';
  return '#E85D26';
}

// Returns unique tasks that fall anywhere within [startStr, endStr] inclusive
function _habitTasksForRange(startStr, endStr, internId) {
  const seen = new Set();
  const result = [];
  const cur = new Date(startStr + 'T00:00:00');
  const end = new Date(endStr + 'T00:00:00');
  while (cur <= end) {
    const ds = dateToLocalStr(cur);
    _habitTasksForDate(ds, internId).forEach(t => {
      if (!seen.has(t.id)) { seen.add(t.id); result.push(t); }
    });
    cur.setDate(cur.getDate() + 1);
  }
  return result;
}


// ── Admin/Intern shared data layer for the swipeable Tasks/Habits page ──
// An intern only ever looks at their own data. Admin looks at either every
// intern or one filtered intern (window.atFilterAssignee) — but everything
// else (header, panes, swipe/nav behavior, category filter, calendar) is
// the exact same shared system either way; only *which ids* to pull from
// differs. Each returned item carries its owner as `_iid`.
function _thpTargetIds() {
  if (currentRole === 'admin') {
    const filterIntern = window.atFilterAssignee || '';
    if (filterIntern) return [parseInt(filterIntern)];
    return INTERNS.filter(i => i.id !== 99).map(i => i.id);
  }
  return [currentUser.id];
}
function _thpTasksForDate(dateStr) {
  const ids = _thpTargetIds();
  const seen = new Set(), result = [];
  ids.forEach(iid => _habitTasksForDate(dateStr, iid).forEach(t => {
    const key = t.id + '-' + iid;
    if (!seen.has(key)) { seen.add(key); result.push({ ...t, _iid: iid }); }
  }));
  return result;
}
function _thpTasksForRange(startStr, endStr) {
  const seen = new Set(), result = [];
  const cur = new Date(startStr + 'T00:00:00'), end = new Date(endStr + 'T00:00:00');
  while (cur <= end) {
    const ds = dateToLocalStr(cur);
    _thpTasksForDate(ds).forEach(t => {
      const key = t.id + '-' + t._iid;
      if (!seen.has(key)) { seen.add(key); result.push(t); }
    });
    cur.setDate(cur.getDate() + 1);
  }
  return result;
}
function _thpHabitsForDate(dateStr) {
  const ids = _thpTargetIds();
  const seen = new Set(), result = [];
  ids.forEach(iid => _habitGetHabitsForDate(dateStr, iid).forEach(h => {
    const key = h.id + '-' + iid;
    if (!seen.has(key)) { seen.add(key); result.push({ ...h, _iid: iid }); }
  }));
  return result;
}
// Drop-in replacements for _habitDayPct/_hbDayPct that aggregate across
// _thpTargetIds() instead of one intern — same (dateStr, internId) call
// shape as _buildDateStrip expects, so it needs no changes to use these.
function _thpAggTaskDayPct(dateStr) {
  const tasks = _thpTasksForDate(dateStr);
  if (!tasks.length) return 0;
  return Math.round(tasks.filter(t => isTaskDone(t.id, t._iid)).length / tasks.length * 100);
}
function _thpAggHabitDayPct(dateStr) {
  const habits = _thpHabitsForDate(dateStr);
  if (!habits.length) return 0;
  return Math.round(habits.filter(h => _habitCompleted(h.id, h._iid, dateStr)).length / habits.length * 100);
}

function _buildDateStrip(internId, pctFn) {
  pctFn = pctFn || _habitDayPct;
  const todayStr   = _habitToday();
  const rangeStart = window.habitRangeStart  || null;
  const rangeEnd   = window.habitRangeEnd    || null;
  const singleDay  = window.habitSelectedDate || todayStr;

  // Build full month — 1st to last day of the month containing the anchor
  const anchor = rangeStart || singleDay;
  const anchorDate = new Date(anchor + 'T00:00:00');
  const y = anchorDate.getFullYear();
  const m = anchorDate.getMonth();
  const firstOfMonth = new Date(y, m, 1);
  const lastOfMonth  = new Date(y, m + 1, 0);

  const days = [];
  const cur = new Date(firstOfMonth);
  while (cur <= lastOfMonth) {
    days.push(dateToLocalStr(cur));
    cur.setDate(cur.getDate() + 1);
  }

  const circ = (2 * Math.PI * 17).toFixed(2);

  return days.map(ds => {
    const isToday  = ds === todayStr;
    const isStart  = rangeStart && ds === rangeStart;
    const isEnd    = rangeEnd   && ds === rangeEnd;
    const inRange  = rangeStart && rangeEnd && ds >= rangeStart && ds <= rangeEnd;
    const isSingle = !rangeStart && ds === singleDay;

    const pct    = pctFn(ds, internId);
    const offset = (circ - (pct / 100) * circ).toFixed(2);

    let cls = 'ds-day';
    if (isToday)  cls += ' today';
    if (isSingle) cls += ' selected';
    if (isStart)  cls += ' ds-range-start';
    if (isEnd)    cls += ' ds-range-end';
    if (inRange && !isStart && !isEnd) cls += ' ds-in-range';

    return `<div class="${cls}"
      onclick="_dsHandleClick('${ds}')"
      ondblclick="_dsHandleDblClick('${ds}')">
      <div class="ds-day-label">${_habitFmtDow(ds)}</div>
      <div class="ds-day-ring">
        <svg viewBox="0 0 42 42" xmlns="http://www.w3.org/2000/svg">
          <circle class="ds-ring-bg" cx="21" cy="21" r="17" stroke-dasharray="${circ}" stroke-dashoffset="0"/>
          <circle class="ds-ring-fill" cx="21" cy="21" r="17" stroke-dasharray="${circ}" stroke-dashoffset="${offset}"/>
        </svg>
        <div class="ds-day-num">${new Date(ds + 'T00:00:00').getDate()}</div>
      </div>
    </div>`;
  }).join('');
}

function _buildHabitRow(task, internId) {
  const done = isTaskDone(task.id, internId);
  const color = _habitGetIconColor(task);  // chosen icon color
  const iconSvg = _habitGetIconSvg(task);
  const needsApproval = task.approvalRequired && !task.isPersonal;

  // Icon bg: always neutral gray. Icon stroke/fill: the task chosen color.
  const iconBgStyle = 'background:#f0f2f5;';  // CSS var overridden in dark via class

  // Checkmark button — ALWAYS rendered with checkmark SVG inside
  // Pending: transparent bg, border = task color, checkmark stroke = task color
  // Done:    filled bg = task color, white checkmark
  // Approval: yellow border
  let checkBtnOnClick = '';
  let checkDoneClass = done ? 'habit-check-btn done' : 'habit-check-btn';
  let checkBtnStyle = '';
  let checkmarkColor = '';

  if (done) {
    // Done: filled solid circle in task color, white check
    checkBtnStyle = `background:${color};border-color:${color};`;
    checkmarkColor = '#fff';
    checkBtnOnClick = `event.stopPropagation();`;
  } else if (needsApproval) {
    // Approval: task color tint bg + border, black check
    checkBtnStyle = `background:${color}14;border-color:${color}18;`;
    checkmarkColor = '#111';
    checkBtnOnClick = `event.stopPropagation();openApprovalDlg('${task.id}','${internId}')`;
  } else {
    // Pending: task color tint bg (14) + border (18), black tick always
    checkBtnStyle = `background:${color}14;border-color:${color}18;`;
    checkmarkColor = '#111';
    checkBtnOnClick = `event.stopPropagation();habitCompleteTask('${task.id}','${internId}',this)`;
  }

  // Checkmark SVG — always present, color changes
  const checkSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="${checkmarkColor}" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none;display:block;"><polyline points="20 6 9 17 4 12"/></svg>`;

  // Scale icon svg — remove any hardcoded w/h to let CSS control it
  const scaledIcon = iconSvg
    .replace(/width="[^"]*"/, '')
    .replace(/height="[^"]*"/, '')
    .replace('<svg ', '<svg width="22" height="22" ');
  const desc = task.description ? `<div class="habit-desc">${richTextPreview(task.description,80)}</div>` : '';

  // XP badge — shows task points in task color
  const xpBadge = task.points
    ? `<span class="habit-xp-badge" style="color:${color};background:${color}14;border-color:${color}18;">+${task.points}</span>`
    : '';

  return `<div class="habit-row${done?' habit-row-done':''}" data-task-id="${task.id}"
    onclick="openTaskDetail('${task.id}')" style="cursor:pointer;">
    <div class="habit-icon-sq ${done?'habit-icon-done':''}"
         style="${iconBgStyle}color:${color};"
         onclick="event.stopPropagation();openHabitInfoPopup('${task.id}',this)"
         title="Task info">
      ${scaledIcon}
    </div>
    <div class="habit-centre">
      <div class="habit-title">${sanitize(task.title)}</div>${desc}
    </div>
    <div class="habit-actions">
      ${xpBadge}
      <div class="${checkDoneClass}" style="${checkBtnStyle}" onclick="${checkBtnOnClick || 'event.stopPropagation()'}">${checkSvg}</div>
    </div>
  </div>`;
}

// Admin's version of _buildHabitRow: shows which intern owns the task (when
// viewing "All"), and tapping the checkmark opens Edit Task rather than
// completing it — admin manages tasks here, they don't complete them on an
// intern's behalf. Row itself still opens the full task detail view.
function _buildAdminTaskRow(task, interns, filterIntern) {
  const iid   = task._iid;
  const done  = isTaskDone(task.id, iid);
  const color = _habitGetIconColor(task);
  const iconSvg = _habitGetIconSvg(task);
  const scaledIcon = iconSvg.replace(/width="[^"]*"/, '').replace(/height="[^"]*"/, '').replace('<svg ', '<svg width="22" height="22" ');
  const desc = task.description ? `<div class="habit-desc">${richTextPreview(task.description,80)}</div>` : '';
  const xpBadge = task.points ? `<span class="habit-xp-badge" style="color:${color};background:${color}14;border-color:${color}18;">+${task.points}</span>` : '';
  const intern = interns.find(i => i.id === iid);
  const internBadge = !filterIntern && intern
    ? `<span class="at-intern-badge">${sanitize(intern.name.split(' ')[0])}</span>` : '';
  const checkBtnStyle = done
    ? `background:${color};border-color:${color};`
    : `background:${color}14;border-color:${color}18;`;
  const checkmarkColor = done ? '#fff' : '#111';
  const checkSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="${checkmarkColor}" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>`;
  return `<div class="habit-row${done?' habit-row-done':''}" data-task-id="${task.id}" onclick="openAdminTaskDetail('${task.id}')" style="cursor:pointer;">
    <div class="habit-icon-sq ${done?'habit-icon-done':''}" style="background:#f0f2f5;color:${color};" onclick="event.stopPropagation();openAdminTaskDetail('${task.id}')" title="Task detail">${scaledIcon}</div>
    <div class="habit-centre">
      <div class="habit-title">${sanitize(task.title)}${internBadge}</div>${desc}
    </div>
    <div class="habit-actions">${xpBadge}<div class="habit-check-btn${done?' done':''}" style="${checkBtnStyle}" onclick="event.stopPropagation();openEditTask('${task.id}')">${checkSvg}</div></div>
  </div>`;
}

function renderInternTasks(ca) {
  window.thpActiveTab = 'tasks'; // always land on Tasks on fresh navigation
  ca.innerHTML = `<div class="thp-outer">
    <div id="thpSharedHeader"></div>
    <div class="thp-swipe-wrap" id="thpSwipeWrap" onscroll="_thpOnScroll()">
      <div class="thp-page" id="thpTasksPage"></div>
      <div class="thp-divider"></div>
      <div class="thp-page" id="thpHabitsPage"></div>
    </div>
  </div>`;
  _thpRefreshAll();
  // Always land on the Tasks page (not wherever the user last swiped to).
  const wrap = document.getElementById('thpSwipeWrap');
  if (wrap) wrap.scrollLeft = 0;
  const navLabel = document.querySelector('#mbn-tasks .duo-nav-label');
  if (navLabel) navLabel.textContent = 'Tasks';
}

// Rebuilds the shared header plus both content panes. Used on first render
// and whenever the shared date/range changes (both panes depend on it) —
// but NOT on every swipe, and it never touches scroll position or which
// tab is considered active.
function _thpRefreshAll() {
  _renderSharedHeader();
  _renderTasksPageBody();
  _renderHabitsPageBody();
}

// Detects which of the two panes (Tasks / Habits) is currently in view as
// the user swipes. Habitica-style: the shared header above never rebuilds
// or flickers on swipe — only its % value/icon refresh to match whichever
// pane is now active, via a lightweight header-only re-render. The nav
// label updates live (cheap, just text), but the header rebuild itself is
// debounced until the swipe settles, so it never repaints mid-drag (which
// was causing a brief visible flash/mismatch while the finger was moving).
let _thpScrollSettleTimer = null;
function _thpOnScroll() {
  const wrap = document.getElementById('thpSwipeWrap');
  const navSel = currentRole === 'admin' ? '#ambn-tasks .duo-nav-label' : '#mbn-tasks .duo-nav-label';
  const navLabel = document.querySelector(navSel);
  if (!wrap || !navLabel) return;
  const pageIndex = wrap.scrollLeft < wrap.clientWidth / 2 ? 0 : 1;
  const newTab = pageIndex === 0 ? 'tasks' : 'habits';
  navLabel.textContent = pageIndex === 0 ? 'Tasks' : 'Habits';
  clearTimeout(_thpScrollSettleTimer);
  _thpScrollSettleTimer = setTimeout(() => {
    if (newTab !== window.thpActiveTab) {
      window.thpActiveTab = newTab;
      _renderSharedHeader(); // header only — the list panes below don't change
    }
  }, 120);
}

// ── Shared header: date label + day-strip + performance value. Lives ONCE
// above both swipeable panes (matching Habitica's fixed character-stats bar
// that never scrolls away). Only its % icon/number/settings-button swap
// between Tasks and Habits data — the date/range selection itself is shared
// by both panes, since you're browsing the same calendar either way. ──
function _renderSharedHeader() {
  const box = document.getElementById('thpSharedHeader');
  if (!box) return;
  const isAdminCtx = currentRole === 'admin';
  const id = currentUser.id; // still used for the intern path exactly as before
  const todayStr = _habitToday();
  const activeTab = window.thpActiveTab || 'tasks';

  const rangeStart = window.habitRangeStart  || null;
  const rangeEnd   = window.habitRangeEnd    || null;
  const singleDay  = window.habitSelectedDate || todayStr;
  const isRange    = !!(rangeStart && rangeEnd && rangeStart !== rangeEnd);

  let headerDate;
  if (isRange) {
    const fmtS = _habitFmtHeaderDate(rangeStart);
    const fmtE = _habitFmtHeaderDate(rangeEnd);
    headerDate = `<span>${fmtS}</span><span class="hd-range-sep"> — </span><span>${fmtE}</span>`;
  } else {
    const isToday = singleDay === todayStr;
    headerDate = isToday
      ? `Today, <span>${_habitFmtHeaderDate(todayStr)}</span>`
      : `<span>${_habitFmtDow(singleDay)}, ${_habitFmtHeaderDate(singleDay)}</span>`;
  }

  let pct, pctIcon, pctFn;
  if (activeTab === 'habits') {
    pctFn = isAdminCtx ? _thpAggHabitDayPct : _hbDayPct;
    const habits = isRange ? [] : (isAdminCtx ? _thpHabitsForDate(singleDay) : _habitGetHabitsForDate(singleDay, id)); // range mode is Tasks-only for now
    const done = isAdminCtx
      ? habits.filter(h => _habitCompleted(h.id, h._iid, singleDay)).length
      : habits.filter(h => _habitCompleted(h.id, id, singleDay)).length;
    pct = habits.length ? Math.round(done / habits.length * 100) : 0;
    pctIcon = `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3a9 9 0 1 0 9 9"/><path d="M12 3v3"/><path d="m12 12 4-4"/></svg>`;
  } else {
    pctFn = isAdminCtx ? _thpAggTaskDayPct : _habitDayPct;
    const tasks = isAdminCtx
      ? (isRange ? _thpTasksForRange(rangeStart, rangeEnd) : _thpTasksForDate(singleDay))
      : (isRange ? _habitTasksForRange(rangeStart, rangeEnd, id) : _habitTasksForDate(singleDay, id));
    const done = isAdminCtx
      ? tasks.filter(t => isTaskDone(t.id, t._iid)).length
      : tasks.filter(t => isTaskDone(t.id, id)).length;
    pct = tasks.length ? ((done / tasks.length) * 100).toFixed(1) : '0.0';
    pctIcon = `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>`;
  }

  const dateStripHtml = _buildDateStrip(id, pctFn);

  // All/Due counts + which state var/setter to use — adapts to whichever
  // tab is active, but the ROW ITSELF is one persistent element (like the
  // date-strip), so swiping only updates its numbers, never its position.
  let totalCount, dueN, statusF, statusSetter;
  if (activeTab === 'habits') {
    const habits = isRange ? [] : (isAdminCtx ? _thpHabitsForDate(singleDay) : _habitGetHabitsForDate(singleDay, id));
    totalCount = habits.length;
    dueN = isAdminCtx
      ? habits.filter(h => !_habitCompleted(h.id, h._iid, singleDay)).length
      : habits.filter(h => !_habitCompleted(h.id, id, singleDay)).length;
    statusF = window.habitsStatusFilter || 'All';
    statusSetter = 'habitsSetStatusFilter';
  } else {
    const tasks = isAdminCtx
      ? (isRange ? _thpTasksForRange(rangeStart, rangeEnd) : _thpTasksForDate(singleDay))
      : (isRange ? _habitTasksForRange(rangeStart, rangeEnd, id) : _habitTasksForDate(singleDay, id));
    totalCount = tasks.length;
    dueN = isAdminCtx
      ? tasks.filter(t => !isTaskDone(t.id, t._iid)).length
      : tasks.filter(t => !isTaskDone(t.id, id)).length;
    statusF = window.habitStatusFilter || 'All';
    statusSetter = 'habitSetStatusFilter';
  }

  // Admin-only: funnel button opens the existing intern-filter bottom sheet
  // (openAdminTaskInternFilter) — this is the real, already-built/styled
  // filter UI admin's task page had; reusing it as-is rather than inventing
  // a new pills row.
  const filterIntern = isAdminCtx ? (window.atFilterAssignee || '') : '';
  const internFilterBtn = isAdminCtx
    ? `<button class="at-filter-btn ${filterIntern ? 'at-filter-active' : ''}" onclick="openAdminTaskInternFilter()" title="Filter by intern">
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
      </button>`
    : '';

  box.innerHTML = `<div class="hd-wrap">
    <div class="hd-top-row">
      <div class="hd-date-label hd-date-clickable" onclick="openTaskCalendar()" title="Open calendar" style="flex:1;">
        ${headerDate}
      </div>
      ${internFilterBtn}
      <div class="hd-pct-bare">${pctIcon} <span class="hd-pct-num">${pct}%</span></div>
    </div>
    <div class="date-strip-scroll" id="habitDateStrip">${dateStripHtml}</div>
  </div>
  <div class="hd-filter-bar">
    <div class="hd-status-group">
      <div class="hd-status-btn${statusF==='All'?' hd-status-active':''}" onclick="${statusSetter}('All')">All (${totalCount})</div>
      <div class="hd-status-btn${statusF==='Due'?' hd-status-active':''}" onclick="${statusSetter}('Due')">Due (${dueN})</div>
    </div>
    ${_thpBuildCatRow()}
  </div>`;

  requestAnimationFrame(() => {
    const strip = document.getElementById('habitDateStrip');
    if (!strip) return;
    const sel = strip.querySelector('.ds-range-start, .ds-day.selected, .ds-day.today');
    if (sel) {
      const stripRect = strip.getBoundingClientRect();
      const selRect   = sel.getBoundingClientRect();
      const targetScroll = strip.scrollLeft + selRect.left - stripRect.left
                         - (stripRect.width / 2) + (selRect.width / 2);
      strip.scrollTo({ left: targetScroll, behavior: 'smooth' });
    }
  });
  if (window.lucide) lucide.createIcons();
}

// Shared category icons — used when building the category row inside
// either pane's own filter-bar (Tasks: same row as All/Due; Habits: its
// own row), so both stay visually identical to how they always were.
const _thpCatIcons = {
  All:      `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none;flex-shrink:0;"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>`,
  Office:   `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none;flex-shrink:0;"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2"/><line x1="12" y1="12" x2="12" y2="16"/><line x1="10" y1="14" x2="14" y2="14"/></svg>`,
  Academic: `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="pointer-events:none;flex-shrink:0;"><path d="M22 10v6M2 10l10-5 10 5-10 5z"/><path d="M6 12v5c3 3 9 3 12 0v-5"/></svg>`,
  Personal: `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="currentColor" stroke="currentColor" stroke-width="0" style="pointer-events:none;flex-shrink:0;"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>`,
};
function _thpBuildCatRow() {
  const catF = window.habitCatFilter || 'All';
  return `<div class="hd-cat-scroll">
    ${['All','Office','Academic','Personal'].map(c => {
      const isActive = catF === c;
      return `<div class="hd-cat-pill${isActive?' hd-cat-active':''}" onclick="setSharedCatFilter('${c}')">
        <span class="hd-cat-icon">${_thpCatIcons[c]||''}</span>
        <span>${c}</span>
      </div>`;
    }).join('')}
  </div>`;
}

// Shared category filter — used by BOTH Tasks and Habits (one state, not
// two independent ones); each pane still renders its own copy of the row
// in its original position, but they read/write the same window.habitCatFilter.
function setSharedCatFilter(v) {
  window.habitCatFilter = v;
  _renderSharedHeader();
  _renderTasksPageBody();
  _renderHabitsPageBody();
}

function _renderTasksPageBody() {
  const ca = document.getElementById('thpTasksPage');
  if (!ca) return;
  const isAdminCtx = currentRole === 'admin';
  const id       = currentUser.id;
  const todayStr = _habitToday();

  const rangeStart = window.habitRangeStart  || null;
  const rangeEnd   = window.habitRangeEnd    || null;
  const singleDay  = window.habitSelectedDate || todayStr;
  const isRange    = !!(rangeStart && rangeEnd && rangeStart !== rangeEnd);

  const statusF = window.habitStatusFilter || 'All';
  const catF    = window.habitCatFilter    || 'All';
  let taskListHtml;

  if (isAdminCtx) {
    let tasks = isRange ? _thpTasksForRange(rangeStart, rangeEnd) : _thpTasksForDate(singleDay);
    if (statusF === 'Due') tasks = tasks.filter(t => !isTaskDone(t.id, t._iid));
    if (catF !== 'All') tasks = tasks.filter(t => (t.category || 'Personal') === catF);
    const interns = INTERNS.filter(i => i.id !== 99);
    const filterIntern = window.atFilterAssignee || '';
    taskListHtml = tasks.length === 0
      ? `<div class="habit-empty"><div class="habit-empty-icon">🎉</div><div class="habit-empty-msg">No tasks here</div><div class="habit-empty-sub">${statusF === 'Due' ? 'All caught up!' : isRange ? 'No tasks in this range.' : 'Nothing assigned for this day.'}</div></div>`
      : `<div class="habit-list">${tasks.map(t => _buildAdminTaskRow(t, interns, filterIntern)).join('')}</div>`;
    const selBar = _adminSelMode
      ? `<div class="task-select-bar" id="adminSelBar"><span>${_adminSelIds.size} selected</span><div style="display:flex;gap:8px;"><button onclick="cancelAdminSel()">Cancel</button><button class="danger" onclick="deleteSelectedAdminTasks()">🗑 Delete</button></div></div>`
      : '';
    taskListHtml += selBar;
  } else {
    let tasks = isRange
      ? _habitTasksForRange(rangeStart, rangeEnd, id)
      : _habitTasksForDate(singleDay, id);
    if (statusF === 'Due') tasks = tasks.filter(t => !isTaskDone(t.id, id));
    if (catF !== 'All') tasks = tasks.filter(t => (t.category || 'Personal') === catF);
    taskListHtml = tasks.length === 0
      ? `<div class="habit-empty"><div class="habit-empty-icon">🎉</div><div class="habit-empty-msg">No tasks here</div><div class="habit-empty-sub">${statusF === 'Due' ? 'All caught up!' : isRange ? 'No tasks in this range.' : 'Nothing assigned for this day.'}</div></div>`
      : `<div class="habit-list">${tasks.map(t => _buildHabitRow(t, id)).join('')}</div>`;
  }

  ca.innerHTML = `<div class="habit-page-wrap">${taskListHtml}</div>`;
  initLongPressAll();
  if (window.lucide) lucide.createIcons();
}

// ── Date strip: simple single-tap to jump to a day ───────────────────────────
function _dsHandleClick(ds) {
  window.habitSelectedDate = ds;
  window.habitRangeStart   = null;
  window.habitRangeEnd     = null;
  _thpRefreshAll();
}
function _dsHandleDblClick(ds) { _dsHandleClick(ds); }

function _dsClearRange() {
  window.habitRangeStart   = null;
  window.habitRangeEnd     = null;
  window.habitSelectedDate = _habitToday();
  _thpRefreshAll();
}

// ── Full calendar bottom-sheet ────────────────────────────────────────────────
// State: which month is displayed, and pending selection inside the sheet
let _calViewYear  = null;
let _calViewMonth = null;  // 0-based
let _calSelStart  = null;  // pending range start (YYYY-MM-DD)
let _calSelEnd    = null;  // pending range end   (YYYY-MM-DD)

function openTaskCalendar() {
  const todayStr = _habitToday();
  const now      = new Date(todayStr + 'T00:00:00');
  _calViewYear   = now.getFullYear();
  _calViewMonth  = now.getMonth();

  // Fix 2: Always open with clean state — no pre-seeded date.
  // First tap will set start, second tap sets end.
  _calSelStart = null;
  _calSelEnd   = null;

  _renderTaskCalendar();
}

function _renderTaskCalendar() {
  document.getElementById('taskCalSheet')?.remove();

  const todayStr    = _habitToday();
  const y = _calViewYear, m = _calViewMonth;
  const monthName   = new Date(y, m, 1).toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  const firstDow    = new Date(y, m, 1).getDay();  // 0=Sun
  const daysInMonth = new Date(y, m + 1, 0).getDate();

  // Build grid cells
  let cells = '';
  for (let i = 0; i < firstDow; i++) cells += `<div class="tc-cell tc-empty"></div>`;

  for (let d = 1; d <= daysInMonth; d++) {
    const ds     = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const isToday = ds === todayStr;
    const isStart = _calSelStart && ds === _calSelStart;
    const isEnd   = _calSelEnd   && ds === _calSelEnd;
    const inRange = _calSelStart && _calSelEnd && ds > _calSelStart && ds < _calSelEnd;

    let cls = 'tc-cell';
    if (isToday)  cls += ' tc-today';
    if (isStart && !isEnd)  cls += ' tc-sel-start';
    if (isEnd   && !isStart) cls += ' tc-sel-end';
    if (isStart && isEnd)   cls += ' tc-sel-start tc-sel-single';
    if (inRange)  cls += ' tc-in-range';

    cells += `<div class="${cls}" onclick="_calTapDay('${ds}')">${d}</div>`;
  }

  // Hint — guides user through the 2-tap flow
  let hint = '';
  if (!_calSelStart) {
    hint = 'Tap a date to select start';
  } else if (!_calSelEnd) {
    hint = `<span style="color:var(--accent);font-weight:700;">${_habitFmtHeaderDate(_calSelStart)}</span> &nbsp;→&nbsp; Tap end date`;
  } else {
    hint = `<span style="color:var(--accent);font-weight:700;">${_habitFmtHeaderDate(_calSelStart)}</span>
            &nbsp;—&nbsp;
            <span style="color:var(--accent);font-weight:700;">${_habitFmtHeaderDate(_calSelEnd)}</span>`;
  }

  const sheet = document.createElement('div');
  sheet.id    = 'taskCalSheet';
  sheet.innerHTML = `
    <div class="tc-backdrop" onclick="_closeTaskCalendar()"></div>
    <div class="tc-sheet" id="tcSheetInner">
      <div class="tc-handle"></div>
      <div class="tc-header">
        <button class="tc-nav-btn" onclick="_calPrevMonth()">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="15 18 9 12 15 6"/></svg>
        </button>
        <span class="tc-month-label">${monthName}</span>
        <button class="tc-nav-btn" onclick="_calNextMonth()">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="9 18 15 12 9 6"/></svg>
        </button>
      </div>
      <div class="tc-dow-row">
        ${['Su','Mo','Tu','We','Th','Fr','Sa'].map(d=>`<div class="tc-dow">${d}</div>`).join('')}
      </div>
      <div class="tc-grid">${cells}</div>
      <div class="tc-hint">${hint}</div>
      <div class="tc-actions">
        <button class="tc-btn-clear" onclick="_calClear()">Clear</button>
        <button class="tc-btn-apply" onclick="_calApply()">Apply</button>
      </div>
    </div>`;

  document.body.appendChild(sheet);
  requestAnimationFrame(() => sheet.querySelector('#tcSheetInner').classList.add('tc-sheet-open'));
}

function _calTapDay(ds) {
  if (!_calSelStart || (_calSelStart && _calSelEnd)) {
    // Fresh start
    _calSelStart = ds;
    _calSelEnd   = null;
  } else {
    // Have start, set end
    if (ds < _calSelStart) {
      _calSelEnd   = _calSelStart;
      _calSelStart = ds;
    } else if (ds === _calSelStart) {
      // Tapping same day twice = single day selection
      _calSelEnd = null;
    } else {
      _calSelEnd = ds;
    }
  }
  _renderTaskCalendar();
}

function _calPrevMonth() {
  _calViewMonth--;
  if (_calViewMonth < 0) { _calViewMonth = 11; _calViewYear--; }
  _renderTaskCalendar();
}
function _calNextMonth() {
  _calViewMonth++;
  if (_calViewMonth > 11) { _calViewMonth = 0; _calViewYear++; }
  _renderTaskCalendar();
}
function _calClear() {
  _calSelStart = null; _calSelEnd = null;
  window.habitRangeStart   = null;
  window.habitRangeEnd     = null;
  window.habitSelectedDate = _habitToday();
  document.getElementById('taskCalSheet')?.remove();
  _thpRefreshAll();
}
function _calApply() {
  if (_calSelStart) {
    if (_calSelEnd && _calSelEnd !== _calSelStart) {
      // Range mode
      window.habitRangeStart   = _calSelStart;
      window.habitRangeEnd     = _calSelEnd;
      window.habitSelectedDate = _calSelStart;
    } else {
      // Single day
      window.habitRangeStart   = null;
      window.habitRangeEnd     = null;
      window.habitSelectedDate = _calSelStart;
    }
  }
  document.getElementById('taskCalSheet')?.remove();
  _thpRefreshAll();
}
function _closeTaskCalendar() {
  const inner = document.getElementById('tcSheetInner');
  if (inner) {
    inner.classList.remove('tc-sheet-open');
    setTimeout(() => document.getElementById('taskCalSheet')?.remove(), 280);
  }
}



function setInternTaskCat(cat) {
  window.habitCatFilter = cat;
  _thpRefreshAll();
}

function habitSelectDate(ds) { window.habitSelectedDate = ds; window.habitRangeStart = null; window.habitRangeEnd = null; _thpRefreshAll(); }
function habitSetStatusFilter(v) { window.habitStatusFilter = v; _thpRefreshAll(); }
function habitsSetStatusFilter(v) { window.habitsStatusFilter = v; _renderSharedHeader(); _renderHabitsPageBody(); }
function habitSetCatFilter(v)    { window.habitCatFilter = v;    _thpRefreshAll(); }
function habitCompleteTask(tid, iid, el) { completeTask(tid, iid, el, 'tasks'); }

function openHabitInfoPopup(tid, anchorEl) {
  closeHabitInfoPopup();
  const task = db.tasks.find(t=>t.id==tid); if(!task) return;
  const tags=[];
  if(task.sharedWith&&task.sharedWith.length>0) tags.push({icon:'👥',val:`Shared ${task.sharedWith.length}+`});
  const rd=task.instanceDate||task.createdDate||task.dueDate;
  if(rd) tags.push({icon:'📅',val:new Date(rd+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})});
  const rl=task.repeat?(typeof repeatLabel==='function'?repeatLabel(task.repeat):'Repeating'):task.templateId?'Daily':null;
  if(rl) tags.push({icon:'🔁',val:rl});
  if(task.points) tags.push({icon:'⚡',val:`+${task.points} XP`,cls:'points'});
  if(task.category) tags.push({icon:'🏷',val:task.category});
  if(!tags.length) tags.push({icon:'ℹ',val:'No extra info'});
  const tagsHtml=tags.map(t=>`<div class="info-popup-tag ${t.cls||''}"><div class="info-popup-tag-icon">${t.icon}</div><div class="info-popup-tag-val">${sanitize(t.val)}</div></div>`).join('');
  const ttl=task.title.length>28?task.title.slice(0,26)+'…':task.title;
  const ov=document.createElement('div'); ov.className='info-popup-overlay'; ov.id='habitInfoOverlay'; ov.onclick=closeHabitInfoPopup;
  const pop=document.createElement('div'); pop.className='info-popup'; pop.id='habitInfoPopup';
  pop.innerHTML=`<div class="info-popup-title">${sanitize(ttl)}</div><div class="info-popup-tags">${tagsHtml}</div>`;
  pop.onclick=e=>e.stopPropagation();
  document.body.appendChild(ov); document.body.appendChild(pop);
  requestAnimationFrame(()=>{
    const r=anchorEl.getBoundingClientRect(),pw=pop.offsetWidth||240,ph=pop.offsetHeight||140;
    let top=r.bottom+8,left=r.left+r.width/2-pw/2;
    if(left<12)left=12; if(left+pw>window.innerWidth-12)left=window.innerWidth-pw-12;
    if(top+ph>window.innerHeight-20)top=r.top-ph-8;
    pop.style.top=top+'px'; pop.style.left=left+'px';
  });
}
function closeHabitInfoPopup() { document.getElementById('habitInfoOverlay')?.remove(); document.getElementById('habitInfoPopup')?.remove(); }

function openTsd() {
  // Populate name and date
  const name = currentUser ? currentUser.name : '';
  const el = document.getElementById('tsdName'); if (el) el.textContent = name;
  const dt = document.getElementById('tsdDate');
  if (dt) {
    const d = new Date(); 
    dt.textContent = d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
  }
  const lbl = document.getElementById('tsdDarkLabel');
  if (lbl) lbl.textContent = document.body.getAttribute('data-theme') === 'dark' ? 'On' : 'Off';
  document.getElementById('tsd')?.classList.add('open');
  document.getElementById('tsdOverlay')?.classList.add('visible');
}

function closeTsd() {
  document.getElementById('tsd')?.classList.remove('open');
  document.getElementById('tsdOverlay')?.classList.remove('visible');
}

function _populateTaskFilterDropdown() {
  const dd = document.getElementById('itFilterDropdown');
  if (!dd) return;
  const status = window.internTaskStatus || 'Pending';
  dd.innerHTML = ['Pending','All','Completed'].map(s=>
    `<div class="it-filter-opt ${status===s?'active':''}" onclick="setTaskStatus('${s}')">${s}</div>`
  ).join('');
}

function toggleTaskSearch() {
  const bar = document.getElementById('itSearchBar');
  if (!bar) return;
  const visible = bar.style.display !== 'none';
  bar.style.display = visible ? 'none' : 'flex';
  if (!visible) { const inp = document.getElementById('itSearchInput'); if (inp) inp.focus(); }
}

function toggleTaskFilter() {
  const dd = document.getElementById('itFilterDropdown');
  if (!dd) return;
  _populateTaskFilterDropdown();
  dd.style.display = dd.style.display === 'none' ? 'block' : 'none';
}

function setTaskStatus(status) {
  window.internTaskStatus = status;
  const dd = document.getElementById('itFilterDropdown');
  if (dd) dd.style.display = 'none';
  _thpRefreshAll();
}

function _populateComplaintFilterDropdown() {
  const dd = document.getElementById('icFilterDropdown');
  if (!dd) return;
  const status = window.internComplaintFilter || 'All';
  dd.innerHTML = ['All','Resolved','Unresolved'].map(s=>
    `<div class="it-filter-opt ${status===s?'active':''}" onclick="setComplaintFilter('${s}')">${s}</div>`
  ).join('');
}

function toggleComplaintFilter() {
  const dd = document.getElementById('icFilterDropdown');
  if (!dd) return;
  _populateComplaintFilterDropdown();
  dd.style.display = dd.style.display === 'none' ? 'block' : 'none';
}

function setComplaintFilter(status) {
  window.internComplaintFilter = status;
  const dd = document.getElementById('icFilterDropdown');
  if (dd) dd.style.display = 'none';
  renderInternComplaints(document.getElementById('contentArea'));
}

