// ── MORE SHEET ──────────────────────────────────────────────────
function openMoreSheet() {
  // Deactivate any nav pill highlight when "More" is tapped
  document.getElementById('taskSheetWrapper')?.remove();

  const isAdmin = currentRole === 'admin';
  const profileFn  = isAdmin ? "navigateTo('adminAccountSettings')" : "navigateTo('internProfile')";

  const rows = [
    {
      icon: `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>`,
      color: '#3b82f6', bg: 'rgba(59,130,246,.12)',
      label: 'Profile', sub: 'View your profile & stats',
      action: `closeMoreSheet();${profileFn}`, soon: false
    },
    {
      icon: `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>`,
      color: '#f59e0b', bg: 'rgba(245,158,11,.12)',
      label: 'Leaderboard', sub: 'Rankings & leagues',
      action: `closeMoreSheet();openComingSoon()`, soon: true
    },
    {
      icon: `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>`,
      color: '#8b5cf6', bg: 'rgba(139,92,246,.12)',
      label: 'Rewards', sub: isAdmin ? 'Coin economy, store & approvals' : 'My coins & reward store',
      action: `closeMoreSheet();navigateTo('${isAdmin?'adminRewards':'internRewards'}')`, soon: false
    },
    {
      icon: `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>`,
      color: '#06b6d4', bg: 'rgba(6,182,212,.12)',
      label: 'Complaints', sub: 'Submit or view complaints',
      action: `closeMoreSheet();navigateTo('${isAdmin?'adminComplaints':'internComplaints'}')`, soon: false
    },
  ];

  if (isAdmin) {
    rows.push({
      icon: `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/></svg>`,
      color: '#e85d26', bg: 'rgba(232,93,38,.12)',
      label: 'Toolkit', sub: 'Manage training features',
      action: `closeMoreSheet();navigateTo('adminToolkit')`, soon: false
    });
  }

  const rowsHtml = rows.map((r, idx) => `
    <div class="more-row${idx < rows.length - 1 ? ' more-row-divider' : ''}" onclick="${r.action}">
      <div class="more-row-icon" style="background:${r.bg};color:${r.color};">${r.icon}</div>
      <div class="more-row-body">
        <div class="more-row-title">${r.label}</div>
        <div class="more-row-sub">${r.sub}</div>
      </div>
      ${r.soon ? '<span class="more-soon-badge">Soon</span>' : ''}
      <svg class="more-row-chevron" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
    </div>`).join('');

  document.getElementById('moreSheetWrapper')?.remove();
  const w = document.createElement('div'); w.id = 'moreSheetWrapper';
  w.innerHTML = `
    <div class="more-overlay" onclick="closeMoreSheet()"></div>
    <div class="more-sheet" id="moreSheet">
      <div class="more-handle"></div>
      <div class="more-rows">${rowsHtml}</div>
    </div>`;
  document.body.appendChild(w);
  requestAnimationFrame(() => {
    document.getElementById('moreSheet')?.classList.add('open');
    w.querySelector('.more-overlay')?.classList.add('visible');
    // Clear all nav buttons first, then highlight More only
    document.querySelectorAll('.duo-nav-btn').forEach(b => b.classList.remove('active'));
    document.getElementById('mbn-more')?.classList.add('active');
    document.getElementById('ambn-more')?.classList.add('active');
  });
}

function closeMoreSheet() {
  const s  = document.getElementById('moreSheet');
  const ov = document.querySelector('.more-overlay');
  if (s)  s.classList.remove('open');
  if (ov) ov.classList.remove('visible');
  setTimeout(() => document.getElementById('moreSheetWrapper')?.remove(), 300);
  // Remove More highlight, restore the actual active page
  document.getElementById('mbn-more')?.classList.remove('active');
  document.getElementById('ambn-more')?.classList.remove('active');
}


