function openLogAttendance(cat) {
  const td    = today();
  const parts = td.split('-');
  const display = new Date(td + 'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
  const dayName = new Date(td + 'T00:00:00').toLocaleDateString('en-US',{weekday:'long'});

  document.getElementById('attPanelWrapper')?.remove();
  const w = document.createElement('div'); w.id = 'attPanelWrapper';
  w.innerHTML = `
    <div class="att-panel-overlay" onclick="closeAttPanel()"></div>
    <div class="att-panel" id="attPanel">
      <div class="att-panel-header">
        <button class="att-back" onclick="closeAttPanel()">
          <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
        </button>
        <div>
          <div class="att-panel-title">Log Attendance</div>
          <div class="att-panel-sub">${cat}</div>
        </div>
        <div style="width:38px;"></div>
      </div>
      <div class="att-panel-body">
        <!-- Today date (locked) -->
        <div class="att-field-card">
          <div class="att-field-label">Date</div>
          <div class="att-date-chip">
            <div>
              <div class="att-date-val">${display}</div>
              <div class="att-date-day">${dayName}</div>
            </div>
            <div class="att-lock-badge">
              <svg xmlns="http://www.w3.org/2000/svg" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
              Today only
            </div>
          </div>
        </div>

        <!-- Status: Present / Absent / Leave -->
        <div class="att-field-card">
          <div class="att-field-label">Status</div>
          <div class="att-status-grid">
            <div class="att-status-btn att-status-present active" id="attStatusPresent" onclick="selectAttStatus('present')">Present</div>
            <div class="att-status-btn att-status-absent" id="attStatusAbsent" onclick="selectAttStatus('absent')">Absent</div>
            <div class="att-status-btn att-status-leave" id="attStatusLeave" onclick="selectAttStatus('leave')">Leave</div>
          </div>
        </div>

        <!-- Send Request toggle -->
        <div class="att-toggle-card" id="attSendReqCard">
          <div>
            <div class="att-toggle-title">Send Request to Admin</div>
            <div class="att-toggle-sub">Admin will approve this log entry</div>
          </div>
          <label class="toggle">
            <input type="checkbox" id="attSendReqToggle" onchange="toggleAttReqMode()">
            <span class="toggle-slider"></span>
          </label>
        </div>

        <!-- Contributor code (shown when toggle off) -->
        <div class="att-field-card" id="attCodeWrap">
          <div class="att-field-label">Contributor Code</div>
          <input type="password" class="att-code-input" id="attCode" placeholder="Enter code…" autocomplete="off">
        </div>

        <!-- Note (shown when toggle on) -->
        <div class="att-field-card" id="attNoteWrap" style="display:none;">
          <div class="att-field-label">Note (optional)</div>
          <textarea class="att-code-input" id="attNote" placeholder="Add a reason or note…" rows="3" style="resize:none;height:auto;"></textarea>
        </div>

        <div style="height:20px;"></div>
      </div>
      <div class="att-panel-footer">
        <button class="att-submit-btn" id="attSubmitBtn" onclick="submitAttendance('${cat}','${td}')">Log Attendance</button>
      </div>
    </div>`;
  document.body.appendChild(w);
  window._attStatus = 'present';
  requestAnimationFrame(() => {
    document.getElementById('attPanel')?.classList.add('open');
    w.querySelector('.att-panel-overlay')?.classList.add('visible');
  });
}

function closeAttPanel() {
  const p = document.getElementById('attPanel');
  const ov = document.querySelector('#attPanelWrapper .att-panel-overlay');
  if (p) p.classList.remove('open');
  if (ov) ov.classList.remove('visible');
  setTimeout(() => document.getElementById('attPanelWrapper')?.remove(), 300);
}

function selectAttStatus(status) {
  window._attStatus = status;
  ['present','absent','leave'].forEach(s => {
    const el = document.getElementById('attStatus' + s[0].toUpperCase() + s.slice(1));
    if (el) el.classList.toggle('active', s === status);
  });
}

function toggleAttReqMode() {
  const on  = document.getElementById('attSendReqToggle').checked;
  const cw  = document.getElementById('attCodeWrap');
  const nw  = document.getElementById('attNoteWrap');
  const btn = document.getElementById('attSubmitBtn');
  if (cw) cw.style.display = on ? 'none' : '';
  if (nw) nw.style.display = on ? '' : 'none';
  if (btn) btn.textContent  = on ? 'Submit Request' : 'Log Attendance';
}

async function submitAttendance(cat, date) {
  const status  = window._attStatus || 'present';
  const sendReq = document.getElementById('attSendReqToggle')?.checked;
  const code    = document.getElementById('attCode')?.value.trim();
  const note    = document.getElementById('attNote')?.value.trim();
  const s       = db.submissions[currentUser.id];
  const catKey  = CAT_KEYS[cat];

  if (sendReq) {
    // Submit as pending request to admin
    db.pendingRequests = db.pendingRequests || [];
    db.pendingRequests.push({
      id: 'req-' + Date.now(), internId: currentUser.id,
      type: 'attendance', category: cat, status: 'pending',
      date, attStatus: status, note, taskTitle: cat,
      requestDate: today()
    });
    db.adminNotifications.unshift({
      id:'an-'+Date.now(), msg:`${currentUser.name} sent attendance request (${cat})`,
      type:'request', read:false, date:today(), internId:currentUser.id
    });
  } else {
    // Verify code
    if (!code) { showToast('Enter contributor code', 'error'); return; }
    const codeHash = await sha256(code);
    const contrib  = db.contributors.find(c => c.codeHash === codeHash);
    if (!contrib) { showToast('Invalid code', 'error'); return; }
    if (contrib.taskApprovalOnly) { showToast('Contributor is for task approval only', 'error'); return; }

    // Save attendance log
    s.attendanceLogs = s.attendanceLogs || [];
    s.attendanceLogs.push({ date, cat, status, addedAt: Date.now() });

    // Increment counter
    if (status === 'present') {
      s[catKey] = (s[catKey] || 0) + 1;
      const catPts = db.catPoints || DEF_POINTS;
      const earned = Math.max(0, parseInt(catPts[cat]) || 5);
      s.points = Math.max(0, (s.points||0) + earned);
      s.pointHistory = s.pointHistory || [];
      s.pointHistory.unshift({type:'entry', label:cat, pts:earned, date});
    }
  }
  db.submissions[currentUser.id] = s;
  playSuccessSound();
  closeAttPanel();
  await saveAndRefresh(sendReq ? 'Request sent to admin!' : 'Attendance logged!', 'internDashboard');
}

// ── Work Log Entry form ──────────────────────────────────────────
function openLogEntry(cat) {
  const catColors = {
    Bugs: { color:'#ef4444', bg:'rgba(239,68,68,.15)', prefix:'BUG', key:'bugs' },
    Projects: { color:'#059669', bg:'rgba(5,150,105,.15)', prefix:'PRJ', key:'project' },
    Suggestions: { color:'#f59e0b', bg:'rgba(245,158,11,.15)', prefix:'SUG', key:'suggestions' },
  };
  const c = catColors[cat] || catColors['Bugs'];
  const s = db.submissions[currentUser.id];
  const entries = (s.entries||[]).filter(e => e.cat === cat);
  const nextId  = `#${c.prefix}-${String(entries.length+1).padStart(3,'0')}`;

  openModal(`<div class="modal-title" style="color:${c.color};">+ ${cat === 'Bugs' ? 'Report Bug' : cat === 'Projects' ? 'Log Project' : 'Add Suggestion'}</div>
    <div style="font-size:12px;color:var(--text3);margin-bottom:14px;">ID: <strong style="color:${c.color};">${nextId}</strong></div>
    <div class="form-group"><label>Title *</label><input type="text" id="leTitle" placeholder="${cat === 'Bugs' ? 'Brief bug description' : cat === 'Projects' ? 'Project name' : 'Your suggestion'}"></div>
    <div class="form-group"><label>Description</label><textarea id="leDesc" rows="3" placeholder="${cat === 'Bugs' ? 'Steps to reproduce, expected vs actual…' : cat === 'Projects' ? 'What you built, tech used…' : 'Details of your idea…'}"></textarea></div>
    <div class="form-group"><label>Link (optional)</label><input type="url" id="leLink" placeholder="https://github.com/… or any URL"></div>
    <div class="form-group"><label>Contributor Code</label><input type="password" id="leCode" placeholder="Enter code" autocomplete="off"></div>
    <div class="modal-actions">
      <button class="btn btn-secondary" onclick="closeModal()">Cancel</button>
      <button class="btn btn-primary" onclick="submitLogEntry('${cat}')" style="background:${c.color};border-color:${c.color};">Submit</button>
    </div>`);
}

async function submitLogEntry(cat) {
  const title = document.getElementById('leTitle')?.value.trim();
  if (!title) { showToast('Title required', 'error'); return; }
  const code = document.getElementById('leCode')?.value.trim();
  if (!code) { showToast('Enter contributor code', 'error'); return; }
  const codeHash = await sha256(code);
  const contrib  = db.contributors.find(c => c.codeHash === codeHash);
  if (!contrib) { showToast('Invalid code', 'error'); return; }
  if (contrib.taskApprovalOnly) { showToast('This contributor is for task approval only', 'error'); return; }

  const catColors = { Bugs:'bugs', Projects:'project', Suggestions:'suggestions' };
  const catPrefixes = { Bugs:'BUG', Projects:'PRJ', Suggestions:'SUG' };
  const catKey = catColors[cat];
  const s = db.submissions[currentUser.id];
  s.entries = s.entries || [];
  const entries = s.entries.filter(e => e.cat === cat);
  const id = `#${catPrefixes[cat]}-${String(entries.length+1).padStart(3,'0')}`;

  s.entries.push({
    id, cat, title,
    desc: document.getElementById('leDesc')?.value || '',
    link: document.getElementById('leLink')?.value || '',
    date: today(), addedAt: Date.now()
  });
  s[catKey] = (s[catKey]||0) + 1;
  const catPts = db.catPoints || DEF_POINTS;
  const catLabel = cat === 'Bugs' ? 'Bugs' : cat === 'Projects' ? 'Projects' : 'Suggestions';
  const fullCat  = cat === 'Bugs' ? 'Bugs' : cat === 'Projects' ? 'Projects' : 'Suggestions';
  const earned   = Math.max(0, parseInt(catPts[fullCat]) || 5);
  s.points = Math.max(0,(s.points||0)+earned);
  s.pointHistory = s.pointHistory||[];
  s.pointHistory.unshift({type:'entry',label:cat,pts:earned,date:today()});
  db.submissions[currentUser.id] = s;
  playSuccessSound();
  closeModal();
  await saveAndRefresh(`${id} logged! +${earned} pts`, 'internDashboard');
}


