async function ntdChangeStatus(taskId, iid, newStatus) {
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const uid = parseInt(iid);
  const key = taskId + '-' + uid;
  let coinsEarned = 0;

  if (newStatus === 'Completed') {
    // Fix 2: write to db.taskCompletions — the same store isTaskDone() reads
    if (!db.taskCompletions[key]?.done) {
      db.taskCompletions[key] = { done: true };
      const pts = task.points || 0;
      if (pts) {
        if (!db.submissions[uid]) db.submissions[uid] = { points: 0 };
        db.submissions[uid].points = (db.submissions[uid].points || 0) + pts;
        db.submissions[uid].pointHistory = db.submissions[uid].pointHistory || [];
        db.submissions[uid].pointHistory.unshift({ type: 'task', label: task.title, pts, date: today() });
        // This flow was never converting XP into coins — fixed to match
        // how task completion elsewhere in the app already does it.
        coinsEarned = awardCoins(uid, pts, 'task', task.title, taskId);
      }
    }
    if (task.inProgress) task.inProgress = task.inProgress.filter(id => id !== uid);
  } else {
    delete db.taskCompletions[key];
    if (task.inProgress) task.inProgress = task.inProgress.filter(id => id !== uid);
  }

  markDirty();
  try {
    await fbPatch('taskCompletions', db.taskCompletions);
    if (coinsEarned > 0) await saveWallet(uid);
  } catch(e) {}
  showToast(newStatus === 'Completed' ? (coinsEarned > 0 ? `✓ Task completed! +${coinsEarned} coin${coinsEarned!==1?'s':''}` : '✓ Task completed!') : 'Status updated', 'success');
  updateBadges && updateBadges();

  // Refresh status badge
  const isOverdue = !isTaskDone(taskId, uid) && task.dueDate && new Date(task.dueDate + 'T23:59:59') < new Date();
  const nowStatus = isTaskDone(taskId, uid) ? 'Completed' : isOverdue ? 'Pending' : 'To Do';
  const nowColor  = nowStatus === 'Completed' ? '#22c55e' : nowStatus === 'Pending' ? '#ef4444' : '#94a3b8';
  const badge = document.querySelector('.ntd-status-badge');
  if (badge) {
    const dot = badge.querySelector('.ntd-spill-dot');
    const lbl = badge.querySelectorAll('span')[1];
    if (dot) dot.style.background = nowColor;
    if (lbl) lbl.textContent = nowStatus;
  }

  if (newStatus === 'Completed') {
    // Fix 2: disable ALL hero action buttons
    document.querySelectorAll('#ntdPage .ntd-hero-btns .ntd-hero-act-btn').forEach(b => {
      b.disabled = true;
      b.classList.add('ntd-btn-disabled');
      b.onclick = null;
    });
    // Turn checkmark green
    const btns = document.querySelectorAll('#ntdPage .ntd-hero-btns .ntd-hero-act-btn');
    const checkBtnEl = btns[btns.length - 1];
    if (checkBtnEl) {
      checkBtnEl.classList.add('ntd-act-completed');
      const svgEl = checkBtnEl.querySelector('svg');
      if (svgEl) svgEl.setAttribute('stroke', '#4ade80');
    }
    playSuccessSound && playSuccessSound();
  }

  // Refresh background list
  const ca = document.getElementById('contentArea');
  if (ca) {
    if (typeof renderInternTasks === 'function') renderInternTasks(ca);
  }
}

function ntdOpenNoteSheet(taskId) {
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const heroColor = task.iconColor || task.color || '#e85d26';
  // Build inline note sheet directly in the page (not modal) so keyboard opens immediately
  const existing = document.getElementById('ntdInlineNoteSheet');
  if (existing) { existing.remove(); return; } // toggle off if already open
  const sheet = document.createElement('div');
  sheet.id = 'ntdInlineNoteSheet';
  sheet.className = 'ntd-inline-sheet';
  sheet.innerHTML = `
    <div class="ntd-inline-sheet-hd">
      <span style="font-size:14px;font-weight:700;color:var(--text);">📝 Add Note</span>
      <button class="ntd-inline-sheet-close" onclick="document.getElementById('ntdInlineNoteSheet')?.remove()">✕</button>
    </div>
    <textarea id="ntdInlineNoteTA" class="ntd-inline-sheet-ta" placeholder="Write your note…" rows="4" autofocus></textarea>
    <div style="display:flex;gap:8px;padding:0 0 4px;">
      <button class="btn btn-secondary" style="flex:1;" onclick="document.getElementById('ntdInlineNoteSheet')?.remove()">Cancel</button>
      <button class="btn btn-primary" style="flex:1;background:${heroColor};border-color:${heroColor};" onclick="ntdSaveNote('${taskId}')">Save Note</button>
    </div>
  `;
  // Append inside ntdScrollBody so it scrolls with content and keyboard pushes it up
  const scrollBody = document.getElementById('ntdScrollBody');
  if (scrollBody) {
    scrollBody.appendChild(sheet);
    scrollBody.scrollTop = scrollBody.scrollHeight;
  } else {
    document.getElementById('ntdPage')?.appendChild(sheet);
  }
  // Focus textarea immediately — this opens the keyboard on mobile
  const ta = document.getElementById('ntdInlineNoteTA');
  if (ta) {
    ta.focus();
    // Scroll into view after keyboard opens
    setTimeout(() => ta.scrollIntoView({ behavior: 'smooth', block: 'center' }), 200);
  }
}

async function ntdSaveNote(taskId) {
  const ta = document.getElementById('ntdInlineNoteTA');
  const text = ta?.value.trim();
  if (!text) { showToast('Note cannot be empty', 'error'); return; }
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const user = currentUser;
  const note = {
    id: 'note-' + Date.now(),
    userId: user?.id || 0,
    userName: user?.name || 'Unknown',
    role: currentRole,
    type: 'text',
    content: text,
    timestamp: Date.now()
  };
  if (!task.notes) task.notes = [];
  task.notes.push(note);  // append — allows multiple notes
  markDirty();
  try { await fbPatch('tasks', db.tasks); } catch(e){}
  document.getElementById('ntdInlineNoteSheet')?.remove();
  showToast('Note saved ✓', 'success');
  _ntdRefreshNotes(taskId);
}

function ntdOpenCamera(taskId) {
  // Create a fresh file input each time to avoid stale state on Android WebView
  let fi = document.getElementById('ntdFileInput');
  if (!fi) {
    fi = document.createElement('input');
    fi.type = 'file';
    fi.id = 'ntdFileInput';
    fi.accept = 'image/*';
    fi.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0;';
    document.body.appendChild(fi);
  }
  fi.value = '';  // clear previous selection
  fi.dataset.taskid = taskId;
  fi.onchange = () => ntdHandlePhoto(taskId, fi);
  fi.click();
}

function ntdHandlePhoto(taskId, input) {
  const file = input?.files?.[0]; if (!file) return;
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const user = currentUser;
  const reader = new FileReader();
  reader.onload = async e => {
    const dataUrl = e.target.result;
    const note = {
      id: 'note-' + Date.now(),
      userId: user?.id || 0,
      userName: user?.name || 'Unknown',
      role: currentRole,
      type: 'photo',
      content: dataUrl,
      timestamp: Date.now()
    };
    if (!task.notes) task.notes = [];
    task.notes.push(note);
    markDirty();
    try { await fbPatch('tasks', db.tasks); } catch(e){}
    showToast('Photo added ✓', 'success');
    _ntdRefreshNotes(taskId);
    input.value = '';
  };
  reader.onerror = () => showToast('Failed to read image', 'error');
  reader.readAsDataURL(file);
}

function _ntdRefreshNotes(taskId) {
  const task = db.tasks.find(t => t.id == taskId); if (!task) return;
  const heroColor = (typeof _habitGetIconColor === 'function') ? _habitGetIconColor(task) : (task.iconColor || task.color || '#e85d26');
  const isAdminView = currentRole === 'admin';
  // Fix 7: ALL notes visible to both admin and intern
  const visibleNotes = task.notes || [];
  const section = document.getElementById('ntdNotesSection'); if (!section) return;
  section.dataset.color = heroColor;
  section.innerHTML = _buildNotesTimeline(visibleNotes, heroColor, isAdminView);
}

