// Scans the canvas pixels to find the bounding box of everything that isn't
// blank/white background, so Save can crop tightly around the actual
// drawing rather than inserting the whole (mostly empty) canvas.
function _rteDrawGetContentBounds(canvas) {
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const data = ctx.getImageData(0, 0, W, H).data;
  let minX = W, minY = H, maxX = -1, maxY = -1;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 4;
      const r = data[i], g = data[i+1], b = data[i+2], a = data[i+3];
      const isBlank = a < 10 || (r > 248 && g > 248 && b > 248);
      if (!isBlank) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }
  return maxX < 0 ? null : { minX, minY, maxX, maxY };
}
function rteCloseDraw() {
  const p = document.getElementById('rteDrawPage');
  if (p) p.classList.remove('open');
  setTimeout(() => document.getElementById('rteDrawWrapper')?.remove(), 200);
}

// ── Image action sheet — tap any image inside the note to Resize, Copy,
// Remove, Save, or Zoom it. ──────────────────────────────────────────────
let _rteActiveImg = null;

function _rteImageClickHandler(e) {
  const img = e.target.closest('img');
  const ed = document.getElementById('rteEditable');
  if (!img || !ed || !ed.contains(img)) return;
  e.preventDefault();
  e.stopPropagation();
  rteOpenImageMenu(img);
}

const _RTE_IMGMENU_ICONS = {
  resize: '<svg xmlns="http://www.w3.org/2000/svg" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>',
  copy: '<svg xmlns="http://www.w3.org/2000/svg" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>',
  remove: '<svg xmlns="http://www.w3.org/2000/svg" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>',
  save: '<svg xmlns="http://www.w3.org/2000/svg" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg>',
  zoom: '<svg xmlns="http://www.w3.org/2000/svg" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/><line x1="11" y1="8" x2="11" y2="14"/><line x1="8" y1="11" x2="14" y2="11"/></svg>',
};

function rteOpenImageMenu(img) {
  _rteActiveImg = img;
  // Same fix as the crop screen: blur the note editor so the keyboard
  // (tied to focus, not visual stacking) doesn't stay open behind this
  // menu and cover it.
  document.getElementById('rteEditable')?.blur();
  if (document.activeElement && document.activeElement !== document.body) {
    document.activeElement.blur();
  }
  const rows = [
    ['resize','Resize','rteOpenResizePanel()'],
    ['copy','Copy','rteImageCopy()'],
    ['remove','Remove','rteImageRemove()'],
    ['save','Save','rteImageSave()'],
    ['zoom','Zoom','rteImageZoom()'],
  ];
  const rowsHtml = rows.map(([key,label,action]) =>
    `<button type="button" class="rte-imgmenu-row" onmousedown="event.preventDefault();${action}"><span class="rte-imgmenu-icon">${_RTE_IMGMENU_ICONS[key]}</span><span>${label}</span></button>`
  ).join('');
  const html = `
  <div class="rte-modal-overlay" id="rteImgMenuOverlay" onclick="rteCloseImageMenu();_rteFocusAndRestore()"></div>
  <div class="rte-imgmenu" id="rteImgMenu">
    <div class="rte-imgmenu-title">Image</div>
    ${rowsHtml}
  </div>`;
  const w = document.createElement('div'); w.id = 'rteImgMenuWrapper'; w.innerHTML = html;
  document.body.appendChild(w);
  requestAnimationFrame(() => {
    document.getElementById('rteImgMenuOverlay')?.classList.add('visible');
    document.getElementById('rteImgMenu')?.classList.add('open');
  });
}
function rteCloseImageMenu() {
  const ov = document.getElementById('rteImgMenuOverlay'), m = document.getElementById('rteImgMenu');
  if (ov) ov.classList.remove('visible');
  if (m) m.classList.remove('open');
  setTimeout(() => document.getElementById('rteImgMenuWrapper')?.remove(), 200);
}

function rteImageRemove() {
  if (_rteActiveImg) { _rteActiveImg.remove(); _rteActiveImg = null; }
  rteCloseImageMenu();
  _rteFocusAndRestore();
}
function rteImageSave() {
  const img = _rteActiveImg; rteCloseImageMenu();
  if (!img) { _rteFocusAndRestore(); return; }
  const a = document.createElement('a');
  a.href = img.src;
  a.download = 'image-' + Date.now() + '.png';
  document.body.appendChild(a); a.click(); a.remove();
  showToast('Image saved', 'success');
  _rteFocusAndRestore();
}
async function rteImageCopy() {
  const img = _rteActiveImg; rteCloseImageMenu();
  if (!img) { _rteFocusAndRestore(); return; }
  try {
    const resp = await fetch(img.src);
    const blob = await resp.blob();
    await navigator.clipboard.write([new ClipboardItem({ [blob.type]: blob })]);
    showToast('Image copied', 'success');
  } catch (e) {
    showToast('Copy not supported on this device', 'error');
  }
  _rteFocusAndRestore();
}
function rteImageZoom() {
  const src = _rteActiveImg?.src; rteCloseImageMenu();
  if (!src) { _rteFocusAndRestore(); return; }
  const html = `<div class="rte-zoom-overlay" id="rteZoomOverlay" onclick="rteCloseZoom()"><img src="${src}" class="rte-zoom-img"></div>`;
  const w = document.createElement('div'); w.id = 'rteZoomWrapper'; w.innerHTML = html;
  document.body.appendChild(w);
  requestAnimationFrame(() => document.getElementById('rteZoomOverlay')?.classList.add('visible'));
}
function rteCloseZoom() {
  const ov = document.getElementById('rteZoomOverlay');
  if (ov) ov.classList.remove('visible');
  setTimeout(() => document.getElementById('rteZoomWrapper')?.remove(), 200);
  _rteFocusAndRestore();
}

// ── Resize panel — drag Width/Height sliders to resize the image live ───
function rteOpenResizePanel() {
  rteCloseImageMenu();
  const img = _rteActiveImg; if (!img) return;
  const naturalW = img.naturalWidth || img.width || 300;
  const naturalH = img.naturalHeight || img.height || 300;
  const curW = Math.round(img.width || naturalW);
  const curH = Math.round(img.height || naturalH);
  const maxW = Math.max(naturalW * 2, curW, 700);
  const maxH = Math.max(naturalH * 2, curH, 700);
  window._rteResizeAspect = naturalW / naturalH || 1;
  const html = `
  <div class="rte-modal-overlay" id="rteResizeOverlay" onclick="rteCloseResizePanel()"></div>
  <div class="rte-resize-panel" id="rteResizePanel">
    <div class="rte-resize-title">Resize Image</div>
    <div class="rte-resize-row">
      <div class="rte-resize-row-label">Width <span id="rteResizeWVal">${curW}px</span></div>
      <input type="range" id="rteResizeW" min="20" max="${Math.round(maxW)}" value="${curW}" oninput="rteResizeApply('w')">
    </div>
    <div class="rte-resize-row">
      <div class="rte-resize-row-label">Height <span id="rteResizeHVal">${curH}px</span></div>
      <input type="range" id="rteResizeH" min="20" max="${Math.round(maxH)}" value="${curH}" oninput="rteResizeApply('h')">
    </div>
    <label class="rte-resize-lock"><input type="checkbox" id="rteResizeLock" checked> Lock aspect ratio</label>
    <button class="btn btn-primary btn-full" onmousedown="event.preventDefault();rteCloseResizePanel()">Done</button>
  </div>`;
  const w = document.createElement('div'); w.id = 'rteResizeWrapper'; w.innerHTML = html;
  document.body.appendChild(w);
  requestAnimationFrame(() => {
    document.getElementById('rteResizeOverlay')?.classList.add('visible');
    document.getElementById('rteResizePanel')?.classList.add('open');
  });
}
function rteResizeApply(source) {
  const img = _rteActiveImg; if (!img) return;
  const wSlider = document.getElementById('rteResizeW'), hSlider = document.getElementById('rteResizeH');
  const lock = document.getElementById('rteResizeLock')?.checked;
  let w = parseInt(wSlider.value, 10), h = parseInt(hSlider.value, 10);
  const aspect = window._rteResizeAspect || 1;
  if (lock) {
    if (source === 'w') { h = Math.round(w / aspect); hSlider.value = h; }
    else { w = Math.round(h * aspect); wSlider.value = w; }
  }
  document.getElementById('rteResizeWVal').textContent = w + 'px';
  document.getElementById('rteResizeHVal').textContent = h + 'px';
  img.style.width = w + 'px';
  img.style.height = h + 'px';
  img.setAttribute('width', w);
  img.setAttribute('height', h);
}
function rteCloseResizePanel() {
  const ov = document.getElementById('rteResizeOverlay'), p = document.getElementById('rteResizePanel');
  if (ov) ov.classList.remove('visible');
  if (p) p.classList.remove('open');
  setTimeout(() => document.getElementById('rteResizeWrapper')?.remove(), 200);
  _rteFocusAndRestore();
}

// ══════════════════════════════════════════════════════════════════════
// Crop Image screen — shown whenever a picture is added to the description
// editor. Lets the person crop to a fixed aspect ratio (or Original),
// rotate, and scale the image before it's inserted into the note.
// ══════════════════════════════════════════════════════════════════════
const _RTE_CROP_ICONS = {
  close: '<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>',
  check: '<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>',
  crop: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2v14a2 2 0 0 0 2 2h14"/><path d="M18 22V8a2 2 0 0 0-2-2H2"/></svg>',
  rotate: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>',
  scale: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3H5a2 2 0 0 0-2 2v3"/><path d="M21 8V5a2 2 0 0 0-2-2h-3"/><path d="M3 16v3a2 2 0 0 0 2 2h3"/><path d="M16 21h3a2 2 0 0 0 2-2v-3"/></svg>',
  reset: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>',
  snap90: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>',
};

let _rteCropState = null; // pan/rotate/scale/ratio state for the crop screen

function rteOpenCropPage(srcDataUrl) {
  // The note editor (#rteEditable) is a contenteditable that may still hold
  // focus from just before "Add picture" was tapped. Since it sits hidden
  // behind this full-screen crop page, the on-screen keyboard stays tied to
  // it and can resurface on the next tap unless we explicitly blur it here.
  document.getElementById('rteEditable')?.blur();
  if (document.activeElement && document.activeElement !== document.body) {
    document.activeElement.blur();
  }
  const html = `
  <div class="rte-crop-page" id="rteCropPage">
    <div class="rte-crop-header">
      <button class="rte-crop-icon-btn" onclick="rteCropCancel()">${_RTE_CROP_ICONS.close}</button>
      <span class="rte-crop-title">Crop Image</span>
      <button class="rte-crop-icon-btn rte-crop-confirm" onclick="rteCropConfirm()">${_RTE_CROP_ICONS.check}</button>
    </div>
    <div class="rte-crop-viewport" id="rteCropViewport">
      <img id="rteCropImg" src="${srcDataUrl}" draggable="false">
      <div class="rte-crop-frame" id="rteCropFrame">
        <div class="rte-crop-handle rte-crop-handle-tl" data-corner="tl"></div>
        <div class="rte-crop-handle rte-crop-handle-tr" data-corner="tr"></div>
        <div class="rte-crop-handle rte-crop-handle-bl" data-corner="bl"></div>
        <div class="rte-crop-handle rte-crop-handle-br" data-corner="br"></div>
      </div>
    </div>
    <div class="rte-crop-controls">
      <div class="rte-crop-ratio-row" id="rteCropRatioRow">
        <button class="rte-crop-ratio-btn sel" data-ratio="original" onmousedown="event.preventDefault();rteCropSetRatio('original')">Original</button>
        <button class="rte-crop-ratio-btn" data-ratio="1:1" onmousedown="event.preventDefault();rteCropSetRatio('1:1')">Square</button>
        <button class="rte-crop-ratio-btn" data-ratio="3:2" onmousedown="event.preventDefault();rteCropSetRatio('3:2')">3x2</button>
        <button class="rte-crop-ratio-btn" data-ratio="4:3" onmousedown="event.preventDefault();rteCropSetRatio('4:3')">4x3</button>
        <button class="rte-crop-ratio-btn" data-ratio="16:9" onmousedown="event.preventDefault();rteCropSetRatio('16:9')">16x9</button>
      </div>
      <div class="rte-crop-rotate-row" id="rteCropRotateRow" style="display:none;">
        <button class="rte-crop-round-btn" onmousedown="event.preventDefault();rteCropResetRotate()" title="Reset">${_RTE_CROP_ICONS.reset}</button>
        <div class="rte-crop-rotate-wrap">
          <div class="rte-crop-rotate-val" id="rteCropRotateVal">0.0°</div>
          <input type="range" id="rteCropRotateSlider" min="-45" max="45" value="0" step="0.5" oninput="rteCropRotateChange(this.value)">
        </div>
        <button class="rte-crop-round-btn" onmousedown="event.preventDefault();rteCropSnap90()" title="Rotate 90°">${_RTE_CROP_ICONS.snap90}<span class="rte-crop-90-badge">90°</span></button>
      </div>
      <div class="rte-crop-scale-row" id="rteCropScaleRow" style="display:none;">
        <div class="rte-crop-scale-val" id="rteCropScaleVal">100%</div>
        <input type="range" id="rteCropScaleSlider" min="50" max="250" value="100" oninput="rteCropScaleChange(this.value)">
      </div>
    </div>
    <div class="rte-crop-tabs">
      <button class="rte-crop-tab sel" data-tab="crop" onclick="rteCropSwitchTab('crop')">${_RTE_CROP_ICONS.crop}<span>Crop</span></button>
      <button class="rte-crop-tab" data-tab="rotate" onclick="rteCropSwitchTab('rotate')">${_RTE_CROP_ICONS.rotate}<span>Rotate</span></button>
      <button class="rte-crop-tab" data-tab="scale" onclick="rteCropSwitchTab('scale')">${_RTE_CROP_ICONS.scale}<span>Scale</span></button>
    </div>
  </div>`;
  const w = document.createElement('div'); w.id = 'rteCropWrapper'; w.innerHTML = html;
  document.body.appendChild(w);
  requestAnimationFrame(() => {
    document.getElementById('rteCropPage')?.classList.add('open');
    _rteCropInit(srcDataUrl);
  });
}

function _rteCropInit(srcDataUrl) {
  const img = document.getElementById('rteCropImg');
  const viewport = document.getElementById('rteCropViewport');
  if (!img || !viewport) return;
  const setup = () => {
    const vw = viewport.clientWidth, vh = viewport.clientHeight;
    const natW = img.naturalWidth || 1, natH = img.naturalHeight || 1;
    const baseScale = Math.min(vw / natW, vh / natH) * 0.92;
    _rteCropState = {
      natW, natH, baseScale, vw, vh,
      pan: { x: 0, y: 0 }, rotateFine: 0, rotateSnap: 0, scale: 1,
      ratio: 'original', frameLeft: 0, frameTop: 0, frameW: vw, frameH: vh,
    };
    img.style.width = (natW * baseScale) + 'px';
    img.style.height = (natH * baseScale) + 'px';
    img.style.marginLeft = (-(natW * baseScale) / 2) + 'px';
    img.style.marginTop = (-(natH * baseScale) / 2) + 'px';
    _rteCropApplyTransform();
    rteCropSetRatio('original');
    _rteCropWireDrag();
    _rteCropWireHandles();
  };
  if (img.complete && img.naturalWidth) setup();
  else img.onload = setup;
}

function _rteCropApplyTransform() {
  const s = _rteCropState, img = document.getElementById('rteCropImg');
  if (!s || !img) return;
  const angle = s.rotateSnap + s.rotateFine;
  img.style.transform = `translate(${s.pan.x}px, ${s.pan.y}px) rotate(${angle}deg) scale(${s.scale})`;
}
function _rteCropApplyFrame() {
  const s = _rteCropState, frame = document.getElementById('rteCropFrame');
  if (!s || !frame) return;
  frame.style.left = s.frameLeft + 'px';
  frame.style.top = s.frameTop + 'px';
  frame.style.width = s.frameW + 'px';
  frame.style.height = s.frameH + 'px';
}

function rteCropSetRatio(ratio) {
  const s = _rteCropState; if (!s) return;
  s.ratio = ratio;
  document.querySelectorAll('.rte-crop-ratio-btn').forEach(b => b.classList.toggle('sel', b.dataset.ratio === ratio));
  let ar;
  if (ratio === 'original') ar = s.natW / s.natH;
  else if (ratio === '1:1') ar = 1;
  else if (ratio === '3:2') ar = 3 / 2;
  else if (ratio === '4:3') ar = 4 / 3;
  else ar = 16 / 9;
  const maxW = s.vw * 0.86, maxH = s.vh * 0.86;
  let w = maxW, h = w / ar;
  if (h > maxH) { h = maxH; w = h * ar; }
  s.frameW = w; s.frameH = h;
  s.frameLeft = (s.vw - w) / 2;
  s.frameTop = (s.vh - h) / 2;
  _rteCropApplyFrame();
}

// Dragging anywhere inside the frame (but not on a corner handle) pans the
// image behind it — lets you choose *which part* of the photo sits inside
// the crop.
function _rteCropWireDrag() {
  const vp = document.getElementById('rteCropViewport'); if (!vp) return;
  let dragging = false, startX = 0, startY = 0, startPan = { x: 0, y: 0 };
  const pos = e => { const t = e.touches ? e.touches[0] : e; return { x: t.clientX, y: t.clientY }; };
  const start = e => { dragging = true; const p = pos(e); startX = p.x; startY = p.y; startPan = { ..._rteCropState.pan }; };
  const move = e => {
    if (!dragging || !_rteCropState) return; e.preventDefault();
    const p = pos(e);
    _rteCropState.pan.x = startPan.x + (p.x - startX);
    _rteCropState.pan.y = startPan.y + (p.y - startY);
    _rteCropApplyTransform();
  };
  const end = () => { dragging = false; };
  vp.addEventListener('mousedown', start);
  window.addEventListener('mousemove', move);
  window.addEventListener('mouseup', end);
  vp.addEventListener('touchstart', start, { passive: false });
  vp.addEventListener('touchmove', move, { passive: false });
  vp.addEventListener('touchend', end);
}

// Dragging a corner handle freely resizes the crop frame itself (the part
// that was missing — previously only fixed aspect-ratio presets were
// available). Grabbing any corner switches the ratio row to "Custom" since
// the frame is no longer locked to a preset shape.
function _rteCropWireHandles() {
  const frame = document.getElementById('rteCropFrame'); if (!frame) return;
  const viewport = document.getElementById('rteCropViewport'); if (!viewport) return;
  const MIN = 44;
  frame.querySelectorAll('.rte-crop-handle').forEach(handle => {
    const corner = handle.dataset.corner;
    let dragging = false;
    const pos = e => {
      const r = viewport.getBoundingClientRect();
      const t = e.touches ? e.touches[0] : e;
      return { x: t.clientX - r.left, y: t.clientY - r.top };
    };
    const start = e => { e.preventDefault(); e.stopPropagation(); dragging = true; };
    const move = e => {
      if (!dragging || !_rteCropState) return;
      e.preventDefault(); e.stopPropagation();
      const s = _rteCropState;
      const p = pos(e);
      const px = Math.max(0, Math.min(s.vw, p.x));
      const py = Math.max(0, Math.min(s.vh, p.y));
      let left = s.frameLeft, top = s.frameTop, w = s.frameW, h = s.frameH;
      const right = left + w, bottom = top + h;
      if (corner === 'tl') {
        left = Math.min(px, right - MIN); top = Math.min(py, bottom - MIN);
        w = right - left; h = bottom - top;
      } else if (corner === 'tr') {
        const newRight = Math.max(px, left + MIN); top = Math.min(py, bottom - MIN);
        w = newRight - left; h = bottom - top;
      } else if (corner === 'bl') {
        left = Math.min(px, right - MIN); const newBottom = Math.max(py, top + MIN);
        w = right - left; h = newBottom - top;
      } else {
        const newRight = Math.max(px, left + MIN); const newBottom = Math.max(py, top + MIN);
        w = newRight - left; h = newBottom - top;
      }
      s.frameLeft = left; s.frameTop = top; s.frameW = w; s.frameH = h;
      if (s.ratio !== 'custom') {
        s.ratio = 'custom';
        document.querySelectorAll('.rte-crop-ratio-btn').forEach(b => b.classList.remove('sel'));
      }
      _rteCropApplyFrame();
    };
    const end = () => { dragging = false; };
    handle.addEventListener('mousedown', start);
    window.addEventListener('mousemove', move);
    window.addEventListener('mouseup', end);
    handle.addEventListener('touchstart', start, { passive: false });
    handle.addEventListener('touchmove', move, { passive: false });
    handle.addEventListener('touchend', end);
  });
}

function rteCropSwitchTab(tab) {
  document.querySelectorAll('.rte-crop-tab').forEach(b => b.classList.toggle('sel', b.dataset.tab === tab));
  document.getElementById('rteCropRatioRow').style.display = tab === 'crop' ? 'flex' : 'none';
  document.getElementById('rteCropRotateRow').style.display = tab === 'rotate' ? 'flex' : 'none';
  document.getElementById('rteCropScaleRow').style.display = tab === 'scale' ? 'flex' : 'none';
}
function rteCropRotateChange(v) {
  const s = _rteCropState; if (!s) return;
  s.rotateFine = parseFloat(v);
  document.getElementById('rteCropRotateVal').textContent = (s.rotateSnap + s.rotateFine).toFixed(1) + '°';
  _rteCropApplyTransform();
}
function rteCropSnap90() {
  const s = _rteCropState; if (!s) return;
  s.rotateSnap = (s.rotateSnap + 90) % 360;
  document.getElementById('rteCropRotateVal').textContent = (s.rotateSnap + s.rotateFine).toFixed(1) + '°';
  _rteCropApplyTransform();
}
function rteCropResetRotate() {
  const s = _rteCropState; if (!s) return;
  s.rotateFine = 0; s.rotateSnap = 0;
  const slider = document.getElementById('rteCropRotateSlider'); if (slider) slider.value = 0;
  document.getElementById('rteCropRotateVal').textContent = '0.0°';
  _rteCropApplyTransform();
}
function rteCropScaleChange(v) {
  const s = _rteCropState; if (!s) return;
  s.scale = parseFloat(v) / 100;
  document.getElementById('rteCropScaleVal').textContent = Math.round(v) + '%';
  _rteCropApplyTransform();
}

function rteCropConfirm() {
  const s = _rteCropState;
  const img = document.getElementById('rteCropImg');
  if (!s || !img) { rteCropCancel(); return; }
  const frameW = Math.max(1, s.frameW), frameH = Math.max(1, s.frameH);
  // The on-screen frame is only a few hundred CSS pixels, but the source
  // photo can be several thousand pixels wide — rendering the output canvas
  // at frameW×frameH (as before) silently threw away almost all of that
  // resolution. `totalScale` is how many CSS px the crop UI currently shows
  // per one natural source pixel, so 1/totalScale scales the frame size back
  // up to the *actual* native-resolution pixel count the crop is capturing.
  const totalScale = s.baseScale * s.scale;
  let k = 1 / totalScale;
  let outW = frameW * k, outH = frameH * k;
  // Cap the output so an extreme zoom-out doesn't produce an unreasonably
  // huge canvas/data URL — this only kicks in well above typical photo
  // resolutions, so normal crops still keep their full native sharpness.
  const MAX_DIM = 2200;
  const capScale = Math.min(1, MAX_DIM / Math.max(outW, outH));
  outW = Math.round(outW * capScale); outH = Math.round(outH * capScale);
  k *= capScale;

  const canvas = document.createElement('canvas');
  canvas.width = outW; canvas.height = outH;
  const ctx = canvas.getContext('2d');
  // The image is centered in the viewport (plus pan); the frame can now sit
  // anywhere in the viewport (plus be freely resized), so the offset between
  // the two has to be computed explicitly rather than assumed to be zero.
  const offsetX = ((s.vw / 2 + s.pan.x) - s.frameLeft) * k;
  const offsetY = ((s.vh / 2 + s.pan.y) - s.frameTop) * k;
  ctx.translate(offsetX, offsetY);
  ctx.rotate((s.rotateSnap + s.rotateFine) * Math.PI / 180);
  ctx.scale(totalScale * k, totalScale * k);
  ctx.drawImage(img, -s.natW / 2, -s.natH / 2, s.natW, s.natH);
  const dataUrl = canvas.toDataURL('image/png');
  rteCropCancel();
  _rteInsertImageAtCaret(dataUrl);
}
function rteCropCancel() {
  const p = document.getElementById('rteCropPage');
  if (p) p.classList.remove('open');
  setTimeout(() => document.getElementById('rteCropWrapper')?.remove(), 220);
  _rteCropState = null;
  _rteFocusAndRestore();
}

function _ctDateChange(input) {
  const lbl=document.getElementById('ctDueDateLabel'); if(!lbl) return;
  if(input.value) { const d=new Date(input.value+'T00:00:00'); lbl.textContent=d.toLocaleDateString('en-US',{day:'numeric',month:'short',year:'numeric'}); lbl.style.color='var(--accent)'; }
  else { lbl.textContent='Not set'; lbl.style.color='var(--text2)'; }
}

function _ctUpdateCategoryBadge(cat) {
  _ctCategory=cat;
  const badge=document.getElementById('ctCatBadge'); if(!badge) return;
  const catL=cat.toLowerCase();
  const color=catL==='office'?'#3b82f6':catL==='academic'?'#059669':'var(--accent)';
  const bg=catL==='office'?'rgba(59,130,246,.13)':catL==='academic'?'rgba(5,150,105,.13)':'rgba(232,93,38,.13)';
  badge.textContent=cat; badge.style.color=color; badge.style.background=bg; badge.style.borderColor=color;
  // Update icon/colour defaults when category changes
  const defs=_ctDefaultsForCat(cat);
  if(!_ctIconColor) { ctPickColor(defs.color); }
  if(!_ctIconSvg && typeof HABIT_ICONS!=='undefined' && HABIT_ICONS[defs.iconKey]) { ctPickIcon(defs.iconKey); }
}

function openCtCategoryPicker() {
  _openCtMiniSheet('Select Category', [
    {label:'🏢  Office',   action:()=>_ctUpdateCategoryBadge('Office')},
    {label:'📚  Academic', action:()=>_ctUpdateCategoryBadge('Academic')},
    {label:'⭐  Personal', action:()=>_ctUpdateCategoryBadge('Personal')},
  ]);
}

function openCtPriorityPicker() {
  _openCtMiniSheet('Priority', [
    {label:'⬜  None',   action:()=>_ctSetPriority('None')},
    {label:'🟢  Low',    action:()=>_ctSetPriority('Low')},
    {label:'🟡  Medium', action:()=>_ctSetPriority('Medium')},
    {label:'🔴  High',   action:()=>_ctSetPriority('High')},
  ]);
}

function _ctSetPriority(p) {
  _ctPriority=p;
  const badge=document.getElementById('ctPriorityBadge'); if(!badge) return;
  const m={None:['#888','rgba(136,136,136,.1)'],Low:['#059669','rgba(5,150,105,.12)'],Medium:['#d97706','rgba(217,119,6,.12)'],High:['#dc2626','rgba(220,38,38,.12)']};
  const [color,bg]=m[p]||m['None'];
  badge.textContent=p; badge.style.color=color; badge.style.background=bg; badge.style.borderColor=color;
}

function _openCtMiniSheet(title, items) {
  document.getElementById('ctMiniSheet')?.remove();
  const el = document.createElement('div'); el.id = 'ctMiniSheet';
  el.innerHTML = `
    <div class="ctms-overlay" onclick="document.getElementById('ctMiniSheet')?.remove()"></div>
    <div class="ctms-panel" id="ctmsPanel">
      <div class="ctms-handle"></div>
      <div class="ctms-title">${title}</div>
      ${items.map((it,idx) => `<div class="ctms-item" onclick="_ctmsAct(${idx})">${it.label}</div>`).join('')}
      <div class="ctms-cancel" onclick="document.getElementById('ctMiniSheet')?.remove()">Cancel</div>
    </div>`;
  // Store actions on element
  el._actions = items.map(it => it.action);
  document.body.appendChild(el);
  requestAnimationFrame(() => document.getElementById('ctmsPanel')?.classList.add('open'));
}

function _ctmsAct(idx) {
  const el = document.getElementById('ctMiniSheet'); if (!el) return;
  if (el._actions && el._actions[idx]) el._actions[idx]();
  el.remove();
}

async function saveCustomTask() {
  const title = document.getElementById('ptTitle')?.value.trim();
  if (!title) { showToast('Title required', 'error'); return; }
  const pts = parseInt(document.getElementById('ptPoints')?.value) || 0;
  db.tasks.unshift({
    id:'pt-'+Date.now(), title,
    description: document.getElementById('ptDesc')?.value || '',
    dueDate: document.getElementById('ptDue')?.value || '',
    repeat: null,
    category: _ctCategory || 'Personal',
    priority: _ctPriority || 'None',
    isPersonal: true,
    createdBy: currentUser.id, assignedTo: currentUser.id,
    createdDate: today(), createdAt: Date.now(),
    points: Math.max(0, Math.min(pts, 9999)), approvalRequired: false,
    isTemplate: false
  });
  closeCt(); _repeatConfig = null;
  await saveAndRefresh('Task created!', 'internTasks');
}


