function renderInternComplaints(ca) {
  const mine = (db.complaints || []).filter(c => c.from === currentUser.id);
  const filterStatus = window.internComplaintFilter || 'All';

  // Add fixed sidebar toggle button
  let sidebarBtn = document.getElementById('fixed-sidebar-toggle');
  if (!sidebarBtn) {
    sidebarBtn = document.createElement('button');
    sidebarBtn.id = 'fixed-sidebar-toggle';
    sidebarBtn.className = 'sidebar-toggle-btn';
    sidebarBtn.setAttribute('aria-label', 'Open Menu');
    sidebarBtn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <polyline points="9 6 15 12 9 18"/>
      <polyline points="15 6 21 12 15 18"/>
    </svg>`;
    sidebarBtn.onclick = toggleMobileSidebar;
    document.body.appendChild(sidebarBtn);
  }
  sidebarBtn.style.display = 'flex';

  const filtered = mine.filter(c => {
    if (filterStatus === 'Resolved')   return c.done;
    if (filterStatus === 'Unresolved') return !c.done;
    return true; // All
  });

  const buildCard = c => {
    const against = INTERNS.find(i => i.id === c.against);
    return `<div class="complaint-card" style="${c.done?'opacity:.6;':''}">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px;">
        <div style="font-weight:700;font-size:13px;">${sanitize(c.subject)}</div>
        ${c.done ? '<span class="badge badge-green">✓ Resolved</span>' : '<span class="badge badge-orange">Open</span>'}
      </div>
      <div style="font-size:11px;color:var(--text2);">Against: ${sanitize(against?.name||'?')} · ${sanitize(c.date||'')}</div>
      ${c.desc ? `<div style="font-size:12px;color:var(--text2);margin-top:4px;">${sanitize(c.desc)}</div>` : ''}
    </div>`;
  };

  const listHtml = filtered.length
    ? filtered.map(buildCard).join('')
    : `<div class="txp-empty">No complaints found.</div>`;

  ca.innerHTML = `
    <!-- Custom Header - Title Only -->
    <div class="leaderboard-custom-header">
      <h1 class="lb-header-title">Complaints</h1>
    </div>
    
    <div class="it-page">
      
      <div class="it-search-bar" id="icSearchBar" style="display:none;"></div>
      <div class="txp-list" style="padding:12px 4px 0;">${listHtml}</div>
    </div>`;

  // Populate complaint filter dropdown
  _populateComplaintFilterDropdown();
  if (window.lucide) lucide.createIcons(); initCarousels();
}
function openComplaintModal() {
  // BUG-28 FIX: character limits on subject (200) and description (1000) with live counters
  const interns = INTERNS.filter(i => i.id !== 99 && i.id !== currentUser.id);
  openModal(`<div class="modal-title">Submit Complaint</div>
    <div class="form-group">
      <label>Against *</label>
      <select id="cAgainst"><option value="">Select intern...</option>${interns.map(i => `<option value="${i.id}">${sanitize(i.name)}</option>`).join('')}</select>
    </div>
    <div class="form-group">
      <label>Subject * <span id="subjectCount" style="font-size:10px;color:var(--text3);font-weight:400;">0/200</span></label>
      <input type="text" id="cSubject" placeholder="Brief subject line" maxlength="200" oninput="document.getElementById('subjectCount').textContent=this.value.length+'/200'">
    </div>
    <div class="form-group">
      <label>Description <span id="descCount" style="font-size:10px;color:var(--text3);font-weight:400;">0/1000</span></label>
      <textarea id="cDesc" placeholder="Describe the issue in detail..." maxlength="1000" oninput="document.getElementById('descCount').textContent=this.value.length+'/1000'"></textarea>
    </div>
    <div class="modal-actions">
      <button class="btn btn-secondary" onclick="closeModal()">Cancel</button>
      <button class="btn btn-primary" onclick="submitComplaint()">Submit</button>
    </div>`);
}

async function submitComplaint() {
  const against = document.getElementById('cAgainst').value;
  const subject = document.getElementById('cSubject').value.trim();
  const desc    = document.getElementById('cDesc').value.trim();
  if (!against) { showToast('Please select an intern to file against', 'error'); return; }
  if (!subject) { showToast('Subject is required', 'error'); return; }
  db.complaints.push({id:'c-'+Date.now(), from:currentUser.id, against:parseInt(against), subject, desc, date:today(), read:false});
  closeModal();
  await saveAndRefresh('Complaint submitted', 'internComplaints');
}

