function _hFilterInterns() {
  const q=(document.getElementById('hInternSearch')?.value||'').toLowerCase();
  document.querySelectorAll('#hAssignList label[data-name]').forEach(lbl=>{
    lbl.style.display=lbl.dataset.name.includes(q)?'':'none';
  });
}
function _hDateLbl(input, lblId, emptyText='') {
  const lbl=document.getElementById(lblId); if(!lbl) return;
  if(input.value) { const d=new Date(input.value+'T00:00:00'); lbl.textContent=d.toLocaleDateString('en-US',{day:'numeric',month:'short',year:'numeric'}); lbl.style.color='var(--accent)'; }
  else { lbl.textContent=emptyText||'Not set'; lbl.style.color='var(--text2)'; }
}

async function saveHabit() {
  const name = document.getElementById('hName')?.value.trim();
  if (!name) { showToast('Habit name required', 'error'); return; }
  const selectedIds = [...document.querySelectorAll('.hInternCb:checked')].map(cb=>parseInt(cb.value));
  if (!selectedIds.length) { showToast('Assign to at least one intern', 'error'); return; }
  const xpRaw = parseInt(document.getElementById('hXP')?.value);
  const xp = (isFinite(xpRaw) && xpRaw > 0) ? xpRaw : 5;
  const st = _habitCreateState;

  // Build frequency config
  let frequency = { type: 'everyday', config: {} };
  if (st.freqMode === 'SpecificDaysOfWeek') frequency = { type: 'daysOfWeek', config: { days: [...st.dowSel] } };
  else if (st.freqMode === 'SpecificDaysOfMonth') frequency = { type: 'daysOfMonth', config: { dates: [...st.domSel] } };
  else if (st.freqMode === 'SomeDaysPerPeriod') frequency = { type: 'perPeriod', config: { count: st.periodN, unit: st.periodUnit } };

  const startDate = document.getElementById('hStartDate')?.value || _hToday();
  const endDate = document.getElementById('hEndDate')?.value || null;
  if (endDate && endDate < startDate) { showToast('End date must be after start date', 'error'); return; }

  const habit = {
    id: 'h-' + Date.now(),
    name,
    description: document.getElementById('hDesc')?.value.trim() || '',
    iconSvg: st.iconSvg || null,
    color: st.color || '#F59E0B',
    assignedTo: selectedIds,
    frequency,
    startDate,
    endDate,
    xpPerCompletion: xp,
    createdAt: Date.now(),
    createdBy: 'admin'
  };

  // Duplicate check
  const dupIntern = selectedIds.find(iid => (db.habits||[]).some(h=>h.name===name && h.assignedTo && h.assignedTo.includes(iid)));
  if (dupIntern) {
    const iname = INTERNS.find(i=>i.id===dupIntern)?.name || '';
    showToast(`${iname} already has this habit`, 'error'); return;
  }

  if (!db.habits) db.habits = [];
  db.habits.unshift(habit);
  // Notify interns
  selectedIds.forEach(iid => {
    if (!db.notifications[iid]) db.notifications[iid] = [];
    db.notifications[iid].unshift({ id:'n-'+Date.now()+'-'+iid, msg:`New habit assigned: "${name}"`, type:'habit', read:false, date:_hToday() });
  });
  closeCreateHabit();
  // BUG FIX: Use targeted fbPatch instead of full fbWrite (saveDB) to avoid
  // overwriting habitCompletions that were written with fbPatch independently.
  try {
    showLoading('Saving...');
    // Patch only the habits array and notifications — never overwrite completions
    await fbPatch('habits', db.habits.reduce((acc, h, i) => { acc[i] = h; return acc; }, {}));
    selectedIds.forEach(async iid => {
      if (db.notifications[iid]) {
        try { await fbPatch(`notifications/${iid}`, db.notifications[iid].reduce((acc, n, i) => { acc[i] = n; return acc; }, {})); } catch(e){}
      }
    });
    // Also do full save to keep habits array in sync (habits array is index-based)
    await fbPatch('habits', db.habits);
    hideLoading();
    showToast(`Habit created for ${selectedIds.length} intern(s)!`, 'success');
    if (currentPage) await navigateTo(currentPage);
  } catch(e) {
    hideLoading();
    showToast('Save failed. Check your internet.', 'error');
  }
}

// ── Admin Habit Management (Admin Dashboard card) ─────────────
function openAdminHabits() {
  const habits = db.habits || [];
  const td = _hToday();
  if (!habits.length) {
    openModal(`
      <div class="modal-title">🔥 Habits</div>
      <div class="txp-empty" style="margin:20px 0;">No habits created yet.</div>
      <button class="btn btn-primary btn-full" onclick="closeModal();openCreateHabit()">+ Create First Habit</button>
    `);
    if (window.lucide) lucide.createIcons();
    return;
  }

  const rows = habits.map(h => {
    const assignedNames = (h.assignedTo||[]).map(iid=>INTERNS.find(i=>i.id===iid)?.name?.split(' ')[0]||'?').join(', ');
    const totalAssigned = (h.assignedTo||[]).length;
    const doneToday = (h.assignedTo||[]).filter(iid=>_habitCompleted(h.id,iid,td)).length;
    const color = h.color||'#F59E0B';
    const iconSvg=(h.iconSvg||'').replace(/width="[^"]*"/,'').replace(/height="[^"]*"/,'').replace('<svg','<svg width="20" height="20"');
    return `<div class="admin-habit-row" onclick="openAdminHabitDetail('${h.id}')">
      <div class="admin-habit-icon" style="background:${color}22;color:${color};">${iconSvg}</div>
      <div class="admin-habit-info">
        <div class="admin-habit-name">${sanitize(h.name)}</div>
        <div class="admin-habit-meta">${sanitize(assignedNames.length>30?assignedNames.slice(0,28)+'…':assignedNames)}</div>
      </div>
      <div class="admin-habit-stat" style="color:${color};">${doneToday}/${totalAssigned}</div>
      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="var(--text3)" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg>
    </div>`;
  }).join('');

  openModal(`
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">
      <div class="modal-title" style="margin:0;">🔥 Habits</div>
      <button class="btn btn-primary btn-sm" onclick="closeModal();openCreateHabit()">+ New</button>
    </div>
    <div class="admin-habit-list">${rows}</div>
  `);
  if (window.lucide) lucide.createIcons();
}

function openAdminHabitDetail(habitId) {
  const habit = (db.habits||[]).find(h=>h.id===habitId);
  if (!habit) return;
  const color = habit.color||'#F59E0B';
  const td = _hToday();
  const internRows = (habit.assignedTo||[]).map(iid => {
    const intern = INTERNS.find(i=>i.id===iid); if(!intern) return '';
    const { current: streak } = _habitCalcStreak(habitId, iid);
    const score = _habitCalcScore(habitId, iid);
    const done = _habitCompleted(habitId, iid, td);
    return `<div class="admin-hi-row" onclick="openHabitDetail('${habitId}','${iid}')">
      <div class="admin-hi-avatar" style="background:${color}22;color:${color};">${intern.name.charAt(0)}</div>
      <div class="admin-hi-info">
        <div class="admin-hi-name">${sanitize(intern.name)}</div>
        <div class="admin-hi-meta">Streak: ${streak}d · Score: ${score}%</div>
      </div>
      <div class="admin-hi-status" style="color:${done?'#22c55e':'var(--text3)'};">${done?'✓ Done':'Pending'}</div>
    </div>`;
  }).join('');

  closeModal();
  openModal(`
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px;">
      <div style="width:40px;height:40px;border-radius:10px;background:${color}22;color:${color};display:flex;align-items:center;justify-content:center;flex-shrink:0;">
        ${(habit.iconSvg||'').replace(/width="[^"]*"/,'').replace(/height="[^"]*"/,'').replace('<svg','<svg width="22" height="22"')}
      </div>
      <div>
        <div style="font-size:16px;font-weight:700;">${sanitize(habit.name)}</div>
        <div style="font-size:11px;color:var(--text2);">${_habitFreqLabel(habit.frequency)}</div>
      </div>
    </div>
    ${habit.description?`<div style="font-size:13px;color:var(--text2);margin-bottom:16px;padding:10px;background:var(--surface2);border-radius:8px;" class="rich-desc">${sanitizeRichHtml(habit.description)}</div>`:''}
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--text3);margin-bottom:8px;">Assigned Interns</div>
    <div class="admin-habit-interns">${internRows}</div>
    <div style="margin-top:16px;">
      <button class="btn btn-danger btn-full" onclick="confirmDeleteHabit('${habitId}')">Delete Habit</button>
    </div>
  `);
  if (window.lucide) lucide.createIcons();
}

function confirmDeleteHabit(habitId) {
  const habit = (db.habits||[]).find(h=>h.id===habitId); if(!habit) return;
  closeModal();
  openModal(`
    <div class="modal-title">Delete Habit?</div>
    <div style="font-size:13px;color:var(--text2);margin:12px 0;">Delete "<strong>${sanitize(habit.name)}</strong>"? XP already awarded will be kept. This cannot be undone.</div>
    <div style="display:flex;gap:8px;">
      <button class="btn btn-secondary" style="flex:1;" onclick="closeModal()">Cancel</button>
      <button class="btn btn-danger" style="flex:1;" onclick="doDeleteHabit('${habitId}')">Delete</button>
    </div>
  `);
}

async function doDeleteHabit(habitId) {
  db.habits = (db.habits||[]).filter(h=>h.id!==habitId);
  closeModal();
  await saveAndRefresh('Habit deleted.', 'adminDashboard');
}

function setATF(f) { window.adminTaskFilter = f; }


