async function updateTaskStatusKanban(taskId, newStatus) {
  const task = db.tasks.find(t => t.id == taskId);
  if (!task) return;
  const internId = task.assignedTo;
  if (newStatus === 'completed') {
    if (!task.completions) task.completions = [];
    if (!task.completions.find(c => c.userId == internId)) {
      task.completions.push({ userId: internId, timestamp: Date.now(), completedAt: new Date().toISOString().split('T')[0] });
    }
    if (task.inProgress) task.inProgress = task.inProgress.filter(id => id !== internId);
  } else if (newStatus === 'progress') {
    if (!task.inProgress) task.inProgress = [];
    if (!task.inProgress.includes(internId)) task.inProgress.push(internId);
    task.completions = (task.completions || []).filter(c => c.userId != internId);
  } else if (newStatus === 'pending') {
    task.completions = (task.completions || []).filter(c => c.userId != internId);
    if (task.inProgress) task.inProgress = task.inProgress.filter(id => id !== internId);
  }
  await saveDB();
  showToast('✓ Task updated');
  navigateTo('adminTasks');
}

function renderKanbanCard(task) {
  if (!task) return '';
  const cat = (task.category || 'Office').toLowerCase();
  const isDone = isTaskDone(task.id, task.assignedTo);
  const inProgress = isTaskInProgress(task.id, task.assignedTo);
  let checkboxColor = '#3b82f6';
  if (cat === 'academic') checkboxColor = '#059669';
  else if (cat === 'personal') checkboxColor = '#f97316';
  const sharedWith = task.sharedWith && task.sharedWith.length > 1 ? task.sharedWith : [];
  let avatarsHtml = '';
  if (sharedWith.length > 0) {
    avatarsHtml = sharedWith.slice(0, 2).map(id => {
      const intern = INTERNS.find(i => i.id === id);
      const initial = intern ? intern.name.charAt(0).toUpperCase() : '?';
      const color = intern?.color || '#e85d26';
      return `<div class="jira-avatar" style="background:${color};">${initial}</div>`;
    }).join('');
  } else {
    const assignee = INTERNS.find(i => i.id === task.assignedTo);
    if (assignee) {
      const initial = assignee.name.charAt(0).toUpperCase();
      const color = assignee.color || '#e85d26';
      avatarsHtml = `<div class="jira-avatar" style="background:${color};">${initial}</div>`;
    }
  }
  const checkIcon = isDone ? `<i data-lucide="check-square" style="width:16px;height:16px;color:${checkboxColor};"></i>` : `<i data-lucide="square" style="width:16px;height:16px;color:${checkboxColor};"></i>`;
  return `<div class="jira-card" data-task-id="${task.id}" draggable="true" onclick="openAdminTaskDetail('${task.id}')"><div class="jira-card-title">${sanitize(task.title)}</div><div class="jira-card-footer"><div class="jira-card-left">${checkIcon}<span class="jira-task-id" style="color:${checkboxColor};">${task.taskId || 'OF-01'}</span></div><div class="jira-card-right">${task.points ? `<span class="jira-xp-badge">${task.points}XP</span>` : ''}${avatarsHtml ? `<div class="jira-avatars">${avatarsHtml}</div>` : ''}</div></div></div>`;
}

function renderKanbanBoard(allTasks, todoTasks, inProgressTasks, completedTasks) {
  const totalXP = allTasks.reduce((sum, t) => sum + (t.points || 0), 0);
  const columns = [
    { id: 'todo', title: 'TO DO', count: todoTasks.length, tasks: todoTasks },
    { id: 'progress', title: 'IN PROGRESS', count: inProgressTasks.length, tasks: inProgressTasks },
    { id: 'completed', title: 'COMPLETED', count: completedTasks.length, tasks: completedTasks }
  ];
  const columnsHtml = columns.map(column => {
    const cardsHtml = column.tasks.map(task => renderKanbanCard(task)).join('');
    const hasContent = column.tasks.length > 0;
    return `<div class="jira-column ${hasContent ? 'has-content' : 'empty-column'}"><div class="jira-column-header"><div class="jira-column-title">${column.title} <span class="jira-column-count">${column.count}</span></div>${hasContent ? `<button class="jira-menu-btn" onclick="event.stopPropagation();"><i data-lucide="more-vertical" style="width:18px;height:18px;"></i></button>` : ''}</div><div class="jira-column-body" data-column-body="${column.id}">${cardsHtml}${hasContent ? `<button class="jira-add-btn" onclick="event.stopPropagation();openCreateTask()"><i data-lucide="plus" style="width:14px;height:14px;"></i> Create</button>` : ''}</div></div>`;
  }).join('');
  const selectedIntern = window.kanbanInternFilter ? INTERNS.find(i => i.id == window.kanbanInternFilter) : null;
  const internFilterLabel = selectedIntern ? selectedIntern.name : 'All Interns';
  return `<div class="jira-container"><div class="jira-top-nav"><button class="jira-back-btn" onclick="goBackFromBoard()"><i data-lucide="arrow-left" style="width:20px;height:20px;"></i></button><div class="jira-category-dropdown-wrap"><button class="jira-category-dropdown-btn" id="kanbanCategoryBtn" onclick="event.stopPropagation();toggleCategoryDropdown()">${window.kanbanCategoryFilter} <i data-lucide="chevron-down" style="width:16px;height:16px;"></i></button><div class="jira-category-dropdown" id="kanbanCategoryDropdown" style="display:none;"><div class="jira-filter-option ${window.kanbanCategoryFilter === 'All' ? 'selected' : ''}" onclick="setKanbanCategoryFilter('All')">All ${window.kanbanCategoryFilter === 'All' ? '<i data-lucide="check" style="width:14px;height:14px;margin-left:auto;"></i>' : ''}</div><div class="jira-filter-option ${window.kanbanCategoryFilter === 'Office' ? 'selected' : ''}" onclick="setKanbanCategoryFilter('Office')">Office ${window.kanbanCategoryFilter === 'Office' ? '<i data-lucide="check" style="width:14px;height:14px;margin-left:auto;"></i>' : ''}</div><div class="jira-filter-option ${window.kanbanCategoryFilter === 'Academic' ? 'selected' : ''}" onclick="setKanbanCategoryFilter('Academic')">Academic ${window.kanbanCategoryFilter === 'Academic' ? '<i data-lucide="check" style="width:14px;height:14px;margin-left:auto;"></i>' : ''}</div><div class="jira-filter-option ${window.kanbanCategoryFilter === 'Personal' ? 'selected' : ''}" onclick="setKanbanCategoryFilter('Personal')">Personal ${window.kanbanCategoryFilter === 'Personal' ? '<i data-lucide="check" style="width:14px;height:14px;margin-left:auto;"></i>' : ''}</div></div></div><div style="flex:1;"></div><div class="jira-intern-filter-wrap"><button class="jira-icon-btn" id="kanbanInternFilterBtn" onclick="event.stopPropagation();toggleKanbanInternFilter()"><i data-lucide="filter" style="width:20px;height:20px;"></i></button><div class="jira-intern-filter-dropdown" id="kanbanInternFilterDropdown" style="display:none;"><div class="jira-filter-header">Filter by Intern</div><div class="jira-filter-option ${!window.kanbanInternFilter ? 'selected' : ''}" onclick="setKanbanInternFilter('')"><i data-lucide="users" style="width:14px;height:14px;"></i> All Interns ${!window.kanbanInternFilter ? '<i data-lucide="check" style="width:14px;height:14px;margin-left:auto;"></i>' : ''}</div>${INTERNS.filter(i => i.id !== 99).map(intern => `<div class="jira-filter-option ${window.kanbanInternFilter == intern.id ? 'selected' : ''}" onclick="setKanbanInternFilter('${intern.id}')"><div class="jira-filter-avatar" style="background:${intern.color || '#e85d26'};">${intern.name.charAt(0).toUpperCase()}</div>${sanitize(intern.name)}${window.kanbanInternFilter == intern.id ? '<i data-lucide="check" style="width:14px;height:14px;margin-left:auto;"></i>' : ''}</div>`).join('')}</div></div><button class="jira-icon-btn" onclick="openCreateTask()"><i data-lucide="plus" style="width:20px;height:20px;"></i></button></div><div class="jira-tabs"><button class="jira-tab ${window.boardActiveTab === 'board' ? 'active' : ''}" onclick="switchBoardTab('board')"><i data-lucide="trello" style="width:14px;height:14px;"></i> Board</button><button class="jira-tab ${window.boardActiveTab === 'roadmap' ? 'active' : ''}" onclick="switchBoardTab('roadmap')"><i data-lucide="map" style="width:14px;height:14px;"></i> Roadmap</button><button class="jira-tab ${window.boardActiveTab === 'reports' ? 'active' : ''}" onclick="switchBoardTab('reports')"><i data-lucide="bar-chart-2" style="width:14px;height:14px;"></i> Reports</button><button class="jira-tab ${window.boardActiveTab === 'settings' ? 'active' : ''}" onclick="switchBoardTab('settings')"><i data-lucide="settings" style="width:14px;height:14px;"></i> Settings</button></div><div class="jira-board">${columnsHtml}</div><div class="jira-bottom-bar"><div class="jira-filter-status"><span class="jira-filter-badge">${window.kanbanCategoryFilter}</span><span class="jira-filter-badge">${internFilterLabel}</span></div><div class="jira-xp-total">${totalXP}XP</div></div></div>`;
}

function initKanbanDragDrop() {
  const cards = document.querySelectorAll('.jira-card');
  const columns = document.querySelectorAll('.jira-column-body');
  cards.forEach(card => {
    card.addEventListener('dragstart', () => card.classList.add('dragging'));
    card.addEventListener('dragend', () => { card.classList.remove('dragging'); document.querySelectorAll('.jira-column-body').forEach(col => col.classList.remove('drag-over')); });
  });
  columns.forEach(column => {
    column.addEventListener('dragover', (e) => { e.preventDefault(); column.classList.add('drag-over'); });
    column.addEventListener('dragleave', () => column.classList.remove('drag-over'));
    column.addEventListener('drop', async (e) => {
      e.preventDefault();
      column.classList.remove('drag-over');
      const card = document.querySelector('.jira-card.dragging');
      if (!card) return;
      const taskId = card.dataset.taskId;
      const columnId = column.dataset.columnBody;
      if (columnId === 'completed') await updateTaskStatusKanban(taskId, 'completed');
      else if (columnId === 'progress') await updateTaskStatusKanban(taskId, 'progress');
      else if (columnId === 'todo') await updateTaskStatusKanban(taskId, 'pending');
    });
  });
}

function renderAdminTasks(ca) {
  ensureTaskIds();
  const topbar = document.getElementById('mainTopbar');
  if (topbar) topbar.style.display = 'flex';

  // Reuses the exact same swipeable Tasks/Habits shell intern already has
  // (renderInternTasks) — shared header, shared category filter, shared
  // calendar, swipe-to-switch-tabs with the bottom nav label following
  // along. Only the *data* differs (admin aggregates across interns via
  // _thpTargetIds()), which the shared render functions already handle.
  window.thpActiveTab = 'tasks'; // always land on Tasks on fresh navigation
  ca.innerHTML = `<div class="thp-outer">
    <div id="thpSharedHeader"></div>
    <div class="thp-swipe-wrap" id="thpSwipeWrap" onscroll="_thpOnScroll()">
      <div class="thp-page" id="thpTasksPage"></div>
      <div class="thp-divider"></div>
      <div class="thp-page" id="thpHabitsPage"></div>
    </div>
  </div>`;
  _thpRefreshAll();
  // Always land on the Tasks page (not wherever the user last swiped to).
  const wrap = document.getElementById('thpSwipeWrap');
  if (wrap) wrap.scrollLeft = 0;
  const navLabel = document.querySelector('#ambn-tasks .duo-nav-label');
  if (navLabel) navLabel.textContent = 'Tasks';
}

