// ║           REPEAT UTILITIES                        ║
// ╚══════════════════════════════════════════════════╝

// Human-readable label for a repeat config object
function repeatLabel(r) {
  if (!r) return 'None';
  const dn = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  if (r.freq === 'Days'     && r.interval === 1) return 'Daily';
  if (r.freq === 'Days')                         return `Every ${r.interval} Days`;
  if (r.freq === 'Weekdays')                     return 'Every Weekday (Mon–Fri)';
  if (r.freq === 'Weeks') {
    const dayStr = r.days?.length
      ? ' (' + r.days.slice().sort((a,b)=>a-b).map(d=>dn[d]).join(', ') + ')'
      : '';
    return r.interval === 1 ? `Every Week${dayStr}` : `Every ${r.interval} Weeks${dayStr}`;
  }
  if (r.freq === 'Months')  return r.interval === 1 ? 'Monthly'   : `Every ${r.interval} Months`;
  if (r.freq === 'Years')   return r.interval === 1 ? 'Yearly'    : `Every ${r.interval} Years`;
  return `Every ${r.interval} ${r.freq}`;
}

// Auto-refresh timer: re-runs processRepeatTasks every 5 min while logged in.
// Catches the midnight rollover when a user stays logged in all day.
let _repeatCheckTimer = null;
function startRepeatTimer() {
  if (_repeatCheckTimer) clearInterval(_repeatCheckTimer);
  _repeatCheckTimer = setInterval(async () => {
    if (!currentUser || !db) return;
    const changed = processRepeatTasks();
    if (changed) {
      try {
        await saveDB();
        updateBadges();
        if (currentPage) navigateTo(currentPage);
        showStatus('✓ New recurring tasks generated');
      } catch(e) { /* silent — will catch on next sync */ }
    }
  }, 5 * 60 * 1000); // every 5 minutes
}

// ── Repeat Dialog ──
function openRepeatDlg(ctx) {
  document.getElementById('subDialogOverlay')?.remove();
  const cur = _repeatConfig || {freq:'Days', interval:1, days:[]};
  const dn  = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

  // Detect which quick preset matches the current config
  function detectPreset(r) {
    if (!r) return 'daily';
    if (r.freq === 'Days'     && r.interval === 1)  return 'daily';
    if (r.freq === 'Weekdays')                       return 'weekdays';
    if (r.freq === 'Weeks'    && r.interval === 1)   return 'weekly';
    if (r.freq === 'Months'   && r.interval === 1)   return 'monthly';
    return 'custom';
  }
  const initPreset = detectPreset(cur);
  const showDays   = (initPreset === 'weekly') || (initPreset === 'custom' && cur.freq === 'Weeks');
  const showCustom = initPreset === 'custom';

  const ov = document.createElement('div');
  ov.id = 'subDialogOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.45);backdrop-filter:blur(2px);z-index:2000;display:flex;align-items:center;justify-content:center;';
  ov._rs = {freq: cur.freq||'Days', interval: cur.interval||1, days:[...(cur.days||[])], preset: initPreset};

  const pillStyle  = (active) => `padding:6px 14px;border-radius:20px;border:1.5px solid ${active?'#e85d26':'var(--border)'};background:${active?'#e85d26':'var(--surface2)'};color:${active?'#fff':'var(--text2)'};font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;transition:all .15s;`;
  const presets = [{k:'daily','label':'⚡ Daily'},{k:'weekdays',label:'📅 Weekdays'},{k:'weekly',label:'🗓 Weekly'},{k:'monthly',label:'📆 Monthly'},{k:'custom',label:'⚙ Custom'}];

  ov.innerHTML = `
    <div style="background:var(--card-bg);border:1px solid var(--border);border-radius:14px;padding:24px;width:370px;max-width:95vw;box-shadow:0 20px 60px rgba(0,0,0,.35);">
      <div style="font-size:15px;font-weight:700;color:var(--text);margin-bottom:4px;">🔁 Repeat Schedule</div>
      <div style="font-size:12px;color:var(--text2);margin-bottom:4px;">A NEW copy of this task is auto-created each day on the chosen schedule.</div>
      <div style="background:var(--surface2);border:1px solid var(--border);border-radius:6px;padding:6px 10px;font-size:11px;color:#e85d26;margin-bottom:14px;">⚡ <strong>Daily</strong> = a fresh task appears every day for the intern — they complete it each day.</div>

      <!-- Quick Preset Pills -->
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px;">
        ${presets.map(p=>`<button id="rp-${p.k}" onclick="selectRepPreset('${p.k}')" style="${pillStyle(initPreset===p.k)}">${p.label}</button>`).join('')}
      </div>

      <!-- Custom Controls (visible only in Custom mode) -->
      <div id="repCustomSection" style="display:${showCustom?'flex':'none'};align-items:center;gap:10px;margin-bottom:12px;">
        <div style="background:var(--surface2);border-radius:8px;display:flex;align-items:center;border:1px solid var(--border);flex-shrink:0;">
          <button onclick="chRI(-1)" style="background:none;border:none;color:var(--text);padding:7px 12px;cursor:pointer;font-size:15px;">−</button>
          <span id="riVal" style="color:var(--text);font-weight:700;min-width:26px;text-align:center;">${cur.interval||1}</span>
          <button onclick="chRI(1)"  style="background:none;border:none;color:var(--text);padding:7px 12px;cursor:pointer;font-size:15px;">+</button>
        </div>
        <select id="rfSel" onchange="updateRFUI()" style="background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:8px 11px;font-size:14px;font-family:inherit;flex:1;outline:none;">
          ${['Days','Weekdays','Weeks','Months','Years'].map(f=>`<option value="${f}" ${(cur.freq||'Days')===f?'selected':''}>${f}</option>`).join('')}
        </select>
      </div>

      <!-- Day-of-Week Picker (Weekly preset or Weeks in Custom) -->
      <div id="rDaysRow" style="display:${showDays?'flex':'none'};gap:5px;flex-wrap:wrap;margin-bottom:14px;">
        ${dn.map((d,i)=>`<button id="rd-${i}" onclick="togRD(${i})" style="width:40px;height:40px;border-radius:50%;border:none;cursor:pointer;font-size:11px;font-weight:700;background:${cur.days?.includes(i)?'#e85d26':'var(--surface2)'};color:${cur.days?.includes(i)?'#fff':'var(--text2)'};transition:all .15s;">${d}</button>`).join('')}
      </div>

      <!-- Live Preview -->
      <div style="background:var(--surface2);border:1px solid var(--border);border-radius:8px;padding:9px 13px;font-size:12px;color:var(--text2);margin-bottom:18px;">
        Task repeats: <strong id="repPreviewLabel" style="color:#e85d26;">${repeatLabel(ov._rs)}</strong>
      </div>

      <div style="display:flex;gap:7px;justify-content:flex-end;">
        <button onclick="cancelRep()" style="background:none;border:1px solid var(--border);color:var(--text2);border-radius:8px;padding:7px 14px;cursor:pointer;font-family:inherit;">Cancel</button>
        <button onclick="clearRep('${ctx}')" style="background:none;border:1px solid #e53e3e;color:#e53e3e;border-radius:8px;padding:7px 14px;cursor:pointer;font-family:inherit;">Remove</button>
        <button onclick="confirmRep('${ctx}')" style="background:#e85d26;color:#fff;border:none;border-radius:8px;padding:7px 14px;cursor:pointer;font-family:inherit;font-weight:600;">✓ Done</button>
      </div>
    </div>`;
  document.body.appendChild(ov);
}

// Select a quick preset pill
function selectRepPreset(p) {
  const ov = document.getElementById('subDialogOverlay'); if (!ov) return;
  ov._rs.preset = p;
  // Update pill styles
  ['daily','weekdays','weekly','monthly','custom'].forEach(k => {
    const btn = document.getElementById('rp-'+k); if (!btn) return;
    const active = k === p;
    btn.style.background   = active ? '#e85d26' : 'var(--surface2)';
    btn.style.borderColor  = active ? '#e85d26' : 'var(--border)';
    btn.style.color        = active ? '#fff'    : 'var(--text2)';
  });
  // Apply preset config
  const map = {daily:{freq:'Days',interval:1}, weekdays:{freq:'Weekdays',interval:1},
               weekly:{freq:'Weeks',interval:1}, monthly:{freq:'Months',interval:1}};
  if (map[p]) { ov._rs.freq = map[p].freq; ov._rs.interval = map[p].interval; }
  // Show/hide custom controls
  const cs = document.getElementById('repCustomSection');
  if (cs) cs.style.display = p==='custom' ? 'flex' : 'none';
  // Sync the custom select with current freq
  const rfSel = document.getElementById('rfSel'); if (rfSel) rfSel.value = ov._rs.freq;
  const riVal = document.getElementById('riVal'); if (riVal) riVal.textContent = ov._rs.interval;
  // Show/hide day picker
  const showDays = p==='weekly' || (p==='custom' && ov._rs.freq==='Weeks');
  const dr = document.getElementById('rDaysRow'); if (dr) dr.style.display = showDays?'flex':'none';
  updateRepPreview();
}

// Update the live "Task repeats: X" preview line
function updateRepPreview() {
  const ov  = document.getElementById('subDialogOverlay'); if (!ov) return;
  const lbl = document.getElementById('repPreviewLabel'); if (!lbl) return;
  lbl.textContent = repeatLabel(ov._rs);
}

function chRI(d) {
  const ov = document.getElementById('subDialogOverlay');
  const el = document.getElementById('riVal');
  let v = parseInt(el.textContent) + d;
  if (v < 1) v = 1; if (v > 365) v = 365;
  el.textContent = v; ov._rs.interval = v; updateRepPreview();
}

function updateRFUI() {
  const freq = document.getElementById('rfSel').value;
  const ov = document.getElementById('subDialogOverlay');
  if (ov) ov._rs.freq = freq;
  const dr = document.getElementById('rDaysRow');
  if (dr) dr.style.display = freq==='Weeks' ? 'flex' : 'none';
  updateRepPreview();
}

function togRD(i) {
  const ov  = document.getElementById('subDialogOverlay');
  const st  = ov._rs;
  const btn = document.getElementById('rd-'+i);
  if (st.days.includes(i)) {
    st.days = st.days.filter(d=>d!==i);
    btn.style.background='var(--surface2)'; btn.style.color='var(--text2)';
  } else {
    st.days.push(i);
    btn.style.background='#e85d26'; btn.style.color='#fff';
  }
  updateRepPreview();
}

function cancelRep() { document.getElementById('subDialogOverlay')?.remove(); }

function clearRep(ctx) {
  _repeatConfig = null;
  document.getElementById('subDialogOverlay')?.remove();
  const lel = document.getElementById(ctx==='t' ? 'tRepLabel' : 'ptRepLabel');
  if (lel) lel.textContent = 'None';
}

function confirmRep(ctx) {
  const ov = document.getElementById('subDialogOverlay');
  const st = ov._rs;
  // Weekly preset requires at least one day selected
  if ((st.preset==='weekly' || st.freq==='Weeks') && st.days.length===0) {
    document.getElementById('repPreviewLabel').textContent = '⚠ Select at least one day';
    document.getElementById('repPreviewLabel').style.color = '#e53e3e'; return;
  }
  _repeatConfig = {freq:st.freq, interval:st.interval, days:[...st.days]};
  ov.remove();
  const lel = document.getElementById(ctx==='t' ? 'tRepLabel' : 'ptRepLabel');
  if (lel) lel.textContent = repeatLabel(_repeatConfig);
}

// ── Colour / Icon picker interactions ──────────────────────────
function ctToggleColorPicker() {
  const strip=document.getElementById('ctColorStrip'), grid=document.getElementById('ctIconGrid');
  const vis=strip?.classList.contains('visible');
  if(grid) grid.classList.remove('visible');
  strip?.classList.toggle('visible',!vis);
  if(strip && !vis) strip.querySelector('.ct-color-swatch.sel')?.scrollIntoView({block:'nearest',inline:'center'});
}
function ctPickColor(hex) {
  _ctIconColor=hex;
  const dot=document.getElementById('ctColorDot');
  if(dot){dot.style.background=hex;}
  const ip=document.getElementById('ctIconPreview');
  if(ip){ip.style.background=hex+'33';ip.style.color=hex;}
  document.querySelectorAll('.ct-color-swatch').forEach(s=>s.classList.toggle('sel',s.dataset.color===hex));
}
function ctToggleIconPicker() {
  const grid=document.getElementById('ctIconGrid'), strip=document.getElementById('ctColorStrip');
  const vis=grid?.classList.contains('visible');
  if(strip) strip.classList.remove('visible');
  grid?.classList.toggle('visible',!vis);
  if(grid && !vis) grid.querySelector('.ct-icon-opt.sel')?.scrollIntoView({block:'nearest'});
}
function ctPickIcon(key) {
  if(!HABIT_ICONS||!HABIT_ICONS[key]) return;
  const svg=HABIT_ICONS[key]; _ctIconSvg=svg;
  const ip=document.getElementById('ctIconPreview');
  if(ip) ip.innerHTML=svg.replace('viewBox','width="22" height="22" viewBox');
  document.querySelectorAll('.ct-icon-opt').forEach(o=>o.classList.toggle('sel',o.dataset.key===key));
}
function ctOpenSymbolPicker() {
  const SYMBOLS=['🏋','🎯','💊','🛌','📖','💧','🍎','🧘','🚶','🏃','🚴','🎸','💻','✏️','🎨','🧹','💡','🔥','⚡','🌟','🏆','💪','🧠','❤️','🌿','☀️','🌙'];
  _openCtMiniSheet('Symbol', SYMBOLS.map(s=>({
    label:s,
    action:()=>{
      const sp=document.getElementById('ctSymbolPreview'); if(sp) sp.textContent=s;
      window._ctSymbol=s;
    }
  })));
}

// ── Frequency interactions ──────────────────────────────────────
function ctSetFreq(key) {
  _ctFreqMode=key;
  _ctFreqToRepeatConfig();
  const container=document.getElementById('ctFreqOptions'); if(!container) return;
  const dowLabels=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const opts=[
    {key:'None',label:'None',sub:null},
    {key:'Everyday',label:'Everyday',sub:null},
    {key:'SpecificDaysOfWeek',label:'Specific Days of Week',sub:'dow'},
    {key:'SpecificDaysOfMonth',label:'Specific Days of Month',sub:'dom'},
    {key:'SomeDaysPerPeriod',label:'Some Days Per Period',sub:'period'},
  ];
  container.innerHTML=opts.map(opt=>{
    const isSel=_ctFreqMode===opt.key;
    let sub='';
    if(isSel&&opt.sub==='dow') sub=`<div class="ct-freq-sub visible"><div class="ct-dow-row">${dowLabels.map((d,i)=>`<div class="ct-dow-pill${_ctDowSelected.includes(i)?' sel':''}" onclick="ctToggleDow(${i})">${d}</div>`).join('')}</div></div>`;
    else if(isSel&&opt.sub==='dom') sub=`<div class="ct-freq-sub visible"><div class="ct-dom-grid">${Array.from({length:31},(_,i)=>`<div class="ct-dom-pill${_ctDomSelected.includes(i+1)?' sel':''}" onclick="ctToggleDom(${i+1})">${i+1}</div>`).join('')}</div></div>`;
    else if(isSel&&opt.sub==='period') sub=`<div class="ct-freq-sub visible"><div class="ct-period-row"><div class="ct-period-num"><button class="ct-period-btn" onclick="ctPeriodAdj(-1)">−</button><span class="ct-period-val" id="ctPeriodVal">${_ctPeriodN}</span><button class="ct-period-btn" onclick="ctPeriodAdj(1)">+</button></div><span style="font-size:14px;color:var(--text);">days per</span><select class="ct-period-sel" id="ctPeriodUnit" onchange="ctPeriodUnitChange(this.value)"><option value="week"${_ctPeriodUnit==='week'?' selected':''}>Week</option><option value="month"${_ctPeriodUnit==='month'?' selected':''}>Month</option></select></div></div>`;
    return `<div class="ct-freq-option" onclick="ctSetFreq('${opt.key}')"><div class="ct-freq-radio${isSel?' sel':''}"></div><span class="ct-freq-option-label">${opt.label}</span></div>${sub}`;
  }).join('');
}
function ctToggleDow(i) {
  _ctDowSelected=_ctDowSelected.includes(i)?_ctDowSelected.filter(d=>d!==i):[..._ctDowSelected,i];
  ctSetFreq('SpecificDaysOfWeek');
}
function ctToggleDom(n) {
  _ctDomSelected=_ctDomSelected.includes(n)?_ctDomSelected.filter(d=>d!==n):[..._ctDomSelected,n];
  ctSetFreq('SpecificDaysOfMonth');
}
function ctPeriodAdj(d) {
  _ctPeriodN=Math.max(1,Math.min(30,_ctPeriodN+d));
  const el=document.getElementById('ctPeriodVal'); if(el) el.textContent=_ctPeriodN;
  _ctFreqToRepeatConfig();
}
function ctPeriodUnitChange(v) { _ctPeriodUnit=v; _ctFreqToRepeatConfig(); }
function _ctFreqToRepeatConfig() {
  if(_ctFreqMode==='None' || !_ctFreqMode) { _repeatConfig=null; return; }
  if(_ctFreqMode==='Everyday') { _repeatConfig={freq:'Days',interval:1,days:[]}; return; }
  if(_ctFreqMode==='SpecificDaysOfWeek') { _repeatConfig={freq:'Weeks',interval:1,days:[..._ctDowSelected]}; return; }
  if(_ctFreqMode==='SpecificDaysOfMonth') { _repeatConfig={freq:'Months',interval:1,days:[],dom:[..._ctDomSelected]}; return; }
  if(_ctFreqMode==='SomeDaysPerPeriod') {
    const di=_ctPeriodUnit==='week'?Math.max(1,Math.round(7/_ctPeriodN)):Math.max(1,Math.round(30/_ctPeriodN));
    _repeatConfig={freq:'Days',interval:di,days:[],periodN:_ctPeriodN,periodUnit:_ctPeriodUnit};
  }
}

// ── Checklist interactions ──────────────────────────────────────
if(!window._ctChecklistItems) window._ctChecklistItems=[];
function ctToggleChecklist(cb) {
  const el=document.getElementById('ctChecklistItems'); if(!el) return;
  el.style.display=cb.checked?'block':'none';
  if(cb.checked&&window._ctChecklistItems.length===0) ctAddChecklistItem();
}
function ctAddChecklistItem() {
  if(!window._ctChecklistItems) window._ctChecklistItems=[];
  const id='ci-'+Date.now();
  window._ctChecklistItems.push({id,text:''});
  _renderChecklistItems();
}
function ctRemoveChecklistItem(id) {
  window._ctChecklistItems=(window._ctChecklistItems||[]).filter(i=>i.id!==id);
  _renderChecklistItems();
}
function _renderChecklistItems() {
  const list=document.getElementById('ctChecklistList'); if(!list) return;
  list.innerHTML=(window._ctChecklistItems||[]).map(item=>`
    <div class="ct-checklist-item" id="clw-${item.id}">
      <div class="ct-checklist-dot"></div>
      <input type="text" class="ct-checklist-input" placeholder="Enter item…" value="${sanitize(item.text)}"
             oninput="ctUpdateChecklistItem('${item.id}',this.value)">
      <button class="ct-checklist-del" onclick="ctRemoveChecklistItem('${item.id}')">
        <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </div>`).join('');
}
function ctUpdateChecklistItem(id,val) {
  const item=(window._ctChecklistItems||[]).find(i=>i.id===id);
  if(item) item.text=val;
}

// ── Attachment interactions ─────────────────────────────────────
function ctOpenAttachment() { document.getElementById('ctAttachFile')?.click(); }
function ctHandleAttachment(input) {
  const file=input.files&&input.files[0]; if(!file) return;
  window._ctAttachName=file.name;
  const lbl=document.getElementById('ctAttachLabel');
  if(lbl) { lbl.textContent=file.name.length>24?file.name.slice(0,22)+'…':file.name; lbl.style.color='var(--accent)'; }
  showToast('✓',`Attachment: ${file.name}`);
}

async function saveTask() {
  const title = document.getElementById('tTitle')?.value.trim();
  if (!title) { showToast('Title required', 'error'); return; }
  const approvalRequired = document.getElementById('tApproval')?.checked || false;
  if (approvalRequired && !_approvalContribId) { showToast('Select a contributor for approval', 'error'); openApprovalContribDlg(); return; }
  const selectedIds = [...document.querySelectorAll('.tInternCb:checked')].map(cb => parseInt(cb.value));
  if (selectedIds.length === 0) { showToast('Select at least one intern', 'error'); return; }
  const _rawPts = parseInt(document.getElementById('tPoints')?.value);
  const _validPts = (isFinite(_rawPts) && !isNaN(_rawPts)) ? Math.max(0, Math.min(_rawPts, 9999)) : 0;
  // Build checklist
  const checklist = (window._ctChecklistItems||[]).filter(i=>i.text.trim()).map(i=>({id:i.id,text:i.text.trim(),done:false}));
  const baseData = {
    title,
    description: document.getElementById('tDesc')?.value || '',
    category: _ctCategory || 'Office',
    points: _validPts,
    dueDate: document.getElementById('tDue')?.value || '',
    repeat: null,
    approvalRequired, approvalContribId: _approvalContribId,
    isPersonal: false, createdDate: today(), createdAt: Date.now(),
    isTemplate: false,
    iconSvg:    _ctIconSvg   || null,
    iconColor:  _ctIconColor || null,
    checklist:  checklist.length ? checklist : null,
    symbol:     window._ctSymbol || null,
    attachmentName: window._ctAttachName || null,
  };
  const ts = Date.now();
  const task = { ...baseData, id: 't-' + ts, assignedTo: selectedIds[0], sharedWith: selectedIds };
  db.tasks.unshift(task);
  selectedIds.forEach(assignedTo => {
    if (!db.notifications[assignedTo]) db.notifications[assignedTo] = [];
    db.notifications[assignedTo].unshift({id:'n-'+Date.now()+'-'+assignedTo, msg:`New task assigned: "${title}"`, type:'task', read:false, date:today()});
  });
  closeCt(); _approvalContribId = null; _repeatConfig = null;
  window._ctChecklistItems = []; window._ctAttachName = null; window._ctSymbol = null;
  await saveAndRefresh(`Task shared with ${selectedIds.length} intern(s)!`, 'adminTasks');
}

// ╔══════════════════════════════════════════════════╗
// ║   ADMIN ALERTS — tabbed (req 7): Approvals / Complaints / Task Alerts
// ╚══════════════════════════════════════════════════╝
function renderAdminNotifs(ca) {
  const notifs = db.adminNotifications || [];
  const requests = (db.pendingRequests || []).filter(r => r.status === 'pending');
  const hadUnread = notifs.some(n => !n.isRequest && !n.read);
  notifs.forEach(n => { if (!n.isRequest) n.read = true; });
  if (hadUnread) saveDB();
  updateBadges();

  const taskNotifs = notifs.filter(n => !n.isRequest);

  const notifCard = n => `<div class="notif-item">
    <div class="notif-item-icon" style="background:rgba(39,174,96,.1);">${{task:'✅',repeat:'🔁',entry:'📊',request:'📨',announcement:'📢'}[n.type]||'🔔'}</div>
    <div class="notif-item-body"><div class="notif-item-msg">${sanitize(n.msg)}</div><div class="notif-item-date">${sanitize(n.date||'')}</div></div>
  </div>`;

  const approvalsHTML = requests.length === 0
    ? `<div class="txp-empty">No pending approvals.</div>`
    : requests.map(r => {
        const intern = INTERNS.find(i => i.id === r.internId);
        const typeLabel = r.type==='entry' ? `Entry: ${sanitize(r.category||'')}` : `Task: "${sanitize(r.taskTitle||'')}"`;
        return `<div class="complaint-card" style="border-left:4px solid var(--accent);">
          <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
            <div style="width:36px;height:36px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;color:#fff;flex-shrink:0;">${sanitize(intern?.name?.[0]||'?')}</div>
            <div style="flex:1;"><div style="font-weight:700;font-size:13px;">📨 ${sanitize(intern?.name||'Unknown')}</div><div style="font-size:12px;color:var(--text2);">${typeLabel}</div>${r.note ? `<div style="font-size:11px;color:var(--text3);">"${sanitize(r.note)}"</div>` : ''}</div>
            <div style="font-size:11px;color:var(--text3);">${sanitize(r.date||'')}</div>
          </div>
          <div style="display:flex;gap:7px;">
            <button class="btn btn-success btn-sm" onclick="approveRequest('${r.id}')">✅ Approve</button>
            <button class="btn btn-danger btn-sm" onclick="denyRequest('${r.id}')">❌ Deny</button>
          </div>
        </div>`;
      }).join('');

  const complaintsHTML = (db.complaints||[]).length === 0
    ? `<div class="txp-empty">No complaints yet.</div>`
    : (db.complaints||[]).slice(0,20).map(c => {
        const from = INTERNS.find(i=>i.id===c.from); const against = INTERNS.find(i=>i.id===c.against);
        return `<div class="complaint-card" style="${c.done?'opacity:.6;':''}">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">
            <div style="font-weight:700;font-size:13px;">${sanitize(c.subject)}</div>
            ${c.done ? '<span class="badge badge-green">✓ Resolved</span>' : `<button class="btn btn-success btn-sm" onclick="markComplaintDone('${c.id}')">✓ Done</button>`}
          </div>
          <div style="font-size:12px;color:var(--text2);">${sanitize(from?.name||'?')} → ${sanitize(against?.name||'?')} · ${sanitize(c.date||'')}</div>
        </div>`;
      }).join('');

  const alertsHTML = taskNotifs.length === 0
    ? `<div class="txp-empty">No task alerts yet.</div>`
    : taskNotifs.map(notifCard).join('') + `<div style="margin-top:10px;"><button class="btn btn-danger btn-sm" onclick="clearAdminNotifs()">Clear Alerts</button></div>`;

  const filterVal = window.adminNotifFilter || 'Entries';
  let content = '';
  if (filterVal === 'Entries') {
    content = approvalsHTML;
  } else if (filterVal === 'Complaints') {
    content = complaintsHTML;
  } else {
    content = alertsHTML;
  }

  ca.innerHTML = `<div class="it-page">
    <div class="txp-list" style="padding:12px 4px 0;">${content}</div>
  </div>`;
  _populateAdminNotifFilter();
  if (window.lucide) lucide.createIcons(); initCarousels();
}
function setAdminNotifTab(tab) {
  window.adminNotifTab = tab;
  renderAdminNotifs(document.getElementById('contentArea'));
}

async function clearAdminNotifs() {
  db.adminNotifications = db.adminNotifications.filter(n => n.isRequest);
  await saveAndRefresh('Cleared', 'adminNotifs');
}

