              const rw=storeRw.find(x=>x.id===rdm.rewardId);
              const intern=interns.find(i=>i.id===rdm.internId);
              const cat=CATS[rw?.category]||CATS.physical;
              const st=RDST[rdm.status]||RDST.pending;
              const ini=(intern?.name||'?').split(' ').map(x=>x[0]).join('').toUpperCase().slice(0,2);
