  const statusLabel = r.active!==false ? 'Active' : 'Inactive';

  // Terms as bullet list
  const termLines = (r.terms||'').split('\n').filter(Boolean);
  const termHtml = termLines.length
    ? termLines.map(l=>`<li>${sanitize(l)}</li>`).join('')
    : `<li>No terms specified.</li>`;

  // Validity display
  let validityStr = '—';
  if(r.validityStart && r.validityEnd) {
    const fmt = d=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
    validityStr = fmt(r.validityStart)+' – '+fmt(r.validityEnd);
  } else if(r.validityEnd) {
    validityStr = 'Until '+new Date(r.validityEnd).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
  }

  // Category SVG icons for info row
