// BUG-21 FIX: Show / hide password on login form
function togglePwVisibility() {
  const inp = document.getElementById('loginPass');
  const btn = document.getElementById('pwToggleBtn');
  const icon = document.getElementById('pwToggleIcon');
  if (!inp) return;
  if (inp.type === 'password') {
    inp.type = 'text';
    if (icon) { icon.setAttribute('data-lucide','eye-off'); lucide.createIcons(); }
  } else {
    inp.type = 'password';
    if (icon) { icon.setAttribute('data-lucide','eye'); lucide.createIcons(); }
  }
}

// PHASE-2 FIX-3: Dark mode toggle
function toggleDarkMode() {
  const html = document.documentElement;
  const isDark = html.getAttribute('data-theme') === 'dark';
  const next = isDark ? 'light' : 'dark';
  html.setAttribute('data-theme', next);
  try { localStorage.setItem('txp_theme', next); } catch(e) {}
  // Update toggle icon
  const btn = document.getElementById('themeToggle');
  if (btn) {
    const i = btn.querySelector('i');
    if (i) { i.setAttribute('data-lucide', next === 'dark' ? 'sun' : 'moon'); lucide.createIcons(); }
  }
}

// Restore saved theme on load (called before render)
function restoreTheme() {
  try {
    const saved = localStorage.getItem('txp_theme');
    if (saved === 'dark') {
      document.documentElement.setAttribute('data-theme','dark');
      // Update icon after DOM ready
      setTimeout(() => {
        const btn = document.getElementById('themeToggle');
        if (btn) {
          const i = btn.querySelector('i');
          if (i) { i.setAttribute('data-lucide','sun'); if (window.lucide) lucide.createIcons(); initCarousels(); }
        }
      }, 100);
    }
  } catch(e) {}
}


// ╔══════════════════════════════════════════════════╗
// ║          PULL-TO-REFRESH  (Modern / Fluid)       ║
// ║  • Works from top of page on a long drag down    ║
// ║  • Rubber-band pill indicator with arrow→spin    ║
// ║  • Haptic-style resistance curve                 ║
// ║  • Restores page + scroll/carousel position      ║
// ╚══════════════════════════════════════════════════╝
(function initPullToRefresh() {

  // ── Config ────────────────────────────────────────
  const THRESHOLD   = 90;   // px of pull distance to commit refresh
  const DEAD_ZONE   = 8;    // px before anything moves
  const MAX_PULL    = 110;  // px — maximum visual travel of pill
  const RESIST      = 0.45; // resistance multiplier (lower = heavier feel)

  // ── State ─────────────────────────────────────────
  let startY = 0, currentY = 0;
  let pulling = false, triggered = false, refreshing = false;

  // ── Build indicator pill (once) ───────────────────
  function buildIndicator() {
    if (document.getElementById('ptr-pill')) return;
    const pill = document.createElement('div');
    pill.id = 'ptr-pill';
    pill.innerHTML = `
      <div class="ptr-icon-wrap" id="ptrIconWrap">
        <svg class="ptr-arrow" id="ptrArrow" xmlns="http://www.w3.org/2000/svg" width="18" height="18"
          viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"
          stroke-linecap="round" stroke-linejoin="round">
          <line x1="12" y1="5" x2="12" y2="19"/>
          <polyline points="19 12 12 19 5 12"/>
        </svg>
        <svg class="ptr-spinner-svg" id="ptrSpinner" xmlns="http://www.w3.org/2000/svg"
          width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor"
          stroke-width="2.5" stroke-linecap="round">
          <path d="M21 12a9 9 0 1 1-6.219-8.56"/>
        </svg>
      </div>
      <span class="ptr-pill-label" id="ptrLabel">Pull to refresh</span>`;
    document.body.appendChild(pill);
  }

  // ── Utilities ─────────────────────────────────────
  function canPull() {
    const ls = document.getElementById('loginScreen');
    if (ls && ls.classList.contains('active')) return false;
    if (refreshing) return false;
    const ca = document.getElementById('contentArea');
    return !ca || ca.scrollTop <= 1; // must be at (or very near) top
  }

  function setPillState(progress, travel) {
    buildIndicator();
    const pill   = document.getElementById('ptr-pill');
    const arrow  = document.getElementById('ptrArrow');
    const lbl    = document.getElementById('ptrLabel');
    if (!pill) return;

    // Translate pill down from above the topbar
    const topbarH = document.getElementById('topbar')?.offsetHeight || 56;
    const y = Math.min(travel, MAX_PULL);
    pill.style.transform = `translate(-50%, ${y - 56}px)`;
    pill.style.opacity   = String(Math.min(progress * 2, 1));

    // Rotate arrow proportionally → full 180° when threshold hit
    const deg = Math.min(progress, 1) * 180;
    if (arrow) arrow.style.transform = `rotate(${deg}deg)`;

    // Label text
    if (lbl) lbl.textContent = progress >= 1 ? 'Release to refresh' : 'Pull to refresh';

    // Ready-state styling
    pill.classList.toggle('ptr-ready', progress >= 1);
  }

  function resetPill(animate) {
    const pill = document.getElementById('ptr-pill');
    if (!pill) return;
    if (animate) {
      pill.style.transition = 'transform .28s cubic-bezier(.4,0,.2,1), opacity .22s';
      pill.style.transform  = 'translate(-50%, -70px)';
      pill.style.opacity    = '0';
      setTimeout(() => {
        pill.style.transition = '';
        pill.classList.remove('ptr-ready', 'ptr-loading');
      }, 300);
    } else {
      pill.style.transition = '';
      pill.style.transform  = 'translate(-50%, -70px)';
      pill.style.opacity    = '0';
      pill.classList.remove('ptr-ready', 'ptr-loading');
    }
  }

  function showLoaderState() {
    const pill    = document.getElementById('ptr-pill');
    const arrow   = document.getElementById('ptrArrow');
    const spinner = document.getElementById('ptrSpinner');
    const lbl     = document.getElementById('ptrLabel');
    if (!pill) return;
    const topbarH = document.getElementById('topbar')?.offsetHeight || 56;
    pill.style.transition = 'transform .2s cubic-bezier(.4,0,.2,1)';
    pill.style.transform  = `translate(-50%, ${topbarH - 20}px)`;
    pill.style.opacity    = '1';
    pill.classList.add('ptr-loading');
    if (arrow)   arrow.style.display   = 'none';
    if (spinner) spinner.style.display = 'block';
    if (lbl)     lbl.textContent       = 'Refreshing…';
  }

  // ── Save/restore page state ────────────────────────
  function saveState() {
    const ca = document.getElementById('contentArea');
    const carousels = {};
    document.querySelectorAll('.cp-tab-strip').forEach(strip => {
      strip.querySelectorAll('.cp-tab').forEach((t, i) => {
        if (t.classList.contains('active')) carousels[strip.id] = i;
      });
    });
    return { page: currentPage, scrollTop: ca ? ca.scrollTop : 0, carousels };
  }

  // ── Main refresh ───────────────────────────────────
  async function doRefresh(state) {
    refreshing = true;
    showLoaderState();
    try {
      await loadDB();
      await navigateTo(state.page);
      updateBadges();
      requestAnimationFrame(() => {
        Object.entries(state.carousels).forEach(([sid, idx]) =>
          carouselGoTo(sid.replace('-strip', ''), idx, false));
        const ca = document.getElementById('contentArea');
        if (ca) ca.scrollTop = state.scrollTop;
      });
      showToast('Refreshed', 'success');
    } catch(e) {
      showToast('Refresh failed — check connection', 'error');
    } finally {
      refreshing = false;
      triggered  = false;
      // Short pause so user sees the spinner, then retract
      setTimeout(() => resetPill(true), 400);
      // Restore spinner/arrow visibility for next pull
      setTimeout(() => {
        const arrow   = document.getElementById('ptrArrow');
        const spinner = document.getElementById('ptrSpinner');
        if (arrow)   arrow.style.display   = '';
        if (spinner) spinner.style.display = '';
      }, 800);
    }
  }

  // ── Touch handlers ─────────────────────────────────
  document.addEventListener('touchstart', e => {
    if (!canPull()) { pulling = false; return; }
    startY   = e.touches[0].clientY;
    currentY = startY;
    pulling  = true;
    triggered = false;
  }, { passive: true });

  document.addEventListener('touchmove', e => {
    if (!pulling || triggered || refreshing) return;
    currentY = e.touches[0].clientY;
    const raw = currentY - startY;

    // Abort if scrolling up
    if (raw <= 0) { pulling = false; resetPill(false); return; }

    // Double-check we're still at top
    const ca = document.getElementById('contentArea');
    if (ca && ca.scrollTop > 1) { pulling = false; resetPill(false); return; }

    if (raw < DEAD_ZONE) return;

    const travel   = (raw - DEAD_ZONE) * RESIST;
    const progress = travel / THRESHOLD;
    setPillState(progress, travel);
  }, { passive: true });

  document.addEventListener('touchend', async () => {
    if (!pulling || triggered || refreshing) { pulling = false; return; }
    pulling = false;

    const raw      = currentY - startY;
    const travel   = (raw - DEAD_ZONE) * RESIST;
    const progress = travel / THRESHOLD;

    if (progress >= 1) {
      triggered = true;
      const state = saveState();
      await doRefresh(state);
    } else {
      resetPill(true);
    }
  });

  document.addEventListener('touchcancel', () => {
    pulling = false;
    if (!refreshing) resetPill(true);
  });

})();


window.addEventListener('load', async () => {
  // PHASE-2 FIX-3: Restore saved theme before anything renders
  restoreTheme();
  // ── RESTORE SESSION: if a valid session exists, skip the login screen ──────
  // The user only gets shown the login screen if they explicitly logged out,
  // or if this is their first ever visit. Closing the app / refreshing keeps
  // them logged in — just like WhatsApp, Gmail, and every modern mobile app.
  let restored = false;
  try {
    const raw = localStorage.getItem('txp_session');
    if (raw) {
      const { id } = JSON.parse(raw);
      const user = INTERNS.find(i => i.id === id);
      if (user) {
        // Valid saved session — restore it silently
        showLoading('Restoring session...');
        try {
          await loadDB();
          hideLoading();
          currentUser = user;
          currentRole = user.role || 'intern';
          document.getElementById('loadingOverlay').classList.add('hidden');
          document.getElementById('loginScreen').classList.remove('active');
          document.getElementById('mainScreen').classList.add('active');
          const _fn = user.name.split(' ')[0];
          document.getElementById('topFirstName') && (document.getElementById('topFirstName').textContent = sanitize(_fn));
          document.getElementById('topName') && (document.getElementById('topName').textContent = sanitize(user.name));
          document.getElementById('topRole').textContent   = currentRole === 'admin' ? 'Administrator' : 'Intern';
          (function() {
            const av = document.getElementById('topAvatar');
            if (!av) return;
            const avCfg = db?.submissions?.[user.id]?.avatar || {};
            const avUrl = buildAvatarUrl(avCfg);
            av.innerHTML = ''; // clear initials
            av.style.background = 'none'; av.style.overflow = 'hidden'; av.style.padding = '0';
            const img = document.createElement('img');
            img.src = avUrl;
            img.style.cssText = 'width:100%;height:100%;object-fit:cover;object-position:top center;border-radius:50%;';
            img.onerror = () => { av.textContent = user.name[0]; av.style.background = 'var(--accent)'; };
            av.insertBefore(img, av.firstChild);
          })();
          window.taskFilter = 'Today'; window.adminTaskFilter = 'Sent';
          window.adminSelectedIntern = null; window.atFilterAssignee = ''; window.atFilterCat = '';
          renderSidebar();
          startRepeatTimer();
          _dmSubscribeUnreadBadge();
          _thStartRealtime();
          if (window.lucide) lucide.createIcons(); initCarousels();
          await navigateTo(currentRole === 'admin' ? 'adminDashboard' : 'internDashboard');
          restored = true;
        } catch(e) {
          // Firebase error — clear broken session and fall through to login
          hideLoading();
          try { localStorage.removeItem('txp_session'); } catch(e2) {}
        }
      }
    }
  } catch(e) { /* malformed localStorage — ignore and show login */ }

  if (!restored) {
    setTimeout(() => {
      document.getElementById('loadingOverlay').classList.add('hidden');
      document.getElementById('loginScreen').classList.add('active');
      if (window.lucide) lucide.createIcons(); initCarousels();
    }, 800);
  }
});



// ══════════════════════════════════════════════════════════════
//  PEEK CAROUSEL — build HTML (req 1)
// ══════════════════════════════════════════════════════════════
function buildTabCarousel(carouselId, panelDefs, opts) {
  opts = opts || {};
  const tabs = panelDefs.map((p, i) =>
    `<button class="cp-tab${i===0?' active':''}" onclick="carouselGoTo('${carouselId}',${i})">${p.label}</button>`
  ).join('');
  const panels = panelDefs.map(p => `<div class="carousel-panel">${p.content}</div>`).join('');
  // Spacers at both ends let the first and last tabs scroll to true center.
  // Width = 50% strip − 21% (half of 42% tab) = 29%
  const spacer = '<span class="cp-tab-spacer"></span>';
  return `<div class="cp-strip-wrap"><div class="cp-tab-strip" id="${carouselId}-strip">${spacer}${tabs}${spacer}</div><div class="peek-carousel" id="${carouselId}" onscroll="onCarouselScroll(this)">${panels}</div></div>`;
}

function carouselGoTo(id, idx, animate) {
  if (animate === undefined) animate = true;
  const el = document.getElementById(id);
  if (!el) return;
  const panels = el.querySelectorAll(':scope > .carousel-panel');
  if (!panels[idx]) return;
  el.scrollTo({ left: panels[idx].offsetLeft, behavior: animate ? 'smooth' : 'instant' });
  _updateCarouselNav(id, idx);
}

function _updateCarouselNav(id, idx) {
  const strip = document.getElementById(id + '-strip');
  if (!strip) return;
  const tabs = strip.querySelectorAll('.cp-tab');
  tabs.forEach((btn, i) => btn.classList.toggle('active', i === idx));
  const activeTab = tabs[idx];
  if (activeTab) activeTab.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
}

function initCarousels() {
  document.querySelectorAll('.cp-tab-strip').forEach(strip => {
    const active = strip.querySelector('.cp-tab.active');
    if (active) active.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'instant' });
  });
}

function onCarouselScroll(el) {
  clearTimeout(el._st);
  el._st = setTimeout(() => {
    const panels = Array.from(el.querySelectorAll(':scope > .carousel-panel'));
    if (!panels.length) return;
    const vpCentre = el.scrollLeft + el.offsetWidth / 2;
    let active = 0, minDist = Infinity;
    panels.forEach((p, i) => {
      const dist = Math.abs((p.offsetLeft + p.offsetWidth / 2) - vpCentre);
      if (dist < minDist) { minDist = dist; active = i; }
    });
    _updateCarouselNav(el.id, active);
  }, 30);
}

// ══════════════════════════════════════════════════════════════
//  TXP TASK CARD — brand design, fixed height, colored border
// ══════════════════════════════════════════════════════════════
function buildTxpTaskCard(t, userId, opts={}) {
  const { isAdmin=false, selMode=false, selIds=null } = opts;
  const done = isTaskDone(t.id, userId || t.assignedTo);
  const cat = (t.category||'personal').toLowerCase();
  const cardCat  = `cat-${cat}`;
  const isRoutine = !!(t.templateId || t.repeat);
  const needsApproval = t.approvalRequired && !t.isPersonal;
  const role = isAdmin ? 'admin' : 'intern';
  const clickFn = isAdmin ? `openAdminTaskDetail('${t.id}')` : `openTaskDetail('${t.id}')`;
  const catColor = cat==='office' ? '#3b82f6' : cat==='academic' ? '#059669' : 'var(--accent)';
  const catRgb   = cat==='office' ? '59,130,246' : cat==='academic' ? '5,150,105' : '232,93,38';
  const tagStyle = `background:rgba(${catRgb},.08);color:${catColor};border-color:rgba(${catRgb},.28);`;
  const ptsStyle = `background:rgba(${catRgb},.1);color:${catColor};`;

  if (selMode && selIds) {
    const checked = selIds.has(t.id);
    const assigneeName = INTERNS.find(i=>i.id===t.assignedTo)?.name?.split(' ')[0]||'—';
    return `<div class="txp-card ${cardCat} ${checked?'selected':''}" onclick="toggleAdminSel('${t.id}')">
      <div class="txp-card-check"><div class="txp-checkbox ${checked?'on':''}">${checked?'✓':''}</div></div>
      <div class="txp-card-body">
        <div class="txp-card-title">${sanitize(t.title.length>34?t.title.slice(0,32)+'…':t.title)}</div>
        <div class="txp-card-tags"><span class="txp-tag" style="${tagStyle}"><i data-lucide="user" style="width:9px;height:9px;"></i> ${sanitize(assigneeName)}</span></div>
      </div>
      <div class="txp-card-right">${t.points?`<span class="txp-card-pts" style="${ptsStyle}">+${t.points}</span>`:''}</div>
    </div>`;
  }

  const circleClass = `txp-circle cat-${cat}${done?' done':''}`;
  const completeFn = (done || isAdmin) ? ''
    : needsApproval ? `openApprovalDlg('${t.id}','${userId}')` : `completeTask('${t.id}','${userId}')`;
  const circleInner = done
    ? `<i data-lucide="check" style="width:11px;height:11px;color:${catColor};pointer-events:none;"></i>`
    : needsApproval ? `<i data-lucide="lock" style="width:9px;height:9px;pointer-events:none;color:${catColor};"></i>` : '';

  // Shared tag: visible to admin only, shows count of shared interns
  let sharedTag = '';
  if (isAdmin && t.sharedWith && t.sharedWith.length > 1) {
    sharedTag = `<span class="txp-tag" style="${tagStyle}">Shared ${t.sharedWith.length}+</span>`;
  }

  // Due date: show human-friendly format
  let dueDateTag = '';
  if (t.dueDate) {
    const dd = new Date(t.dueDate + 'T00:00:00');
    const fmt = dd.toLocaleDateString('en-US',{day:'numeric',month:'short'});
    dueDateTag = `<span class="txp-tag" style="${tagStyle}"><i data-lucide="calendar" style="width:9px;height:9px;"></i> ${fmt}</span>`;
  }
  const routineTag = isRoutine ? `<span class="txp-tag" style="${tagStyle}">Repeat</span>` : '';
  const tagsHtml   = [sharedTag, dueDateTag, routineTag].filter(Boolean).join('');

  return `<div class="txp-card ${cardCat} ${done?'done':''}"
    onclick="${clickFn}"
    oncontextmenu="event.preventDefault();showTaskCtxMenu(event,'${t.id}','${role}')"
    data-longpress-id="${t.id}" data-longpress-role="${role}">
    <div class="txp-card-check">
      <div class="${circleClass}" onclick="event.stopPropagation();${completeFn}">${circleInner}</div>
    </div>
    <div class="txp-card-body">
      <div class="txp-card-title ${done?'done':''}">${done?'<s>':''}${sanitize(t.title.length>36?t.title.slice(0,34)+'…':t.title)}${done?'</s>':''}</div>
      ${tagsHtml ? `<div class="txp-card-tags">${tagsHtml}</div>` : ''}
    </div>
    <div class="txp-card-right">
      ${t.points ? `<span class="txp-card-pts" style="${ptsStyle}">+${t.points}</span>` : ''}
      
    </div>
  </div>`;
}
// ══════════════════════════════════════════════════════════
//  SWIPEABLE TABS — real touch-swipe support (fix req 3)
//  Works on any container that has a .swipe-tabs-bar inside.
//  Detecting left/right swipe cycles through the tab buttons.
// ══════════════════════════════════════════════════════════
(function initSwipeTabs() {
  let _sx = 0, _sy = 0, _el = null;
  const MIN_DIST = 45;   // px to count as a swipe
  const MAX_VERT = 60;   // max vertical drift allowed

  function _animTabContent(bar, dir) {
    // Find the content area sibling/parent of this tab bar and animate it
    requestAnimationFrame(() => {
      const parent = bar.parentElement;
      if (!parent) return;
      // Try to find a direct content div after the bar
      const panels = parent.querySelectorAll(':scope > div:not(.swipe-tabs-bar), :scope > .swipe-tab-content');
      const target = panels[panels.length - 1] || parent.nextElementSibling;
      if (!target) return;
      const cls = dir === 'left' ? 'swipe-tab-anim-left' : 'swipe-tab-anim-right';
      target.classList.remove('swipe-tab-anim-left','swipe-tab-anim-right');
      void target.offsetWidth; // reflow
      target.classList.add(cls);
    });
  }

  function findTabBar(target) {
    let el = target;
    while (el && el !== document.body) {
      const bar = el.querySelector?.(':scope > .swipe-tabs-bar, :scope > .dash-tab-nav')
        || el.closest?.('.swipe-tabs-bar, .dash-tab-nav');
      if (bar) return bar;
      if (el.parentElement) {
        const sibling = el.parentElement.querySelector('.swipe-tabs-bar, .dash-tab-nav');
        if (sibling) return sibling;
      }
      el = el.parentElement;
    }
    return null;
  }

  document.addEventListener('touchstart', (e) => {
    _sx = e.touches[0].clientX;
    _sy = e.touches[0].clientY;
    _el = findTabBar(e.target);
  }, { passive: true });

  document.addEventListener('touchend', (e) => {
    if (!_el) return;
    const dx = e.changedTouches[0].clientX - _sx;
    const dy = e.changedTouches[0].clientY - _sy;
    if (Math.abs(dy) > MAX_VERT || Math.abs(dx) < MIN_DIST) return;

    const btns = Array.from(_el.querySelectorAll('.swipe-tab-btn, .dash-tab-pill'));
    if (!btns.length) return;
    const activeIdx = btns.findIndex(b => b.classList.contains('active'));
    const current = activeIdx === -1 ? 0 : activeIdx;

    if (dx < 0) {
      // Swipe LEFT → next tab
      if (current < btns.length - 1) {
        btns[current + 1].click();
        _animTabContent(_el, 'left');
      }
    } else {
      // Swipe RIGHT → previous tab
      if (current > 0) {
        btns[current - 1].click();
        _animTabContent(_el, 'right');
      }
    }
    _el = null;
  }, { passive: true });
})();

// ══════════════════════════════════════════════════════════════
//  V-NOTCH NAV BAR — Precise clip-path path() generator
//
//  Draws a rounded-rectangle outline with a SHARP V cutout at
//  the exact top-center using only MoveTo + LineTo (no arcs in
//  the notch itself). Corner arcs use quadratic Bézier (Q).
//
//  V geometry (90° tip):
//    V_HW    = 38px  → half-width of V opening at top of bar
//    V_DEPTH = 38px  → depth of V tip below top edge
//    angle at tip    = 2 × atan(V_HW / V_DEPTH) = 90°
//
// ══════════════════════════════════════════════════════════════
//  V-NOTCH NAVIGATION (DISABLED - NOW USING FLAT MODERN DESIGN)
// ══════════════════════════════════════════════════════════════
//  This function is no longer needed as we've switched to a flat
//  modern bottom navigation design without the V-notch.
//  Keeping the code here for reference but commented out.
// ══════════════════════════════════════════════════════════════

/*
(function initVNotchNav() {

  const NAV_H   = 68;  // nav bar height (matches CSS height: 68px)
  const NAV_R   = 20;  // corner radius  (matches CSS border-radius: 20px)
  const V_HW    = 38;  // V half-width at the top edge (px)
  const V_DEPTH = 38;  // depth of V tip from top edge (px) — equal → 90° angle

  function buildVPath(W) {
    const h  = NAV_H;
    const r  = NAV_R;
    const hw = V_HW;
    const vd = V_DEPTH;
    const cx = W / 2;

    if (W < hw * 2 + r * 2 + 8) return null; // sanity guard

    const d = [
      'M ' + r + ' ' + h,                          // bottom-left after corner
      'Q 0 ' + h + ' 0 ' + (h - r),               // bottom-left arc
      'L 0 ' + r,                                   // up left edge
      'Q 0 0 ' + r + ' 0',                          // top-left arc
      'L ' + (cx - hw) + ' 0',                      // top edge → left V shoulder
      'L ' + cx + ' ' + vd,                         // ▼ LineTo V tip  (sharp!)
      'L ' + (cx + hw) + ' 0',                      // LineTo right V shoulder
      'L ' + (W - r) + ' 0',                        // top edge → right
      'Q ' + W + ' 0 ' + W + ' ' + r,              // top-right arc
      'L ' + W + ' ' + (h - r),                     // down right edge
      'Q ' + W + ' ' + h + ' ' + (W - r) + ' ' + h,// bottom-right arc
      'Z'
    ].join(' ');

    return 'path("' + d + '")';
  }

  function applyVNotch() {
    var W = Math.max(window.innerWidth - 16, 100);
    var clipPath = buildVPath(W);
    if (!clipPath) return;

    var ids = ['mobBottomNav', 'mobAdminBottomNav'];
    for (var i = 0; i < ids.length; i++) {
      var el = document.getElementById(ids[i]);
      if (el) el.style.setProperty('--nav-clip-path', clipPath);
    }
  }

  // Run immediately — nav elements are already in the DOM
  applyVNotch();

  // Re-run on resize (orientation flip, split-screen, browser chrome resize)
  window.addEventListener('resize', applyVNotch, { passive: true });

})();
*/

